/* ÇEVİRİ ar · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ar","olay",{
"OLAYLAR:1299-01:0":{"b": ["تأسيس الإمارة العثمانية", "9f0b7c0a"], "d": ["يُعدّ شروع عثمان غازي، من قبيلة قايي، في التحرك مستقلًّا في ناحية سوغوت ودومانيج البداية التقليدية لتأسيس الدولة العثمانية، بينما يرى بعض المؤرخين أن انتصار بافيوس عام 1302 هو نقطة التحول الحقيقية. وقد جمعت الإمارة القوة بسرعة بفضل غارات الغزو انطلاقًا من موقعها في الثغر البيزنطي. وفي هذه البيئة التي كان إرث السلاجقة يتفكك فيها، جمع عثمان غازي حوله الأخيّة والغزاة والتركمان الرحّل؛ ويُعدّ الرباط الذي أقامه مع الشيخ أده بالي أساس المشروعية المعنوية للإمارة. الأماكن الأخرى التي انضمت في التاريخ نفسه: إينه غول، يارحصار.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["فتح بورصة", "98c727fa"], "d": ["استسلمت بورصة، التي ظلّت سنوات طويلة تحت الحصار، لأورخان غازي الذي أدار المرحلة الأخيرة من الحصار؛ واتُّخذت المدينة أول عاصمة كبرى للإمارة. ويُروى أن نبأ الفتح بُلّغ إلى عثمان غازي وهو على فراش الموت، وأنه دُفن في بورصة بحسب وصيته. وسرعان ما زُوّدت المدينة بالمساجد والعمائر والمدارس، فصارت نموذجًا للعمران العثماني المبكر.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["فتح إزنيق", "a846a811"], "d": ["استسلمت إزنيق (نيقية)، وهي من أهم مراكز البيزنطيين في الأناضول، لأورخان غازي بعد أن فقدت أمل المقاومة إثر انتصار بيلكانون عام 1329. وأُنشئت فيها أول مدرسة عثمانية، وبدأ علماء مثل داود القيصري التدريس فيها؛ وصارت المدينة مركز العلم في العصر المبكر. وحُوّلت كنيسة آيا صوفيا إلى مسجد، فكانت مثالًا مبكرًا على تقليد الفتح.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["فتح إزميت", "06a35035"], "d": ["بسقوط إزميت (نيقوميديا) دخل آخر حصن مهم للبيزنطيين في الجانب الآسيوي تحت الإدارة العثمانية؛ وصارت شبه جزيرة كوجه إيلي كلها، حتى الساحل المقابل لالقسطنطينية، أرضًا عثمانية. وهكذا سيطرت الإمارة على كامل سواحل مرمرة الجنوبية والشرقية، وهيّأت البنية التحتية للعبور إلى الروملي.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["قلعة جمبي — العبور إلى الروملي", "c2f0a07d"], "d": ["كان سليمان باشا، ابن أورخان غازي، قد اتخذ قلعة جمبي، التي أُعطيت في الحرب الأهلية البيزنطية، قاعدة له عام 1352؛ وبعد الزلزال الكبير الذي دمّر غاليبولي في مارس 1354 حُصّنت القلاع التي أُخليت بسرعة، فتحولت شبه الجزيرة إلى رأس جسر عثماني دائم. وهذه الخطوة، التي دعمها إسكان السكان التركمان المنقولين من الأناضول، هي بداية الوجود العثماني في القارة الأوروبية الذي سيمتد أكثر من 550 عامًا.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["فتح أدرنة", "2f54ebb0"], "d": ["حدّد الاستيلاء على أدرنة (أدريانوبل)، المدينة المفتاحية في تراقيا، القاعدة الرئيسة للفتوحات في البلقان واتجاهها؛ وتاريخ الفتح مختلف فيه في المصادر بين 1361 و1369. وبعد فترة قصيرة جُعلت المدينة عاصمة، معلنةً انتقال مركز ثقل الدولة إلى الروملي؛ وظلت دار الملك نحو 90 عامًا حتى فتح القسطنطينية.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["اعتلاء مراد الأول العرش", "f8d48a26"], "d": ["نقل مراد الأول (خداوندكار)، الذي تولى العرش بوفاة أورخان غازي، الدولة في سلطنته التي دامت 27 عامًا من إمارة ثغرية إلى هيكل إمبراطورية. فوُضع أساس الجيش الإنكشاري بنظام البنجيك، وعُمّم نظام التيمار، وأُنشئت بكلربكية الروملي، وقوي نظام الوزارة. وصارت الفتوحات في البلقان في عهده سياسة دولة منتظمة.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["معركة كوسوفو الأولى — استشهاد مراد الأول", "10b8ddc9"], "d": ["هُزم التحالف البلقاني بقيادة الأمير لازار هزيمة حاسمة في سهل كوسوفو؛ ودخلت صربيا تحت السيادة العثمانية العليا. وطعن النبيلُ الصربي ميلوش أوبيليتش السلطانَ مراد الأول بخنجر وهو يتجول في ساحة المعركة فاستشهد — وهو السلطان العثماني الوحيد الذي مات في ساحة القتال. وأُجلس يلدريم بايزيد مكانه في المعسكر؛ وخُنق أخوه يعقوب جلبي، وكان ذلك من أولى الأمثلة المعروفة لتطبيق قتل الإخوة.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["انتصار نيكوبوليس", "75716e96"], "d": ["هُزم الجيش الصليبي الكبير، الذي اجتمع بدعوة من الملك المجري سيغيسموند وشاركت فيه فرسان فرنسيون وبورغونديون، هزيمة ساحقة أمام نيكوبوليس على ضفاف الدانوب على يد يلدريم بايزيد. وثبّت الانتصار السيادة العثمانية على بلغاريا؛ ولم تُنظَّم في أوروبا حملة صليبية كبرى طوال جيل كامل.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["معركة أنقرة — بداية فترة الفتنة", "b4a99d96"], "d": ["في الهزيمة الثقيلة التي لحقت بالعثمانيين أمام جيش تيمور في سهل تشوبوق وقع يلدريم بايزيد في الأسر، وتوفي في الأسر بعد بضعة أشهر. وأعاد تيمور إحياء الإمارات الأناضولية؛ وتفتتت الأراضي العثمانية بين أبناء بايزيد، وبدأ صراع على العرش دام 11 عامًا (فترة الفتنة). وقد ترسخت أهمية البنية المركزية في الذاكرة العثمانية في هذه الفترة، وهي أشد أزمة عاشتها الدولة منذ تأسيسها. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: داتشا، مرمريس، فتحية (ماكري)، سوكه، كوتاهية، أفيون، إسبارطة، مانيسا، آيدين، دنيزلي، موغلا، أنطاليا، قونية، قرمان، قيصري، قسطموني، بارتن، صفرانبولو، سامسون، سيواس، ملطية، بيشهر، سيفريحصار، قيرشهير، تشوروم، تشانقري، ينيشهير (بورصة)، إينه غول، قلعة أيدوس، جيويه، كوبروحصار (ينيشهير)، مرمرجق، آق حصار (باموقوفا)، مكجة، كستل، أولوباد، هارمانقايا، آق يازي، جزيرة إمرالي، قنديرة، مودانيا، يالوفا، قره مورسل، أرموتلو، جمليك (كيوس)، سوغوت، بيلجك، إسكيشهير، بورصة، إزنيق، إزميت، باليكسير، جناق قلعة، برغمة، أماسية، طوقات، جورلو، لولة برغاز، مالقرة، كشان، إبسالا، كيليد بحر، جرمن، إسكي زاغرا (ستارا زاغورا)، تتارباظارجق، إحتيمان، كوستندل، بتريتش، نيفروكوب (غوتسه ديلتشيف)، دراما، غاليبولي، جمبي، أدرنة، ديديموتيخون، قرق كليسة، تكيرداغ، فيليبه، صوفيا، نيش، فيدين، ترنوفو، وارنا، شومنو، سيليستر، نيكوبوليس، روسجق، سلانيك، سيريس، قوالة، أسكوب، مناستر، أوهريد، ينيشهير (لاريسا)، تيرهالا، إزدين (لاميا)، بليفن، غومولجينة، بيغا، دومانيج، قولاجة حصار، قره جة حصار، يارحصار، ديمبوس، كيتي (كته)، لفكه (عثمانلي)، لبلبجي حصار، قره جبوش، قره تكين، أبسو (هيبسو)، أدرانوس (أورهانلي)، بيلكانون (إسكي حصار)، غبزه، هريكه، سمندرة، كرماستي (مصطفى كمال باشا)، ميخاليتش (قره جابي)، كوستنجة، غولياز (أبولونيا).", "d34e55d5"]},
"OLAYLAR:1413-07:0":{"b": ["جلبي محمد يعيد توحيد الدولة", "03413dfd"], "d": ["وحّد محمد الأول أراضي الدولة تحت إدارة واحدة بعد أن هزم موسى جلبي في تشامورلو في الحساب الأخير بين الإخوة؛ ولذلك يُعدّ «المؤسس الثاني للدولة». فأُصلحت البنية الحكومية التي تآكلت في أثناء الفتنة، وتوازنت العلاقات مع الإمارات الأناضولية، واتُّبعت في الروملي سياسة سلم حذرة.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["ثورة الشيخ بدر الدين", "e0a072ca"], "d": ["اندلعت الحركة الدينية الاجتماعية التي نشأت حول الشيخ بدر الدين، الفقيه والمتصوف الكبير الذي تولى قضاء العسكر في فترة الفتنة، في وقت واحد مع ثورتي بوركلوجه مصطفى في قره بورون وطورلاق كمال في مانيسا. وقُمعت الثورات بالدماء؛ وأُلقي القبض على بدر الدين في دلي أورمان وأُعدم في سيريس. وقد ترك الحدث أثرًا عميقًا في الأدب وكتابة التاريخ بوصفه أقدم انتفاضة اجتماعية مهدوية كبرى في التاريخ العثماني.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["انتصار وارنا", "f739eedc"], "d": ["أُبيد في وارنا على يد مراد الثاني، الذي عاد إلى رأس الجيش وهو متنازل عن العرش، الجيشُ الصليبي المجري البولندي الذي نقض معاهدة سيجد وتقدم جنوبًا؛ وقُتل الملك الشاب لاديسلاس الثالث في ساحة المعركة. وأزال الانتصار آخر فرصة كبرى للتدخل الخارجي الرامي إلى تصفية الوجود العثماني في البلقان، وأمّن الطريق إلى فتح القسطنطينية.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["معركة كوسوفو الثانية", "ebe0b662"], "d": ["هُزم جيش يانوش هونيادي، الذي أراد الثأر لوارنا، هزيمة حاسمة على يد مراد الثاني في معركة شاقة دامت ثلاثة أيام. وهي آخر معركة ميدانية كبرى خاضها الصليبيون ضد العثمانيين في البلقان؛ وبهذا الانتصار استقرت السيادة العثمانية جنوب الدانوب استقرارًا لا رجعة فيه.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["فتح القسطنطينية", "583d5e3e"], "d": ["بعد حصار دام أربعة وخمسين يومًا (6 أبريل – 29 مايو 1453) دخل الجيش العثماني المدينة صباح 29 مايو بعد أن تجاوز الأسوار؛ وقُتل الإمبراطور الأخير قسطنطين الحادي عشر في القتال، وطُويت صفحة الإمبراطورية الرومانية الشرقية التي دامت 1100 عام. ونال السلطان الشاب لقب «الفاتح»، وجعل المدينة عاصمة وحوّل آيا صوفيا إلى مسجد؛ وسرعان ما دبّت الحياة في المدينة بالإسكان والعمران. ويُعدّ صبّ المدافع العملاقة ونقل السفن برًّا ونظام الحصار أمام الأسوار ذروة الهندسة العسكرية في العصر. ويُعدّ الفتح في الكتابة التاريخية الأوروبية من التواريخ الرمزية لنهاية العصور الوسطى.", "3664c5fe"]},
"OLAYLAR:1461-08-15:0":{"b": ["فتح طرابزون", "15f52403"], "d": ["استسلمت إمبراطورية طرابزون الرومية في ختام حملة البحر الأسود الشاقة التي قادها الفاتح بالجيش والأسطول في آن واحد؛ وبتصفية آخر بقايا العالم البيزنطي في الأناضول دخل الساحل الجنوبي للبحر الأسود برمّته تحت السيادة العثمانية. وقد عزّز إنهاء أسرة كومنينوس دعوى الفاتح بأنه «سلطان البحرين والبرّين». الأماكن الأخرى التي انضمت في التاريخ نفسه: غيرسون، ريزه.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["الفتح النهائي لسيلفكه — كسر آخر مقاومة للقرمانيين", "d988bee4"], "d": ["كانت قلعة سيلفكه قد استسلمت مرة لقدك أحمد باشا عام 1472، لكن قاسم بك القرماني استعادها في السنة نفسها بمساعدة الأسطول الصليبي في البحر المتوسط. وبعد انتصار أوتلوق بيلي كلّف الفاتح ابنه وقدك أحمد باشا بالاستيلاء على المنطقة نهائيًّا؛ فأُشعلت مخازن البارود بمساعدة المدفعية العثمانية القديمة وسقطت القلعة سريعًا. وهكذا كُسرت آخر مقاومة للقرمانيين في جبال طاشلي وإيچ إيل؛ وسيكتمل القضاء على الإمارة عام 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["معركة أوتلوق بيلي", "42c7194e"], "d": ["هُزم أوزون حسن، حاكم آق قويونلو الذي صار قوة كبرى في الشرق وتحالف مع البندقية، هزيمة ثقيلة في أوتلوق بيلي أمام جيش الفاتح المجهز بالأسلحة النارية. وأكد الانتصار التفوق العثماني في الأناضول؛ وكان كذلك دليلًا مبكرًا على تفوق الجيش المركزي الذي يستخدم المدافع والبنادق على الجيش التقليدي.", "9c59ac50"]},
"OLAYLAR:1475-06-06:0":{"b": ["دخول القرم في الحماية العثمانية", "44e3f7c8"], "d": ["فتح الأسطول بقيادة قدك أحمد باشا مدن الساحل الجنوبي للقرم، وفي مقدمتها كفة التي كانت بيد الجنوية؛ وجُعلت هذه السواحل سناجق عثمانية مباشرة. أما خانية القرم فصارت مع منكلي كراي دولة تابعة ذات امتياز تعترف بالسيادة العثمانية العليا، وظلت ثلاثة قرون حجر الزاوية في السياسة الشمالية؛ وصار البحر الأسود فعليًّا بحيرة عثمانية داخلية. الأماكن الأخرى التي انضمت في التاريخ نفسه: باغجه سراي، كرتش، آزاق.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["وفاة الفاتح — قضية الأمير جم", "190ecf01"], "d": ["تولى بايزيد الثاني العرش إثر وفاة الفاتح المفاجئة في طريق الحملة؛ وأقام أخوه الأمير جم، مدّعيًا السلطنة، الخطبة باسمه وضرب النقود في بورصة. ولما هُزم لجأ أولًا إلى المماليك ثم إلى فرسان رودس؛ وصار جم، في يد الفرسان والبابوية، ورقة مساومة في الدبلوماسية الأوروبية، وتوفي في نابولي عام 1495. وقد أجبرت هذه القضية السياسة الخارجية العثمانية على التزام الحذر خمس عشرة سنة.", "7e488d7b"]},
"OLAYLAR:1514-08:0":{"b": ["انتصار جالديران", "fea64ebb"], "d": ["أراد السلطان ياووز سليم أن يحسم من جذوره الخطر الذي أحدثته الدعاية الصفوية في الأناضول، فهزم جيش الشاه إسماعيل هزيمة ثقيلة في سهل جالديران بتفوق المدافع والبنادق. ودُخلت تبريز؛ وضُمّت الأناضول الشرقية والجنوبية الشرقية وخط الموصل – ديار بكر إلى الإدارة العثمانية. وبفضل جهد إدريس البدليسي ارتبطت الإمارات الكردية بالعثمانيين، فأُرسي إطار الحدود الشرقية الذي سيدوم قرونًا.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["انتصار مرج دابق", "07d254d3"], "d": ["شُتّت الجيش المملوكي في مرج دابق شمال حلب في غضون ساعات قليلة؛ وقُتل السلطان المسن قانصوه الغوري في أثناء المعركة. وبهذا الانتصار الذي فتح أبواب حلب ودمشق على مصراعيها انتقلت سوريا ولبنان وفلسطين إلى الإدارة العثمانية؛ وانفتح الطريق إلى حملة مصر التي ستنهي الدولة المملوكية.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["الريدانية — فتح مصر والخلافة", "caf378d6"], "d": ["اجتاز الجيش العثماني صحراء سيناء بسرعة، وخرق خط دفاع طومان باي في الريدانية، ودخل القاهرة؛ وقُبض على طومان باي الذي واصل المقاومة وأُعدم، وطُويت صفحة الدولة المملوكية. ودخلت مصر والحجاز والمدن المقدسة تحت الإدارة العثمانية؛ ونُقل الخليفة العباسي والأمانات المقدسة إلى إسطنبول. وبانتقال الخلافة إلى الأسرة العثمانية تولى السلاطين دعوى زعامة العالم الإسلامي؛ كما وفّرت السيطرة على طريق التوابل إيرادات كبيرة للإمبراطورية. الأماكن الأخرى التي انضمت في التاريخ نفسه: عكا، معان، صيدا، الكرك.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["اعتلاء سليمان القانوني العرش", "f6512269"], "d": ["تُعدّ سلطنة سليمان الأول، الذي تولى العرش بوفاة ياووز بوصفه الابن الذكر الوحيد، وقد دامت 46 عامًا، ذروة الإمبراطورية سياسيًّا وعسكريًّا وقانونيًّا وثقافيًّا. وقد أكسبته القوانين نامه التي نظّمت القانون العرفي لقب «القانوني»؛ وعُرف في الغرب باسم «العظيم» (Magnificent). وآثار المعمار سنان، والعصر الذهبي للأدب الديواني، وتفوق الأسطول في البحر المتوسط هي رموز هذه الحقبة.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["فتح بلغراد", "59ef5cec"], "d": ["سقطت بلغراد، التي لم يستطع الفاتح أخذها عام 1456 وكانت تُعدّ «مفتاح أوروبا الوسطى»، بحصار عند ملتقى الدانوب والسافا في حملة القانوني الأولى. وانهار خط الدفاع الجنوبي للمجر؛ وبهذا الفتح انفتح باب حملة أوروبا الوسطى التي امتدت إلى موهاج بعد خمس سنوات وإلى ضم بودين بعد عشرين سنة.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["فتح رودس", "807bbb1e"], "d": ["استسلمت رودس، قاعدة فرسان القديس يوحنا الذين كانوا يهددون طرق شرق البحر المتوسط وطريق الحج، بالاتفاق بعد حصار دموي دام أشهرًا؛ وسُمح للفرسان بمغادرة الجزيرة بحرية (واستقروا لاحقًا في مالطة). وتأمّنت سواحل الأناضول، ودخل خط البحر بين إسطنبول ومصر تحت السيطرة العثمانية دون انقطاع.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["معركة موهاج", "f3418b0d"], "d": ["أُبيد الجيش المجري في سهل موهاج في نحو ساعتين بنيران المدافع وتفوق المناورة؛ وقُتل الملك لايوش الثاني في المستنقع وهو يفرّ. وأنهت موهاج، وهي من أسرع المعارك الميدانية الكبرى حسمًا في التاريخ العثماني، المملكة المجرية المستقلة فعليًّا، وفتحت عصر التنافس العثماني الهابسبورغي في أوروبا الوسطى.", "48967894"]},
"OLAYLAR:1529-09:0":{"b": ["حصار فيينا الأول", "dc49ea4f"], "d": ["حاصر الجيش العثماني فيينا في حملة نُظّمت ضد استيلاء الهابسبورغ على العرش المجري؛ ورُفع الحصار بعد ثلاثة أسابيع بسبب ترك المدافع الثقيلة في الطريق وحلول الشتاء مبكرًا وصعوبة التموين. ورغم أن المدينة لم تؤخذ، بقي النفوذ العثماني على المجر؛ وأشارت أسوار فيينا إلى حد الوصول اللوجستي للإمبراطورية في أوروبا الوسطى.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["فتح بغداد — حملة العراقين", "897092c3"], "d": ["في الحملة التي نُظّمت على «العراقين» (العراق العربي والعراق العجمي) دُخلت تبريز أولًا ثم بغداد دون قتال؛ وقد أكسب الاستيلاء على عاصمة العباسيين القديمة السلطان العثماني مكانة كبيرة في العالم الإسلامي. وأُحيي ضريح الإمام الأعظم أبي حنيفة؛ وبانضمام بغداد والبصرة بلغت الأراضي العثمانية الخليج العربي. الأماكن الأخرى التي انضمت في التاريخ نفسه: كركوك، كربلاء.", "f3f80434"]},
"OLAYLAR:1538-09:0":{"b": ["انتصار بريفيزة البحري", "30dc0f97"], "d": ["شُتّت الأسطول الصليبي الذي تشكّل بقيادة البابا، رغم تفوقه العددي، أمام بريفيزة بفضل تكتيك بربروس الذي أحسن استخدام الريح والساحل؛ وترك أندريا دوريا ساحة المعركة. وأرسى الانتصار تفوقًا بحريًّا عثمانيًّا لا منازع فيه في البحر المتوسط دام نحو 33 عامًا؛ وهو التاريخ الرمزي ليوم البحرية في التقليد البحري التركي. الأماكن الأخرى التي انضمت في التاريخ نفسه: عدن، بندر.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["ضم بودين — المجر ولاية عثمانية", "db53b244"], "d": ["خرج القانوني في حملة إثر حصار الهابسبورغ لبودين، وبعد أن أنقذ المدينة ضمّ وسط المجر إلى الإدارة العثمانية المباشرة وأنشأ بكلربكية بودين، بينما جُعلت ترانسلفانيا إمارة ذاتية الحكم تابعة للعثمانيين. واستمر هذا الترتيب الذي قُسمت به المجر إلى ثلاثة أقسام نحو 150 عامًا، وشكّل الهيكل الإداري الدائم للعثمانيين في أوروبا الوسطى.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["معاهدة أماسية", "a5afe0d1"], "d": ["هي أول معاهدة سلام رسمية أنهت الحروب العثمانية الصفوية التي دامت سنوات طويلة. فبقيت بغداد والعراق عند العثمانيين، وتم الاعتراف المتبادل لأول مرة بحدود الأناضول الشرقية؛ والتزم الصفويون بوقف الدعاية الشيعية في الأراضي العثمانية، والتزم العثمانيون بأمن مرور الحجاج الإيرانيين. وصارت المعاهدة أول مثال على الإطار القانوني للعلاقات بين الدولتين.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["سيكتوار — وفاة القانوني", "e2917ed2"], "d": ["توفي القانوني، وكان في الثانية والسبعين من عمره، في خيمته قبل سقوط قلعة سيكتوار التي حاصرها في حملته الثالثة عشرة بساعات قليلة؛ وأخفى صوقوللو محمد باشا الوفاة أسابيع كي لا ينفرط عقد الجيش. وأُخذت القلعة، لكن الدولة فقدت أطول سلاطينها حكمًا وأعظمهم مجدًا؛ وتولى العرش ابنه سليم الثاني، وبدأ ثقل كبار الوزراء في إدارة الدولة يزداد.", "62c468a1"]},
"OLAYLAR:1571-08:0":{"b": ["فتح قبرص", "e364a2b3"], "d": ["أُنزلت القوات عام 1570 في قبرص الخاضعة للبندقية؛ وسقطت نيقوسيا سريعًا، أما ماغوزا فلم تستسلم إلا في أغسطس 1571 بعد حصار دام أحد عشر شهرًا. ونُظّمت الجزيرة، وهي حيوية لأمن طرق التجارة والحج في شرق البحر المتوسط، بكلربكية، وأُسكن فيها سكان من الأناضول؛ وكان الفتح كذلك سببًا للتحالف الصليبي الكبير الذي بلغ إينه بختي.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["هزيمة إينه بختي (ليبانتو)", "6a1d44a9"], "d": ["أدرك الأسطول الصليبي، الذي اتحد إثر فتح قبرص، الأسطول العثماني في خليج إينه بختي فأباد معظمه؛ واستشهد قبودان باشا مؤذن زاده علي باشا، ولم ينجُ إلا أسطول أولوج علي. وبعد الكارثة عيّن الصدر الأعظم صوقوللو محمد باشا أولوج علي باشا قبودان باشا وكلّفه بجمع الأسطول المبعثر، وبدأ بناء أسطول جديد في جميع الترسانات من إسطنبول إلى آلانيا؛ غير أن التفوق المطلق في البحر المتوسط اهتزّ نفسيًّا.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["معركة كرستس (هاچوفا)", "da308ec5"], "d": ["في أكبر معركة ميدانية في الحرب الطويلة (1593–1606)، استعاد الجيش الذي كان محمد الثالث بنفسه على رأسه تماسكه بتوجيه من خوجة سعد الدين أفندي في اللحظة التي أوشك فيها على التفكك، فهزم الجيش الهابسبورغي. وتُعدّ آخر معركة ميدانية كلاسيكية كبرى انتصر فيها العثمانيون؛ غير أن عدم تغييرها مجرى الحرب عُدّ علامة على التآكل في النظام العسكري.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["معاهدة زيتفاتوروك", "39c01142"], "d": ["بموجب المعاهدة التي أنهت الحرب المنهكة التي دامت ثلاث عشرة سنة، عُدّ حاكم الهابسبورغ لأول مرة بصفة «الإمبراطور الروماني» نظيرًا للسلطان، وأُلغيت الجزية السنوية. وكان فقدان الأراضي ضئيلًا جدًّا؛ لكن هذا التغير في اللغة الدبلوماسية يُقرأ رمزًا لانتهاء دعوى العثمانيين التفوق المطلق على أوروبا.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["معاهدة قصر شيرين", "c1acf3af"], "d": ["أنهت المعاهدة، التي وُقّعت بعد استعادة مراد الرابع بغداد (1638)، الحروب العثمانية الصفوية التي دامت أكثر من مئة عام. فبقيت بغداد والعراق نهائيًّا عند العثمانيين، وتُركت يريفان للصفويين؛ وصار الخط المرسوم، مع تعديلات طفيفة، أساس الحدود التركية الإيرانية الحالية، وهو يُعدّ من أطول حدود العالم عمرًا. وتركت المعاهدة بدره وجصان ومندلي ودرتنك ودرنه للعثمانيين؛ وكان من المقرر هدم قلعة زنجير الحدودية، وأن تبقى القرى الواقعة غربها للعثمانيين والواقعة شرقها لإيران. وبقي محيط قلعة زالم قرب شهرزور وقلعة قزل جه قلعة عند العثمانيين، وبقيت أورامان ومهربان عند إيران؛ وكان من المقرر أن يُهدم الطرفان قلاع قطور وماكو ومغازبرد.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["اكتمال فتح كريت", "e0d85604"], "d": ["انتهى حصار كانديا، المشهد الأخير من حرب كريت التي بدأت عام 1645، بحملة فاضل أحمد باشا الحازمة التي دامت ثلاث سنوات؛ وسلّم القائد البندقي موروزيني المدينة بمعاهدة. وسُجّل الصراع الذي دام نحو ربع قرن بوصفه أطول حصار في التاريخ العثماني؛ ودخلت آخر قلاع اللاتين الكبرى في شرق البحر المتوسط تحت الإدارة العثمانية. وبقيت ثلاث قلاع صخرية صغيرة على الساحل الشمالي للجزيرة — سودا وسبينالونغا وغرامبوسا — بيد البندقية؛ ولأنها مقامة على جزر صغيرة منفصلة لا يمكن إظهارها على الخريطة منفصلة عن بقية كريت.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["معاهدة بوجاش — أوسع الحدود", "b17b6e5a"], "d": ["ضُمّت بودوليا إلى العثمانيين بمعاهدة بوجاش التي وُقّعت بعد فتح كامانيتسا في حملة بولندا، ووُضع جزء من أوكرانيا تحت الحماية. وبلغت الإمبراطورية بذلك أوسع حدودها في أوروبا؛ وتُعدّ هذه النقطة ذروة عصر التوسع وحلقته الأخيرة في آن واحد.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["هزيمة حصار فيينا الثاني", "7d889252"], "d": ["آل حصار فيينا الذي قام به مرزيفونلو قره مصطفى باشا ودام شهرين إلى هزيمة بضربة مفاجئة أنزلها ملك بولندا يان سوبيسكي من تلال كالنبرغ؛ وانسحب الجيش تاركًا أثقاله، وأُعدم مرزيفونلو في بلغراد. ودامت الحرب ست عشرة سنة مع الحلف المقدس الذي تشكّل إثر الانتصار؛ وتُذكر هذه الهزيمة بوصفها لحظة بداية التراجع الكبير في التاريخ العثماني.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["فتح قلعة غرامبوسا — إحدى القلاع الصخرية التي بقيت بيد البندقية في كريت", "3ddf9eeb"], "d": ["رغم أن فتح كريت عُدّ مكتملًا إلى حد كبير بتسليم كانديا عام 1669، ظلت غرامبوسا، القلعة الصخرية الجزيرية في الطرف الشمالي الغربي للجزيرة، بيد البندقية ثلاثًا وعشرين سنة أخرى. وبالاستيلاء عليها عام 1692 طُهّرت إحدى البقايا البندقية الثلاث في كريت؛ أما سودا وسبينالونغا فكان عليهما انتظار حملة المورة عام 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["معاهدة كارلوفيتس — أول خسارة كبرى للأراضي", "8f7e2546"], "d": ["بموجب كارلوفيتس التي أنهت حروب الحلف المقدس التي دامت ست عشرة سنة، تُركت المجر وترانسلفانيا للنمسا، وبودوليا لبولندا، والمورة وسواحل دالماسيا للبندقية. وللمرة الأولى في التاريخ العثماني كانت أراضٍ بهذا الحجم تخرج من اليد على طاولة المفاوضات وبصورة دائمة؛ وتُعدّ المعاهدة وثيقة بداية عصر جديد انتقلت فيه الإمبراطورية إلى موقف الدفاع أمام أوروبا، كما أنها نقطة تحول في تاريخ الدبلوماسية العثمانية.", "54bb2eee"]},
"OLAYLAR:1711-07-19:0":{"b": ["انتصار بروت", "2583572f"], "d": ["في الحرب التي نشبت بسبب مسألة ملك السويد الذي لجأ إلى العثمانيين بعد هزيمة بولتافا، حوصر جيش القيصر بطرس الأول على ضفاف بروت واضطر إلى الاستسلام. وبالمعاهدة الموقعة استُعيدت آزاق؛ أما عدم إبادة الجيش وإطلاق سراح القيصر فقد دخل التاريخ قرارًا لا يزال موضع جدل منذ ذلك اليوم.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["فتح قلعتي سودا وسبينالونغا — محو آخر أثر بندقي في كريت", "7261f7ba"], "d": ["بعد ثلاث وعشرين سنة من سقوط غرامبوسا عام 1692، فُتحت قلعتا سودا وسبينالونغا، آخر معقلين للبندقية في كريت، بفرع جانبي من حملة المورة. وهكذا اكتمل فتح كريت الذي بدأ عام 1645، بعد ست وأربعين سنة، حتى آخر شبر من الجزيرة.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["ثورة باترونا خليل", "100941a4"], "d": ["تحوّل الغضب من الفشل على الجبهة الإيرانية والضرائب وترف محيط القصر إلى انتفاضة كبرى بقيادة باترونا خليل، حلّاق الحمّام. فقُتل الصدر الأعظم إبراهيم باشا، وخُلع أحمد الثالث عن العرش، وانتهى عصر اللالة؛ وأظهر تحكم الثوار في المدينة أشهرًا هشاشة السلطة المركزية بصورة لافتة.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["معاهدة بلغراد — استرداد بلغراد وسمندرة وشمال صربيا", "ba7f8e46"], "d": ["في ختام الحرب (1736–1739) التي خيضت على جبهتين ضد النمسا وروسيا، استُردت بلغراد وشمال صربيا؛ وقبلت روسيا نزع سلاح آزاق وعدم الاحتفاظ بأسطول في البحر الأسود. وقد منحت المعاهدة، التي تُعدّ آخر نجاح كبير للدبلوماسية العثمانية وجيشها في القرن الثامن عشر، الإمبراطورية فترة سلم دامت ربع قرن.", "5b399dd2"]},
"OLAYLAR:1770-07-06:0":{"b": ["غارة تشسمه", "840b30bd"], "d": ["أحرق الأسطول الروسي، الذي خرج إلى البحر المتوسط بدعم من الإنجليز، الأسطول العثماني المحتمي بميناء تشسمه بالسفن الحارقة حتى كاد يفنيه تمامًا. وظهرت روسيا لأول مرة قوة بحرية كبرى في البحر المتوسط؛ وكانت الكارثة إحدى الضربات التي حسمت مصير الحرب المؤدية إلى كوتشوك قاينارجه عام 1774، وكشفت الحاجة إلى إصلاح جذري للأسطول.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["معاهدة كوتشوك قاينارجه", "2776dcdb"], "d": ["بمعاهدة كوتشوك قاينارجه، التي أنهت حرب 1768–1774 وتُعدّ من أثقل المعاهدات في التاريخ العثماني، مُنحت خانية القرم «الاستقلال» — وأُنشئت عمليًّا منطقة نفوذ روسية. واستقرت روسيا على ساحل البحر الأسود، وكسبت لسفنها التجارية حق المرور في المضائق وسفارة دائمة في إسطنبول؛ وفتح بند الحماية الغامض على الرعايا الأرثوذكس باب مبررات التدخل في القرن التالي. وللمرة الأولى كانت أرض سكانها مسلمون تخرج من السيادة العثمانية.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["ضم القرم إلى روسيا", "bdf6faa8"], "d": ["ضُمَّت القرم «المستقلة» التي أنشأتها معاهدة كوتشوك قاينارجه (Küçük Kaynarca) إلى روسيا بمنشور من كاترين الثانية، بذريعة الاضطرابات في عهد آخر الخانات شاهين كراي (Şahin Giray). وانتهت الشراكة العثمانية القرمية التي دامت ثلاثة قرون؛ وأزال فقدان السهوب الشمالية العمق الدفاعي لإسطنبول، وبدأ أول موجة كبرى من هجرة عشرات الآلاف من تتار القرم إلى الأراضي العثمانية. وفي هذا اليوم انضمت شبه جزيرة القرم (ألوشتا، كفه/كافا، سوداك، يالطا، بالاكلافا، إنكرمان، مانغوب، عرب‌آت) إلى روسيا؛ كما انتقلت تامان وكوبان إلى روسيا في الضم نفسه (TDV Kırım: 8 نيسان/أبريل 1783 بالتقويم اليولياني = 19 نيسان/أبريل بالتقويم الغريغوري).", "aa59d3e1"]},
"OLAYLAR:1789-04:0":{"b": ["سليم الثالث والنظام الجديد", "d53aec21"], "d": ["أدرك سليم الثالث، الذي اعتلى العرش في أثناء الحرب، أن الهزائم بنيوية، فأطلق برنامج إصلاح شاملًا باسم «النظام الجديد» (نظام جديد): جيش جديد مدرَّب على الطريقة الأوروبية، وخزينة مستقلة تموّله (إيراد جديد)، وتقوية مهندسخانات، وأولى السفارات الدائمة في العواصم الأوروبية. ويُعدّ البرنامج بداية تقليد الإصلاح التركي الحديث؛ غير أنه سينهار عام 1807 بمقاومة الأوجاقات والأعيان.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["تصفية فرسان مالطة — محطة الأسطول الفرنسي في الطريق", "d62f901d"], "d": ["مرّ الأسطول الفرنسي المتجه إلى مصر بمالطة في طريقه؛ فسلّم فرسان القديس يوحنا (مالطة) الجزيرة دون مقاومة تُذكر. وبذلك انتهى آخر معاقل فرسان الطريقة التي طُردت من رودس عام 1522 واستقرت هنا. وستنتقل مالطة بعد سنتين إلى يد إنجلترا، أما نابليون فتوجّه من الجزيرة مباشرة إلى الإسكندرية.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["احتلال نابليون لمصر", "93fede5f"], "d": ["نزل جيش الجنرال بونابرت في الإسكندرية واحتل مصر؛ وكانت هذه الحملة، التي استهدفت طريق إنجلترا إلى الهند، أول هجوم مباشر لقوة أوروبية على أراضي العثمانيين المركزية. وقد كسرت غارة نلسون في أبي قير ودفاع جزار أحمد باشا عن عكا المسيرة الفرنسية؛ وانتهى الاحتلال عام 1801، لكن في الفراغ الذي خلّفه بدأ صعود محمد علي باشا الكافالي وعصر «المسألة الشرقية».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["سند الاتفاق", "cce49ef5"], "d": ["وثيقة وُقّعت بين القصر وأسر الأعيان الأقوياء في الولايات بقيادة أعيان روسجق علمدار مصطفى باشا الذي أجلس محمودًا الثاني على العرش؛ وفيها تعهّد الأعيان بالولاء للسلطان وتقديم الدعم العسكري، واعترفت الدولة في المقابل بوجودهم وحقوقهم. ولأنها أول مثال في التاريخ العثماني على تقييد سلطة السلطان بوثيقة، يعدّها بعض المؤرخين بداية بعيدة للتقليد الدستوري؛ وقد أصبحت عمليًّا بلا أثر في غضون بضعة أشهر.", "2d97fdfe"]},
"OLAYLAR:1821-03-25:0":{"b": ["اندلاع الثورة اليونانية", "a7293715"], "d": ["اندلعت الانتفاضة التي أعدّتها منظمة الفيليكي إتيريا أولًا في الأفلاق، ثم في المورة بثقلها الرئيس؛ وتأخرت الدولة المنشغلة بمسألة تبدلن علي باشا في التدخل الأول. وتحولت الثورة سريعًا إلى قضية دولية بفضل التعاطف اليوناني الشديد في الرأي العام الأوروبي (الفيلهلينية)؛ وهكذا أُشعلت فتيلة أول حركة استقلال ناجحة في الأراضي العثمانية في عصر القومية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: أثينا، بالياباترا (باتراس)، إستيفة (طيبة)، ليفاديا.", "316e2ac7"]},
"OLAYLAR:1826-06-15:0":{"b": ["الواقعة الخيرية — إلغاء الجيش الإنكشاري", "08c9372a"], "d": ["أُبيد الإنكشاريون الذين ثاروا (قلبوا القدور) على تدريبات جيش «الأشكنجية» الذي أُنشئ حديثًا في ثكناتهم في أت ميداني بنيران مدافع القوات الموالية التي أعدّها محمود الثاني مسبقًا؛ وأُلغي الأوجاق بجميع فروعه مع التكايا البكتاشية التابعة له. وبتصفية هذه المؤسسة التي دامت أربعة قرون، فتحت هذه العملية، التي دخلت التاريخ باسمها الذي يعني «الحدث الميمون»، الطريق أمام جيش «العساكر المنصورة المحمدية» وأمام جميع إصلاحات المركزية اللاحقة.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["غارة نافارين", "ee579e7f"], "d": ["أُحرق الأسطول العثماني المصري، الذي كان يقمع الثورة اليونانية، في نافارين على يد الأسطول المشترك البريطاني الفرنسي الروسي الذي دخل الميناء دون إعلان حرب؛ وفُقد نحو ستين سفينة وآلاف البحارة. وضمنت الغارة، التي طُويت في الدبلوماسية الأوروبية بوصفها «حادثًا مؤسفًا»، الاستقلال اليوناني عمليًّا، وفتحت الطريق إلى الحرب العثمانية الروسية 1828–1829.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["فرمان التنظيمات", "5042ce7b"], "d": ["بالخط الهمايوني الذي قُرئ في كولخانه وُضعت أرواح جميع الرعايا وأموالهم وأعراضهم، دون تمييز في الدين، تحت ضمان الدولة؛ وأُعلنت مبادئ العدالة في الضريبة والنظام في الخدمة العسكرية وعدم إنزال العقوبة دون محاكمة. ويُعدّ الفرمان، الذي هو من عمل مصطفى رشيد باشا، أول وثيقة كبرى ذات طابع دستوري في التحديث العثماني، وقد أعطى «عهد التنظيمات» (1839–1876) اسمه لعصر الإصلاح؛ وجرت في هذا الإطار إعادة هيكلة جذرية في الإدارة والقانون والتعليم والمالية.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["اندلاع حرب القرم", "3b9ca3c8"], "d": ["تحولت الأزمة التي بدأت بمسألة الأماكن المقدسة ودعوى روسيا حماية الرعايا الأرثوذكس إلى صراع مفتوح بإعلان العثمانيين الحرب؛ وبعد غارة سينوب دخلت إنجلترا وفرنسا (ثم بيدمونت) الحرب إلى جانب العثمانيين. وانتهت الحرب بمعاهدة باريس عام 1856 بعد أن نزلت جيوش الحلفاء في القرم واستولت على سيفاستوبول؛ غير أن الدين الخارجي الأول (1854) الذي أُخذ في سنوات الحرب أدخل الإمبراطورية في دوامة تبعية مالية دامت نصف قرن.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["فرمان الإصلاح", "78ff234d"], "d": ["وسّع الفرمان الذي أُعلن قبل مفاوضات السلام في باريس مبادئ التنظيمات، ومنح الرعايا غير المسلمين حقوق مساواة واسعة تشمل الوظائف الحكومية والخدمة العسكرية وفتح المدارس؛ وأُعيد تنظيم هياكل الطوائف. وبمعاهدة باريس التي وُقّعت بعده قُبلت الدولة العثمانية رسميًّا في أسرة القانون الدولي الأوروبي ووُضعت سلامة أراضيها تحت الضمان المشترك للدول الكبرى — وكان هذا الضمان في التطبيق بابًا جديدًا للتدخلات.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["القانون الأساسي — المشروطية الأولى", "0fe052c1"], "d": ["في يوم افتتاح المؤتمر الدولي الذي اجتمع في إسطنبول لبحث الأزمة البلقانية، أُعلن أول دستور عثماني بطلقات المدافع؛ وأُنشئ برلمان من مجلسين بالقانون الأساسي الذي هو من عمل حركة «العثمانيين الجدد» بقيادة مدحت باشا. وافتُتح مجلس المبعوثان في مارس 1877؛ لكن عبد الحميد الثاني، متذرعًا بحرب 93، علّق المجلس إلى أجل غير مسمى في فبراير 1878، وظل الدستور معلقًا ثلاثين سنة.", "c0f01a41"]},
"OLAYLAR:1877-04:0":{"b": ["حرب 93 (الحرب العثمانية الروسية 1877–1878)", "5bd96af7"], "d": ["في الحرب التي سُميت «حرب 93» لأنها وافقت سنة 1293 الرومية، هاجمت الجيوش الروسية من جبهتين؛ ورغم أن دفاع غازي عثمان باشا عن بليفن ومعارك أحمد مختار باشا في القفقاس صارت ملحمة، انهارت الجبهة وتقدم الروس حتى يشيلكوي (آياستفانوس). وأطلقت الحرب موجات هجرة إسلامية كبرى من البلقان والقفقاس نحو إسطنبول، ما زالت آثارها ممتدة حتى اليوم؛ ولم تعد البنية الديموغرافية والمالية للإمبراطورية إلى حالها السابقة.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["معاهدة برلين", "47f76a49"], "d": ["عدّل مؤتمر برلين «بلغاريا الكبرى» التي أوجدتها آياستفانوس باسم توازن القوى الكبرى، لكنه ترك مع ذلك صورة ثقيلة: فاستقلت صربيا والجبل الأسود ورومانيا؛ وأُنشئت إمارة بلغاريا ذاتية الحكم؛ وتُركت البوسنة والهرسك للاحتلال النمساوي، وقبرص للإدارة البريطانية، وقارص وأردهان وباطوم لروسيا. وتفكك إلى حد كبير النظام العثماني الذي دام خمسمائة عام في الروملي؛ وصارت «المسألة الشرقية» بندًا دائمًا على جدول أعمال الدبلوماسية الأوروبية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: فيليبه، فيدين، ترنوفو، وارنا، شومنو، سيليستر، روسجق، بوخارست، ياش، كوستنجة.", "076697b6"]},
"OLAYLAR:1881-05-12:0":{"b": ["احتلال تونس والديون العمومية", "c7e25598"], "d": ["احتلت فرنسا تونس متذرعة بحوادث على الحدود الجزائرية، ووضعتها تحت حمايتها بمعاهدة باردو؛ وانحسر الوجود العثماني في شمال أفريقيا إلى طرابلس الغرب. وبمرسوم محرم الذي صدر في السنة نفسها أُنشئت إدارة الديون العمومية التي مُثّل فيها الدائنون لإدارة الديون الخارجية التي أفلست: فرُبطت الإيرادات الأساسية كالملح والتبغ والحرير مباشرة بهذه الإدارة الأجنبية، وقُيّدت السيادة المالية تقييدًا شديدًا. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: القيروان، قابس، صفاقس، جربة (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09:0":{"b": ["الاحتلال البريطاني لمصر", "f1269768"], "d": ["سُحقت حركة عرابي باشا التي نهضت ضد الإفلاس المالي والرقابة الأجنبية في مصر بانتصار الجيش البريطاني في التل الكبير، الذي نزل إلى البر بعد قصف الإسكندرية، واحتُلت القاهرة. ورغم أن مصر ظلت قانونيًّا تابعة للعثمانيين، دخلت عمليًّا تحت الإدارة البريطانية؛ وصارت السيطرة على قناة السويس في صلب استراتيجية الإمبراطورية البريطانية.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["إعلان المشروطية الثانية", "95ee2fd2"], "d": ["أعاد عبد الحميد الثاني العمل بالقانون الأساسي أمام الحركة التي كبرت بصعود ضباط جمعية الاتحاد والترقي إلى الجبال في مقدونيا؛ واستُقبل «إعلان الحرية» بحماسة وجرت الانتخابات. غير أن الاستقرار لم يأت: فبعد قمع واقعة 31 مارس (أبريل 1909) خُلع عبد الحميد عن العرش؛ كما جرى في هذه الأشهر المضطربة إعلان استقلال بلغاريا وضم البوسنة وتوجه كريت نحو اليونان.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["حرب طرابلس الغرب", "ed441994"], "d": ["أعلنت إيطاليا، الباحثة عن المستعمرات، الحرب على طرابلس الغرب، آخر أراضي العثمانيين في شمال أفريقيا، واحتلت السواحل؛ ولما لم تستطع الدولة التي لا أسطول لها إرسال جيش نظامي، تسلل ضباط شباب مثل مصطفى كمال وأنور بك سرًّا إلى المنطقة ونظموا مقاومة فعالة مع القبائل السنوسية. وبمعاهدة أوشي (18 أكتوبر 1912) التي وُقّعت إثر اندلاع حرب البلقان تُركت ليبيا لإيطاليا؛ كما احتلت إيطاليا رودس والجزر الاثنتي عشرة.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["معاهدة لندن — فقدان الروملي", "f3f976df"], "d": ["بمعاهدة لندن التي أنهت حرب البلقان الأولى، فُقدت جميع الأراضي غرب خط ميديا – إينوس وجزر بحر إيجه؛ واستقلت ألبانيا. ولم يبقَ من الروملي، التي كانت مركز الثقل الديموغرافي والاقتصادي والثقافي للإمبراطورية منذ أكثر من خمسمائة عام، إلا تراقيا الشرقية (استُردت أدرنة في حرب البلقان الثانية)؛ وقد شدّد هذا الفقدان سياسة الحرب والإسكان لدى الإدارة الاتحادية تشديدًا جذريًّا.", "077da59d"]},
"OLAYLAR:1914-11-01:0":{"b": ["الدخول في الحرب العالمية الأولى", "05a0252e"], "d": ["جرّ السماح للطرادين غويبن وبريسلاو الهاربين من إنجلترا بدخول المضيق، مع إظهارهما كأنهما اشتُريا، الدولةَ خطوة خطوة إلى جانب ألمانيا؛ وبدأت الحرب فعليًّا بقصف الأسطول بقيادة الأميرال سوشون الموانئ الروسية (29 أكتوبر)، وجاءت الإعلانات المتبادلة في مطلع نوفمبر. ورغم إعلان الجهاد الأكبر لم يظهر الأثر المنتظر؛ ودخلت الإمبراطورية، على مدى أربع سنوات، حرب بقاء على خمس جبهات منفصلة من القفقاس إلى فلسطين.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["انتصار جناق قلعة", "95d888e8"], "d": ["ردّ نيران حقول الألغام والطوابي الأسطول الحليف الذي استهدف إسقاط إسطنبول والوصول إلى روسيا عن المضيق في 18 مارس؛ وحسم الخط الذي نصبته كاسحة الألغام نصرت مصير المعركة. وأُوقفت كذلك عملية غاليبولي البرية التي بدأت في أبريل عند أنافارتا وتبة كوجه تشيمن؛ وأخلى الحلفاء شبه الجزيرة تمامًا في يناير 1916. وسُمع اسم المقدم مصطفى كمال على هذه الجبهة؛ ويُعدّ هذا الانتصار، الذي تحقق بنحو ربع مليون شهيد ومفقود، مكان ولادة كوادر حرب الاستقلال وروحها.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["ثورة الشريف حسين", "75f7c58c"], "d": ["ثار أمير مكة الشريف حسين، بعد مراسلات سرية مع الإنجليز، على وعد بمملكة عربية مستقلة؛ واستُهدفت سكة حديد الحجاز بالغارات. ورغم أن دفاع فخري باشا الأسطوري عن المدينة المنورة، الذي استمر إلى ما بعد الهدنة، بقي رمزًا للمقاومة، فإن الثورة، باجتماعها مع التقدم البريطاني على الجبهة الفلسطينية، عجّلت تفكك السيادة العثمانية في الولايات العربية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: الطائف.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["هدنة مودروس", "9e87c767"], "d": ["انسحبت الدولة العثمانية، التي انقطعت جبهاتها بعضها عن بعض بانهيار بلغاريا، من الحرب بالهدنة الموقعة على متن المدرعة أغاممنون. وسرعان ما صارت المادة السابعة، التي تتيح فتح المضائق واحتلال الأماكن التي يُهدَّد أمنها خاصة، غطاءً قانونيًّا للتقاسم الفعلي: فاحتُلت الموصل والإسكندرون، ثم إزمير وإسطنبول. وتُعدّ الهدنة وثيقة النهاية الفعلية للإمبراطورية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: حماة، دمشق، حمص.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["مصطفى كمال في سامسون — حرب الاستقلال", "09a8f784"], "d": ["في أجواء السخط التي خلّفها احتلال إزمير، حوّل مصطفى كمال باشا، الذي نزل في سامسون بصفته مفتش الجيش التاسع، مهمته الرسمية إلى تنظيم المقاومة في الأناضول. وتأتي تعميم أماسية ومؤتمرا أرضروم وسيواس امتدادًا لهذا الانطلاق؛ وصار مبدأ «استقلال الأمة يخلّصه عزم الأمة وقرارها» نواة البرنامج السياسي لحرب الاستقلال.", "330e4c51"]},
"OLAYLAR:1920-04:0":{"b": ["افتتاح المجلس الوطني الكبير ومعاهدة سيفر", "2008feec"], "d": ["افتُتح المجلس الوطني الكبير في أنقرة في 23 أبريل 1920 إثر الاحتلال الرسمي لإسطنبول وحلّ مجلس المبعوثان؛ وصار المجلس، الذي جمع في يده صلاحيات استثنائية، نواة الدولة الجديدة القائمة على الإرادة الوطنية. وكانت معاهدة سيفر، التي وقّعتها حكومة إسطنبول في أغسطس، تقسّم الأناضول؛ فأعلن المجلس الوطني الكبير الموقّعين عليها خونة للوطن، ولم تُطبَّق سيفر قط.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["معركة سقاريا", "f2f970a6"], "d": ["انكسر الهجوم اليوناني، الذي اقترب من أنقرة إلى مسافة 50 كيلومترًا، في معركة دامت 22 يومًا و22 ليلة بأمر «لا يوجد خط دفاع بل توجد مساحة دفاع» الذي أصدره مصطفى كمال باشا بعد توليه القيادة العامة. وانتقل الجيش اليوناني لأول مرة إلى الدفاع الاستراتيجي؛ وجلب الانتصار لمصطفى كمال لقب الغازي ورتبة المشير، وفتح الباب أمام اتفاقية أنقرة مع فرنسا والاعتراف الخارجي.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["الهجوم الكبير وتحرير إزمير", "172a50c4"], "d": ["بلغ الهجوم الذي بدأ صباح 26 أغسطس من كوجه تبه إبادةَ القوات اليونانية الرئيسة في معركة القائد العام في طوملو بينار في 30 أغسطس؛ وبالمطاردة التي استمرت بأمر «أيها الجيوش، هدفكم الأول البحر المتوسط، إلى الأمام!» حُررت إزمير في 9 سبتمبر. واستُردت تراقيا الشرقية دون قتال بهدنة مودانيا (11 أكتوبر)؛ وحدد النصر العسكري قوة الدولة الجديدة التي ستقوم في لوزان على الطاولة.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["إلغاء السلطنة", "9f36a9f6"], "d": ["ألغى المجلس الوطني الكبير السلطنة في 1 نوفمبر 1922 بفصلها عن الخلافة إثر دعوة حكومة إسطنبول أيضًا إلى مفاوضات لوزان؛ وانتهى قانونيًّا حكم الأسرة العثمانية الذي دام 623 عامًا. وغادر محمد السادس وحيد الدين البلاد على متن مدرعة إنجليزية في 17 نوفمبر؛ وجيء بعبد المجيد أفندي إلى منصب الخلافة بقرار المجلس الوطني الكبير، وسيُلغى هذا المنصب أيضًا في 3 مارس 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["معاهدة لوزان", "38c27f7d"], "d": ["بمعاهدة لوزان للسلام التي وُقّعت في ختام مفاوضات شاقة دامت ثمانية أشهر، اعتُرف دوليًّا بحدود الدولة التركية الجديدة واستقلالها التام وسيادتها؛ وأُلغيت الامتيازات الأجنبية، وبدأت عملية تصفية الديون العمومية، ونُظّم تبادل السكان. وتُعدّ لوزان، التي أبطلت سيفر عمليًّا، الانتصار الدبلوماسي لحرب الاستقلال والوثيقة الخارجية المؤسسة للجمهورية.", "6d498c3f"]},
"OLAYLAR:1923-10:0":{"b": ["إعلان الجمهورية", "d5bfcdfb"], "d": ["أُعلنت الجمهورية بقبول المجلس الوطني الكبير، بتعديل دستوري، الحكم القائل «شكل حكومة الدولة التركية هو الجمهورية»؛ وانتُخب مصطفى كمال باشا أول رئيس للجمهورية. وهكذا انطوت المغامرة العثمانية التي بدأت عام 1299 إمارةً ثغرية وامتدت 624 عامًا، وأُقيمت الدولة الجديدة، التي تعود فيها السيادة دون قيد أو شرط للأمة، على إرث الإمبراطورية.", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["عزل تبه دلنلي علي باشا وبدء حصار يانينا", "e8a6530b"], "d": ["بلغت سياسة محمود الثاني في تصفية القوى المحلية تبه دلنلي علي باشا الذي كان يحكم يانينا منذ ثلاث وثلاثين سنة ويسيطر فعليًا على تساليا وإبيروس. فعُزل الباشا من رئاسة الدربندات، وعُزل ابنه ولي من باشوية طرخالة؛ ولما كان متوقعًا ألا يمتثل أُرسلت القوات عليه. وكان خورشيد أحمد باشا المكلف بهذا العمل واليَ المورة أيضًا وأُعطي كذلك سرعسكرية الروملي؛ وكُلّف جميع الحكام المدنيين والعسكريين في المنطقة بالقبض على التبه دلنلي. أي أن القائد الذي كان ينبغي أن يحكم المورة عند اندلاع الثورة اليونانية والقوات تحت إمرته كانوا يحاصرون قلعة يانينا. وعقد علي باشا في 23 مايو 1820 اجتماعًا مع الروم في يانينا، وحاول إقامة ولاية رومية تحت إدارته، وأمدّهم بالمال والسلاح. ولم تكن القوة المقابلة قليلة الشأن: فقد كان لعلي باشا جيش من 30-40.000 رجل، منهم 7.000 دائمون، وأسطول صغير؛ وقُدّر عدد السكان في إدارته بـ1,5-2 مليون، وإيراده السنوي بـ4-5 ملايين قرش.", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["بدء الحرب العثمانية-الإيرانية — خسارة قارص وبايزيد وحصار أرضروم", "570b27bd"], "d": ["في السنة الثانية من الثورة اليونانية تحولت الحدود الشرقية للإمبراطورية إلى منطقة حرب. فعبر ولي العهد القاجاري عباس ميرزا الحدود بقوة عسكرية كبيرة متخذًا ذريعة أن ممثلي العثمانيين فتشوا القافلة التي كانت فيها زوجة الشاه المتجهة إلى الحج؛ وأخذ ولايتي قارص وبايزيد وضرب الحصار على أرضروم. ولم تكن القوة التي واجهته وحدة حدودية عادية: فقد درّب عباس ميرزا جيش أذربيجان على الأساليب الأوروبية وأنشأ في تبريز مصنعًا للبارود وورش مدافع. أما الدولة العثمانية فكانت مشغولة في ذلك الوقت بثورة المورة في الغرب وبمقاومة تبه دلنلي علي باشا في يانينا في الشمال الغربي، ولم يكن في يدها جيش مدرَّب على الأساليب الأوروبية؛ وكان الأوجاق الإنكشاري سيبقى قائمًا حتى عام 1826.", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["احتلال إيران السليمانية وبغداد — حصار كركوك", "384d74e4"], "d": ["بالتزامن مع الحملة في شرق الأناضول شنّت القوات الإيرانية هجومًا واسعًا على شمال العراق وولاية بغداد الخاضعة للإدارة العثمانية. وكان يحكم بغداد حينئذ داود باشا المملوك الذي تولى الولاية منذ 1817؛ وكان الباشا يملك قوة من 10.000 من المشاة والمدفعية دربها ديفو من مرافقي نابليون السابقين. ولم يكن في مركز الإمبراطورية بعد جيش كهذا — فالوحدات المدرَّبة على الأساليب الأوروبية كانت في تلك السنوات في يد الولاة الأقوياء في الأقاليم وحدهم. والذي أنهى الحرب لم يكن انتصارًا عثمانيًا: بل أجبرت المقاومة العثمانية والوباء الذي عمّ أذربيجان القوات الإيرانية على التراجع.", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["مقتل تبه دلنلي علي باشا — نهاية حصار يانينا", "da679150"], "d": ["دامت المقاومة في يانينا قرابة سنتين، وفي تلك المدة نفسها اتسعت الثورة الرومية اتساعًا عامًا. ولما أرسل خورشيد باشا جواسيس إلى القلعة ووزّع الرتب والعطايا على الفارّين نزل عدد الجنود حول علي باشا إلى أربعين أو خمسين؛ فانسحب الباشا إلى دير باندليمون على البحيرة بضمان ألا يُمسّ بسوء إن استسلم. وكانت أسرة خورشيد باشا في هذه الأثناء قد وقعت في يد الثوار الروم؛ فتجاهل الأمان نامة التي أعطاها ليعود إلى المورة في أقرب وقت وأمر بإعداد فرمان إعدام مزيّف. ولما دُخل على غرفته ردّ علي باشا بالسلاح وقُتل في الاشتباك الذي نشب؛ وجيء برأسه إلى إسطنبول في 24 فبراير. وكشف الحصار أيضًا الصدع داخل القيادة العثمانية نفسها: فلما صارت ثورة المورة أخطر من مسألة التبه دلنلي عُيّن سيد علي باشا سرعسكرًا مستقلًا للمورة، ورفض خورشيد باشا، الذي لم يرقه ذلك، طلبات مساعدته، بل حاول أن يظهره فاشلًا في نظر الدولة. وسقطت أنابولي، أقوى قلاع المورة، في نهاية السنة التي أُزيل فيها علي باشا.", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["معاهدة أرضروم — انسحاب القوات الإيرانية في ستين يومًا", "166373c3"], "d": ["انتهت الحرب التي دامت سنتين بمعاهدة الصلح الموقعة في أرضروم. وبموجب المعاهدة كان على القوات الإيرانية أن تنسحب في ستين يومًا من الأراضي التي احتلتها. ولم ترسم المعاهدة حدًّا جديدًا، بل أعادت الوضع قبل الحرب؛ وستتحول الخلافات الحدودية بين الدولتين إلى قتال من جديد في 1833-1842، ولن تُنظَّم إلا في 1847 بمعاهدة ثانية وُقّعت أيضًا في أرضروم. وكان إغلاق الجبهة الشرقية شرطًا مسبقًا لتتمكن الإمبراطورية من توجيه كل ثقلها إلى الثورة اليونانية.", "7c54983b"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["دخول قراجه ريفه (ڤيريا) في السيادة العثمانية", "b0ece3f3"], "d": ["بتسليم سلانيك عام 1387 دخلت في السنة نفسها قراجه ريفه الواقعة في داخل مقدونيا السفلى في السيادة العثمانية. وكانت المدينة عقدة الطريق بين سلانيك وتساليا.", "4e571f7b"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["فتح قلعتي لوغوج (لوغوي) وكارانشبش — استمرار حملة تيميشوارا", "1af5a2be"], "d": ["استسلمت قلعة تيميشوارا بعد ثلاثة أسابيع من المقاومة في 26 تموز/يوليو 1552. وفي آب/أغسطس أُخذت قلعتا لوغوج وكارانشبش أيضًا؛ وأُخذت خمس عشرة قلعة على امتداد وادي موريش، وأُنشئت بكلربكية جديدة مركزها تيميشوارا.", "ecd1e532"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["وقوع بريشتينا في يد الجيش الصربي", "2ef111c0"], "d": ["أخذ الجيش الصربي الذي دخل كوسوفو في حرب البلقان الأولى بريشتينا، وبدأت في المدينة سياسة التصريب من جديد. ويُعدّ سقوط بريشتينا من أولى حلقات تفكك المقاومة العثمانية في ولاية كوسوفو.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["احتلال القوات الصربية لمنستير", "db9b3353"], "d": ["وقعت منستير، أحد أهم المراكز الإدارية والعسكرية في مقدونيا، في حرب البلقان الأولى في يد القوات الصربية بعد اشتباكات دامت خمسة أيام. وكان فقدان المدينة يعني الانتهاء الفعلي للوجود العثماني في مقدونيا.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["إعلان استقلال ألبانيا — إسماعيل قمالي في أفلونية", "2cdbd4d9"], "d": ["بينما دخلت جيوش حرب البلقان الولايات الألبانية أعلن إسماعيل قمالي في أفلونية استقلال ألبانيا. وبذلك خرج من الإدارة العثمانية الساحل والداخل الممتدان من دراج وإلباسان وبيرات وأرغيري وآق حصار إلى آيا ساراندا، وشكّلا نواة الدولة الألبانية الجديدة.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["انتهاء السيادة العثمانية في أوهريد وديبرا", "5273f1ec"], "d": ["بعد أحد عشر يومًا من سقوط منستير دخل الجيش الصربي منطقة البحيرات في غرب مقدونيا؛ وانتهت في أوهريد سيادة عثمانية دامت خمسة قرون، وخرجت ديبرا الشمالية أيضًا في الحركة نفسها.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["احتلال الجبل الأسود لإشقودرة", "db704247"], "d": ["شهدت إشقودرة أحد أطول الحصارات في حرب البلقان الأولى؛ وبعد مقاومة دامت أشهرًا سُلّمت المدينة لقوات الجبل الأسود. وكانت إشقودرة من آخر القلاع العثمانية التي صمدت حتى نهاية الحرب.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["الجبل الأسود يخلي إشقودرة؛ الفيلق الدولي للدول الكبرى يدخل المدينة", "8a6593e9"], "d": ["أخلى الجبل الأسود، بضغط من الدول الكبرى، إشقودرة التي أخذها في 23 نيسان/أبريل 1913 في 14 أيار/مايو 1913؛ ودخل المدينة الفيلق الدولي وصارت جزءًا من الإدارة المؤسسة لألبانيا.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["ابن سعود يأخذ الأحساء — نهاية السيادة العثمانية على ساحل الخليج", "505f26d5"], "d": ["أخرج أمير نجد عبد العزيز بن سعود الحامية العثمانية واستولى على منطقة الأحساء وأقام مركزه في الهفوف. وانتقل ساحل الخليج الغربي مع ميناءي القطيف والعقير إلى الإدارة السعودية؛ وانتهت إدارة الدولة العثمانية في المنطقة التي دامت خمسين سنة.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["معاهدة بوخارست — تراقيا الغربية وحوض قوالة تنتقل من بلغاريا إلى اليونان", "56123a58"], "d": ["انتهت حرب البلقان الثانية بمعاهدة بوخارست الموقّعة بين بلغاريا وصربيا واليونان والجبل الأسود. وتُرك لليونان بهذه المعاهدة حوض قوالة ودراما وسيرس الذي آل إلى بلغاريا في الحرب الأولى.", "ca3eb029"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["إنزال شط العرب — سقوط البصرة وفتح جبهة العراق", "c0a87d5d"], "d": ["نزلت القوة الاستكشافية البريطانية القادمة من الهند في مطلع الحرب العالمية الأولى في الفاو عند مصب شط العرب، وأخذت البصرة بسرعة. وكان سقوط المدينة يعني فتح جبهة العراق ودخول الطرف الشمالي للخليج في السيطرة البريطانية.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["جورجيا تعلن استقلالها — انحلال سايم عبر القوقاز", "6c79a8c7"], "d": ["أعلنت جورجيا، التي خرجت من سايم عبر القوقاز المؤسس بعد بريست-ليتوفسك، استقلالها وقامت جمهورية جورجيا الديمقراطية. وآلت غرب جورجيا مع كوتايسي إلى إدارة هذه الدولة الجديدة.", "7f834f47"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["إعلان جمهورية أذربيجان الديمقراطية", "8baecec3"], "d": ["بعد يومين من انفصال جورجيا أُعلنت جمهورية أذربيجان الديمقراطية؛ وكان المركز الأول كنجة. وفي اليوم نفسه قامت في يريفان جمهورية أرمينيا أيضًا، وانقسمت عبر القوقاز إلى ثلاث دول مستقلة.", "d4eb329a"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["احتلال القوات العربية والبريطانية لحلب", "00efb2da"], "d": ["بعد انهيار الجبهة الفلسطينية دخلت القوات المتقدمة شمالًا حلب؛ وآلت المدينة أولًا إلى القوات العربية ثم إلى القوات البريطانية. وهذا الاحتلال، الذي وقع قبل ثلاثة أيام من هدنة مودروس، أنهى فعليًّا الإدارة العثمانية في سوريا التي دامت أربعة قرون.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["الجيش الأحمر يحتل أذربيجان — نهاية الجمهورية الديمقراطية", "ebbb4566"], "d": ["دخل الجيش الأحمر أذربيجان وحلّ البرلمان والحكومة؛ وانتهت جمهورية أذربيجان الديمقراطية التي دامت سنتين. وبذلك انتقل حوض نفط باكو وكنجة إلى الإدارة السوفييتية.", "67223904"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["خان ميسلون — نهاية عهد فيصل وانتقال سوريا إلى الانتداب الفرنسي", "80a932b0"], "d": ["ألحق الفرنسيون هزيمة شديدة بالقوات السورية في خان ميسلون على طريق بيروت-دمشق، وانتهت مملكة فيصل العربية في دمشق. وأقامت فرنسا فعليًّا سلطة الانتداب التي مُنحت لها في سان ريمو؛ وارتبطت المنطقة الممتدة من حلب إلى دمشق ومن إسكندرون إلى دير الزور بإدارة الانتداب الفرنسي.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["تأسيس إمارة شرق الأردن — عبد الله بن الحسين يعلن إمارته", "5ef520c2"], "d": ["جاء عبد الله، ابن الشريف حسين، شمالًا عبر معان وأعلن إمارة شرق الأردن؛ واعترفت بريطانيا بعد وقت قصير بهذه الإدارة في إطار الانتداب. وصارت عمّان مركز الإمارة، وارتبطت هضبة الأردن، ومنها الكرك، بهذه الإدارة الجديدة.", "113f01ba"]},
"OLAYLAR_2S1019:0330-05-11:0":{"b": ["افتتاح القسطنطينية عاصمةً لبيزنطة (روما الشرقية)", "9d155dd6"], "d": ["افتُتحت بيزنطيوم، التي أعاد قسطنطين بناءها، بمراسم استمرت أيامًا عاصمةً جديدة للإمبراطورية. ويبدأ سجل بيزنطة (روما الشرقية) في الأطلس بهذا اليوم في القسطنطينية.", "c4468b48"]},
"OLAYLAR_2S1019:0969-07-01:0":{"b": ["الفاطميون يستولون على مصر: جوهر الصقلي يدخل الفسطاط، ويوضع أساس القاهرة", "500aef7a"], "d": ["أنهى القائد الفاطمي جوهر الصقلي السيطرة الإخشيدية في مصر ودخل الفسطاط، وأقام في المناح شمالًا قصر العاصمة الجديدة، القاهرة، وأسوارها.", "d9599f90"]},
"OLAYLAR_2S1019:0990-03-31:0":{"b": ["العقيليون يستولون على الموصل — تأسيس أسرة العقيليين في الموصل", "49eb93a6"], "d": ["قتل أبو الذواد أبا طاهر إبراهيم وابنه واستولى على الموصل؛ وتأسست في المدينة أسرة العقيليين التابعة للبويهيين.", "affdc0ec"]},
"OLAYLAR_2S1019:1084-12-12:0":{"b": ["سليمان شاه بن قتلمش يأخذ أنطاكية من بيزنطة", "17d1c6f0"], "d": ["أخذ سليمان شاه، حاكم سلاجقة الأناضول، أنطاكية التي بقيت أكثر من قرن في يد بيزنطة؛ واستسلمت القلعة الداخلية المقاومة في 12 يناير 1085.", "a6f1f783"]},
"OLAYLAR_2S1019:1098-06-03:0":{"b": ["الصليبيون يستولون على أنطاكية — تأسيس إمارة أنطاكية", "c9f47942"], "d": ["سقطت أنطاكية، التي صمدت لحصار طويل، في يد الصليبيين بخيانة فيروز قائد ياغي سيان. وشملت إمارة أنطاكية المؤسَّسة الإسكندرونة أيضًا.", "f6409190"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["غياث الدين كيخسرو يفتح أنطالية — السلاجقة يبلغون البحر المتوسط", "9812e629"], "d": ["أخذ سلطان سلاجقة الأناضول غياث الدين كيخسرو الأول أنطالية، التي وقعت في يد الإيطالي ألدوبرانديني بعد استيلاء اللاتين على القسطنطينية، بدعم من الروم الذين لم يرضوا بالإدارة اللاتينية.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["عز الدين كيكاووس يستردّ أنطالية من القبارصة", "ec2446f9"], "d": ["فتح عز الدين كيكاووس الأول من جديد أنطالية التي خرجت من اليد بثورة سنة 1212 بدعم من ملك قبرص، وأعاد ولايتها إلى مبارز الدين أرتقش.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["بيبرس يأخذ يافا من الصليبيين — انتهاء سيطرة مملكة القدس في يافا", "c7629d70"], "d": ["أنهى السلطان المملوكي بيبرس الأول السيطرة الصليبية في يافا، وأمر بتخريب المدينة؛ وأرسل خشب القلعة الداخلية ورخامها لبناء جامعه في القاهرة.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["بيبرس يأخذ أنطاكية — نهاية إمارة أنطاكية", "da2b511a"], "d": ["تجاوز الجيش المملوكي أسوار أنطاكية بهجوم عام؛ وانتهت الإمارة الصليبية التي دامت 170 سنة، وانضمت الإسكندرونة أيضًا من جديد إلى أراضي الإسلام.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["القرمانيون يستردّون قونية من الإيلخانيين", "057ec073"], "d": ["بعد فرار والي الأناضول الإيلخاني دمرداش إلى مصر، وقعت قونية من جديد في يد القرمانيين. وستنتقل المدينة سنة 1350 إلى إرتنا.", "c2d583f3"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["ستيفان دوشان يأخذ سيريس من بيزنطة", "2cc79d36"], "d": ["استولى الملك الصربي ستيفان دوشان، مستفيدًا من الحرب الأهلية البيزنطية، على سيريس وجعلها عاصمة الإمبراطورية الصربية.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["بيع كونتية فيلدكيرش إلى النمسا الهابسبورغية", "fe4a0306"], "d": ["باع رودولف، آخر كونت من فرع مونتفورت-فيلدكيرش، جميع أملاكه سنة 1375 إلى الهابسبورغ دوقات النمسا؛ وتمّ التسليم الفعلي بوفاته (1390). وكانت فيلدكيرش أول جزء كبير من فورارلبرغ يقع في يد الهابسبورغ.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["بلتشيك وساحل دوبروجا تدخلان في الإدارة العثمانية", "dfd348b9"], "d": ["بعد انتصار قوصوة دخلت بلتشيك على ساحل دوبروجا في الإدارة العثمانية. وسيحتل المنطقة بعد ذلك مباشرة فويفود الأفلاق ميرتشا، وسيُعاد إقرار السيادة العثمانية سنة 1393.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["سادة المرعشيين يستسلمون لتيمور في ماهانسر — مازندران تنتقل إلى التيموريين", "125dbed8"], "d": ["حصر تيمور، الذي دخل مازندران في حملته التي دامت خمس سنوات، المرعشيين الذين واجهوه في قراتوغان في قلعة ماهانسر وتسلّمهم. وجرت مذبحة كبرى في ساري وآمل؛ وأُعطيت ساري إلى إسكندر شيخي ابن كيا أفراسياب.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["شيبينيك تدخل مجددًا في إدارة جمهورية البندقية", "9b7998bf"], "d": ["بعد أن باع لاديسلاوس النابولي حقوقه في دلماسيا إلى البندقية سنة 1409، دخلت شيبينيك، التي قاومت، مجددًا في إدارة البندقية سنة 1412. وبقيت المدينة ملكًا للبندقية في دلماسيا حتى سقوط الجمهورية سنة 1797.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["حملة جلبي محمد على الجاندارأوغلو: جانقري تُعطى لقاسم بك الذي في الحماية العثمانية", "da03b919"], "d": ["زحف جلبي محمد على الجاندارأوغلو إسفنديار بك، الذي أعان الشيخ بدر الدين على العبور إلى الأفلاق، فتقدم إلى قسطموني وحاصر سينوب التي انسحب إليها إسفنديار. واعترف إسفنديار بالسيادة العثمانية؛ وبعد اعتبار جبل إلغاز حدًّا، أُعطيت جانقري وما حولها لابنه قاسم بك الذي لجأ إلى العثمانيين.", "f88b8d5e"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["بيع النصف الأول من كونتية براغنتس إلى النمسا الهابسبورغية", "3a9598db"], "d": ["باعت إليزابيث من هوخبرغ، وريثة مونتفورت-براغنتس، سنة 1451 نصف كونتية براغنتس إلى الهابسبورغ؛ وأُخذ النصف الباقي سنة 1523. وبذلك صارت براغنتس جزءًا من فورارلبرغ الهابسبورغية.", "c02a452c"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["موسكو تأخذ بريانسك من دوقية ليتوانيا الكبرى", "fb1c3a61"], "d": ["في الحرب الموسكوفية-الليتوانية 1500-1503 استولى الجيش الروسي على بريانسك وانضمت المدينة إلى الدولة الموسكوفية؛ وأقرّت هدنة 1503 هذا المكسب.", "8e507991"]},
"OLAYLAR_2S1019:1500-04-12:0":{"b": ["وفاة آخر كونت لغوريتسيا ليونهارد — ليينتس ووادي بوستر تنتقلان إلى النمسا الهابسبورغية (تيرول)", "93331339"], "d": ["توفي ليونهارد، آخر ممثلي كونتات غوريتسيا، في ليينتس في 12 أبريل 1500. ووفقًا لاتفاق وراثة سابق انتقلت الكونتية الأمامية التي تشمل ليينتس ووادي بوستر إلى ماكسيميليان الأول وضُمّت إلى تيرول.", "996079fc"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["بيقلي محمد باشا يأخذ الموصل وسنجار والعمادية من الصفويين", "3039d6af"], "d": ["أخذ بيقلي محمد باشا، الذي هزم قره خان في كوجحصار، وهو يحاصر ماردين، القلاع المحيطة من الصفويين: استُولي على الموصل والرها وبيره جك وسنجار، وقبل أمراء العمادية وسائر الأمراء الأكراد التبعية العثمانية. أما قلعة ماردين فستُتسلَّم بعد عودة الباشا من مرج دابق.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["انتخاب غوستاف فازا ملكًا في سترينغنيس — مملكة السويد تنفصل عن اتحاد كالمار", "a6e95f4c"], "d": ["انتُخب غوستاف إريكسون فازا، الذي ثار على ملك الدنمارك كريستيان الثاني بعد حمام دم ستوكهولم (1520)، ملكًا في 6 يونيو 1523 في الريكسداغ السويدي المنعقد في سترينغنيس في مايو 1523. وبذلك خرجت السويد وفنلندا التابعة لها نهائيًا من اتحاد كالمار القائم منذ 1397، وبدأ عهد فازا في مملكة السويد المستقلة.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["طبقات سيليزيا تعترف بفرديناند الأول ملكًا — سيليزيا تنتقل إلى النمسا الهابسبورغية", "a28e10c2"], "d": ["اعترفت طبقات سيليزيا العليا والسفلى في اجتماع عام بالهابسبورغي فرديناند، الذي انتُخب في أكتوبر 1526 لتاج بوهيميا الذي شغر بوفاة لايوش الثاني في موهاج، ملكًا، وبزوجته آنا ملكةً، في 5 ديسمبر 1526 بشرط تأكيد امتيازاتها. وبذلك دخلت دوقيات سيليزيا في الإدارة الهابسبورغية مع تاج بوهيميا.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["ملك السويد غوستاف فازا يؤسس هلسنكي", "43468b54"], "d": ["أسّس ملك السويد غوستاف فازا سنة 1550 عند مصب نهر فانتا مدينة هلسنكي مدينةً تجاريةً جديدة لتنافس ريفال (تالين) في تجارة البلطيق. ونُقلت المدينة سنة 1640 إلى موضعها الحالي، نحو البحر.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["إمام اليعاربة في عُمان ناصر بن مرشد يأخذ جلفار من البرتغال", "6ca9fb0c"], "d": ["أُخرج البرتغاليون، الذين ثبتوا في جلفار بعد سقوط هرمز سنة 1622، من المنطقة باستيلاء إمام اليعاربة في عُمان ناصر بن مرشد عليها سنة 1633.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["خسارة قلعة سين لصالح البندقية — الداخل الدلماسي", "3af8e103"], "d": ["أخذت القوات البندقية في حرب المورة سنة 1686 قلعة سين في داخل دلماسيا من العثمانيين؛ وصمدت القلعة أيضًا أمام الحصار العثماني سنة 1715 وبقيت في يد البندقية.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["وقوع فارادين وباتش في يد مملكة المجر (التاج الهابسبورغي) — الانسحاب من باتشكا بعد هارشان", "6bc2b1ac"], "d": ["مرّ جيش سارى سليمان باشا، المنسحب من هزيمة هارشان، بفارادين في 1 سبتمبر 1687 وترك القلعة لجعفر باشا؛ وبعد وقت قصير وقعت فارادين وباتش في باتشكا في يد القوات الهابسبورغية المتحالفة. ولما اعتُبر نهر سافا حدًّا في كارلوفتش، بقيت فارادين في الجانب النمساوي.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["وقوع أوسييك في يد مملكة المجر (التاج الهابسبورغي) — بدء فقدان سلافونيا", "7af97ffe"], "d": ["انتقلت قلعة الجسر أوسييك على نهر درافا بعد هزيمة هارشان إلى القوات الهابسبورغية في 26 سبتمبر 1687. وانسحب الوجود العسكري العثماني والسكان الأتراك في سلافونيا تدريجيًا بين 1686 و1688؛ ودخلت المنطقة في الإدارة الهابسبورغية.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["خسارة هرسك نوفي لصالح البندقية — مدخل خليج كوتور", "b88046d8"], "d": ["حاصر الأسطول البندقي وحلفاؤه في حرب المورة سنة 1687 قلعة هرسك نوفي عند مدخل خليج كوتور واستولوا عليها؛ وبقيت المدينة في يد البندقية حتى سقوط جمهورية البندقية سنة 1797.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["ربط كورسيكا بالتاج الإنجليزي — مملكة أنجلو-كورسيكا", "10f18bde"], "d": ["طهّر باولي، الذي ثار على فرنسا الثورية، الجزيرة من الحاميات الفرنسية بدعم الأسطول الإنجليزي؛ وأقرّ المجلس المنعقد في كورتي دستورًا يربط كورسيكا بالملك الإنجليزي. وبقيت الجزيرة سنتين مملكة أنجلو-كورسيكا في ظل إدارة الحاكم العام الإنجليزي غيلبرت إليوت.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["إخلاء الإنجليز لكورسيكا — الجزيرة تعود إلى فرنسا", "c9f986fe"], "d": ["أخلت إنجلترا، التي ضاق عليها الحال في البحر المتوسط بانتصارات بونابرت في إيطاليا وانتقال إسبانيا إلى صف فرنسا، كورسيكا. وانتهت مملكة أنجلو-كورسيكا وارتبطت الجزيرة من جديد بفرنسا.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["الجيش النمساوي-المجري يكسر المقاومة ويأخذ بيهاتش", "ffec53e0"], "d": ["لقيت النمسا-المجر، التي نالت حق احتلال البوسنة والهرسك بمعاهدة برلين، مقاومة المسلمين المحليين في بيهاتش. وأخذت القوات بقيادة الجنرال فيلهلم فون راينلندر المدينة في 18 سبتمبر 1878؛ وخرجت حامية أوستروفيتسا في وادي أونا أيضًا من اليد العثمانية بالعملية نفسها.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["الإنجليز يحتلون سوكوتو — خلافة سوكوتو تفقد عاصمتها", "e744f986"], "d": ["بعد أن أخذ لوغارد، حاكم إنجلترا التي أعلنت شمال نيجيريا مستعمرةً سنة 1900، الإمارات واحدة بعد أخرى، ألحق بجيش سوكوتو هزيمة ثقيلة واحتل العاصمة في 15 مارس 1903. وبمقتل الخليفة طاهر الفارّ في بورمي في يوليو انتهى السلطان السياسي للخلافة.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["ابن سعود يهزم أمير الرشيديين — القصيم تنتقل من إمارة شمر إلى السعوديين", "a32201dd"], "d": ["هزم عبد العزيز بن سعود، الذي استردّ الرياض سنة 1902، أمير الرشيديين عبد العزيز بن متعب وقتله في 13 أبريل 1906. وبعد هذه المعركة استولى على منطقة القصيم (بريدة وعنيزة)؛ ولم يحكم الرشيديون بعد ذلك إلا حائل وما حولها.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["احتلال الإنجليز لجزيرة كمران", "c514bb66"], "d": ["احتل الإنجليز سنة 1915 جزيرة كمران في البحر الأحمر على ساحل اليمن خلال الحرب العالمية الأولى، وبدأت تُدار من عدن.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["احتلال الإنجليز لنابلس — انهيار الجبهة الفلسطينية", "b5e85950"], "d": ["في سبتمبر 1918 فرّق هجوم اللنبي الكبير على الجبهة الفلسطينية الجيشين العثمانيين 7 و8؛ ووقعت نابلس في يد الإنجليز، وانتهى في المدينة حكم عثماني دام أربعة قرون. وبقيت المدينة في الإدارة العسكرية الإنجليزية حتى سنة 1920.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["دخول الإنجليز إلى الموصل — احتلال ولاية الموصل خلافًا للهدنة", "ed5e8e33"], "d": ["حين وُقّعت هدنة مودروس كانت الموصل في يد القوات التركية. ودخل الإنجليز المدينة في 8 (أو 10) نوفمبر 1918 استنادًا إلى المادة 7 من الهدنة، واضطرت القوات التركية إلى الانسحاب من الولاية في 15 نوفمبر. ولم تُحلّ مسألة الموصل في لوزان أيضًا، وتُركت لاتفاقية أنقرة سنة 1926.", "168f5310"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["آلانيا (علائية) تدخل بعد السلاجقة في سيطرة إمارة محلية", "7b1489b3"], "d": ["مع تفكك دولة سلاجقة الأناضول فعليًّا في عقد 1290 استقلّ ميناء علائية (آلانيا) على ساحل المتوسط عن السلطة المركزية ودخل في سيطرة إمارات المنطقة (في هذه الفترة ضمن مجال نفوذ القرمانيين)؛ والتاريخ الدقيق وأي إمارة سيطرت عليه مباشرة غير واضحين في المصادر.", "78a4ff46"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["سينوب يأخذها غازي جلبي وتدخل في نفوذ الجاندارية", "f107586a"], "d": ["أخذ غازي جلبي، من الأسرة المؤسسة لإمارة الجاندار (إسفنديار أوغلو) التي قويت في منطقة قسطموني وسينوب مع ضعف السيادة الإيلخانية، سينوب نحو عام 1322 وجعل المدينة مركزًا ساحليًّا للإمارة.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["معاهدة زادار — دوبروفنيك تنتقل من البندقية إلى الحماية المجرية", "57fb81f9"], "d": ["أنهت معاهدة زادار الموقّعة في 18 شباط/فبراير 1358 سيادة البندقية على دلماسيا التي دامت 150 سنة؛ وبذلك خرجت دوبروفنيك (راغوزا) من إدارة البندقية ونالت وضع جمهورية شبه ذاتية الحكم تدخل تحت حماية الملك المجري لايوش الأول.", "e207c893"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["أرضروم ومنطقة أشقلة تتبدلان بين القره قويونلو والتيموريين", "ca64775a"], "d": ["في الفراغ الذي نشأ بعد وفاة تيمور عام 1405 تحرك سلطان القره قويونلو قره يوسف بين 1406-1408 ضد الولاة التيموريين في شرق الأناضول؛ وخرجت أرضروم وأشقلة المحيطة بها في هذا الصراع من السيطرة التيمورية ودخلت في نفوذ القره قويونلو.", "10b1b07c"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["أوزون حسن الآق قويونلو يُنهي الفرع الأيوبي في حصن كيفا", "2b464a1f"], "d": ["ضُمّت حصن كيفا (حسنكيف) وسعرد، وهما في دجلة العليا أحد الفرعين الأخيرين الباقيين من الأسرة الأيوبية مع حماة، في 1462 على يد سلطان الآق قويونلو أوزون حسن، فانتهت السيادة الأيوبية.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["البرتغال تُكمل سيادتها على سواحل مضيق هرمز", "bef031f0"], "d": ["اكتملت في 1515 حملة الخليج العربي التي بدأها أفونسو دي ألبوكيرك عام 1507، فشملت جزيرة هرمز وقِشم المقابلة لها والبريمي؛ ودخلت مملكة هرمز التابعة لإيران فعليًّا في الحماية البرتغالية، واستولت البرتغال على التحكم بتجارة الخليج.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["اتحاد لوبلين — الأراضي الأوكرانية تنتقل من ليتوانيا إلى بولندا", "1881ceff"], "d": ["وحّد اتحاد لوبلين الموقّع في 1 تموز/يوليو 1569 دوقية ليتوانيا الكبرى ومملكة بولندا في دولة واحدة (ريتش بوسبوليتا). وبحكم شروط الاتفاق نُقلت بودوليا وڤولينيا ومنطقة كييف (ومنها بار وبرديتشيف وبياويستوك وبراسلاف) إداريًّا من ليتوانيا مباشرة إلى مملكة بولندا.", "184b03dd"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["القوات المصرية تنسحب من منطقة الأحساء (لحسا)", "5ea75c8d"], "d": ["كانت قوات محمد علي باشا المصرية قد احتلت نجدًا وشرق الجزيرة العربية (ومنها الأحساء والقطيف والعقير والجبيل) عام 1836؛ وبحمل اتفاقية المضائق في لندن (1840) مصر على التخلي عن فتوحاتها في شبه الجزيرة العربية انسحبت القوات من المنطقة عام 1841، وعادت الإدارة إلى القوى المحلية (نفوذ آل سعود/آل خليفة).", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["القوات الروسية تأخذ قلعة آق مسجد — انهيار خط سير داريا لخانية قوقند", "e9f9a9c7"], "d": ["استولت القوات الروسية بقيادة الجنرال ڤاسيلي بيروفسكي في تموز/يوليو 1853 بعد حصار طويل على قلعة آق مسجد، التابعة لخانية قوقند على ضفة سير داريا؛ وصارت القلعة فيما بعد، باسم بيروفسك، مخفرًا متقدمًا لتركستان الروسية.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["معركة غوك تبه — تركمان آخال تكه يُهزمون أمام روسيا", "76c7a102"], "d": ["كسرت القوات الروسية بقيادة الجنرال ميخائيل سكوبيليف مقاومة تركمان آخال تكه بإسقاطها قلعة غوك تبه (جيوك تبه) في 24 كانون الثاني/يناير 1881؛ ودخلت منطقة التركمان وراء بحر قزوين، ومنها سهل دهستان وأبيورد ونسا، في طور الانضمام إلى الإمبراطورية الروسية (أُنشئت منطقة ما وراء قزوين عام 1881).", "41bbf179"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["إعلان مملكة رومانيا — الإمارة تتحول إلى مملكة", "4d413f0c"], "d": ["تحولت إمارة رومانيا، التي اعترف مؤتمر برلين باستقلالها بعد الحرب العثمانية الروسية 1877-78، إلى مملكة في 26 آذار/مارس 1881 (14 آذار/مارس بالتقويم اليولياني) بتتويج الملك كارول الأول؛ وصارت البلاد كلها، ومنها بابا داغ وبيرلاد وبوزاو والعاصمة بوخارست، جزءًا إداريًّا من المملكة الجديدة.", "54ed49f3"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["إيطاليا تضم هضبة إريتريا بما فيها أسمرة وكرن", "31308dc8"], "d": ["ضمّت إيطاليا، مستفيدة من الفراغ في القوة الذي نشأ بوفاة إمبراطور الحبشة يوحنس الثاني عام 1889، هضبة إريتريا بما فيها أسمرة وكرن ضمًّا فعليًّا إثر معاهدة أوتشيالي (وتشالي) (2 أيار/مايو 1889)؛ وأُعلنت رسميًّا في 1 كانون الثاني/يناير 1890 مستعمرةً باسم «إريتريا».", "66fdfc34"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["المنطقة الشمالية الشرقية من كينيا (خط غاريسا-مارسابيت) تنضم إلى محمية شرق أفريقيا البريطانية", "e45c6d43"], "d": ["اتسعت محمية شرق أفريقيا البريطانية، التي قامت بتنازل شركة شرق أفريقيا البريطانية عن امتيازها للتاج عام 1895، فشملت مناطق الشمال الشرقي مثل غاريسا وكيتوي ومارسابيت وواجير؛ وامتد إخضاع هذه المناطق الداخلية للإدارة الفعلية على النصف الثاني من عقد 1890.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["إمارة إلورن تقع في أيدي قوات شركة النيجر الملكية", "b111cb7d"], "d": ["وقعت إمارة إلورن، التابعة لخلافة سوكوتو، في أيدي قوات شركة النيجر الملكية بقيادة السير جورج غولدي في حملة شباط/فبراير 1897؛ وكُسرت قوة الإمارة العسكرية ودخلت المنطقة فعليًّا في النفوذ البريطاني (واكتمل الضم الرسمي بإنشاء محمية نيجيريا الشمالية عام 1900).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["أسر ملك بونيورو كاباريغا وإلحاق المملكة بمحمية أوغندا البريطانية", "62bc7c64"], "d": ["أُسر كاباريغا ملك بونيورو، الذي قاوم القوات البريطانية منذ 1894، في منطقة لانغو (قرب دوكولو) في 9 نيسان/أبريل 1899 ونُفي إلى سيشل؛ وضُمّت أراضي المملكة، ومنها العاصمة هويما ومسيندي، إلى محمية أوغندا البريطانية.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["معاهدة تورو — مملكة تورو تصبح جزءًا ذاتي الحكم من محمية أوغندا البريطانية", "c55340a2"], "d": ["بعد سقوط بونيورو عام 1899 أضفت مملكة تورو المجاورة طابعًا رسميًّا على الحماية البريطانية القائمة منذ 1896 في إطار معاهدة أوغندا لعام 1900؛ ونالت المملكة، ومنها العاصمة فورت بورتال، وضع إدارة محلية ذاتية الحكم داخل محمية أوغندا البريطانية.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["إمارة أداماوا تُقسم بين ألمانيا وبريطانيا", "b9230d3d"], "d": ["قُسمت إمارة أداماوا (فومبينا)، التابعة لخلافة سوكوتو، إلى قسمين في ختام حملات القوات الاستعمارية الألمانية والبريطانية في 1899-1901: فانضم القسم الشرقي (ومنه غاروا وبانيو ومارووا ونغاوندر) إلى الكاميرون الألمانية، والقسم الغربي (عاصمته يولا) إلى نيجيريا الشمالية البريطانية؛ ونُفي الأمير زبير.", "671ba3aa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["معركة تيت — طوارق أهجار يُهزمون أمام القوات الفرنسية", "831143d6"], "d": ["في المعركة التي جرت قرب واحة تيت يوم 7 أيار/مايو 1902 في أثناء حملة كوتنست هزمت القوات الفرنسية طوارق كل أهجار هزيمة حاسمة؛ ودخلت هذه المنطقة الداخلية من الصحراء، ومنها أبالسة مركز أهجار وإيديلس، في سيطرة الجزائر الفرنسية.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["القوات الفرنسية تستولي على المناطق الداخلية من أوبانغي-شاري (خط بامباري-بريا)", "0b9a9f72"], "d": ["أخضعت الحملات الشمالية للكونغو الفرنسي فعليًّا في مطلع عقد 1900 المنطقة الداخلية من أوبانغي-شاري، وهي تشمل بامباري وباتانغافو وبوسانغوا وبريا؛ ونُظمت المنطقة رسميًّا في 29 كانون الأول/ديسمبر 1903 مستعمرةً باسم أوبانغي-شاري (جزءًا من أفريقيا الاستوائية الفرنسية).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["القوات الفرنسية تقضي على سلطنة دار الكوتي التابعة للسلطان محمد السنوسي", "644b2c3f"], "d": ["قُضي فعليًّا على سلطنة دار الكوتي، القائمة على تجارة الرقيق وعاصمتها ندلي، والتي دخلت الحماية الفرنسية عام 1897، بحملة نُظمت عام 1911 بعدما واصل السلطان محمد السنوسي مقاومة السلطة الفرنسية؛ وقُتل السنوسي في المعركة وأُلغيت السلطنة رسميًّا عام 1912.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["نظام ليفونيا يتنازل عن أراضي كلايبيدا (ميميل) لفرع بروسيا من النظام التوتوني", "e61e5d50"], "d": ["تركت طريقة ليفونيا قلعة كلايبيدا (ميميل) عند مصب نيمان والأراضي المحيطة بها لفرع بروسيا من النظام التوتوني؛ وتنازل أسقف كورلاند عن حصته أيضًا لهذا الفرع في 1392. وبقيت كلايبيدا في النظام بصلحي تورون 1411 وملنو 1422، وانتقلت عام 1525 إلى دوقية بروسيا.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["عمر بك يأخذ قلعة ميناء إزمير من الجنوية", "ab92d96e"], "d": ["حاصر الآيديني عمر بك قلعة ميناء إزمير، التي بقيت في يد اللاتين، سنتين ونصف السنة. وسلّم الحاكم الجنوي للقلعة مارتينو زكاريا القلعة وذهب إلى ساقز.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["السوتايي إبراهيم شاه يسيطر على ديار بكر", "179196cf"], "d": ["بعد تفكك الدولة الإيلخانية سيطر السوتايي إبراهيم شاه على منطقة ديار بكر التي شهدت صراعات بين الجلائريين والجوبانيين؛ واستمرت سيادته حتى 1353.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["بيرات تنتقل من البيزنطيين إلى الصرب — فتح ستيفان دوشان لألبانيا", "1eba202e"], "d": ["إن قلعة بيرات، التي كسرت حصار الأنجويين عام 1281 وكانت منذ ذلك التاريخ مركز آخر إقليم بيزنطي على الأدرياتيكي، انتقلت إلى الصرب في أثناء تقدم ستيفان دوشان نحو ألبانيا والحرب الأهلية البيزنطية مستمرة. وبعد استسلام كرويا في أيار/مايو أو حزيران/يونيو 1343 صارت بيرات وقانينا وأفلونية للصرب في غضون سنتين؛ وعُيّن على رأس الإقليم صهر دوشان جون كومنينوس أسين.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["العبد الواديون (الزيانيون) يتحررون في تلمسان من سيادة المرينيين", "a4aa9573"], "d": ["تحرر العبد الواديون في تلمسان من سيادة المرينيين بقيادة عثمان الثاني وأخيه أبي ثابت. وقصر هذا الاستقلال.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["بيرام خوجه ينال استقلاله — ولادة إمارة القره قويونلو", "37964815"], "d": ["نال بيرام خوجه، الذي يُعدّ أول بك للقره قويونلو، استقلاله بقتل حاكم السوتاي أق ساقال حسين بك. وأخذ الموصل وأعطى إدارتها لأخيه بردي خوجه.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["بوفاة إبراهيم شاه تدخل ديار بكر في إدارة الجلائريين", "11c338ef"], "d": ["عند وفاة السوتايي إبراهيم شاه، الذي كان مسيطرًا على منطقة ديار بكر منذ 1343، دخلت المنطقة في إدارة الجلائريين.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["إينوس تنتقل إلى الإدارة الجنوية (أسرة غاتيلوزي)", "5dc12940"], "d": ["انتقلت إينوس، التي كانت مدينة ميناء مهمة في العهد البيزنطي، عام 1355 إلى الإدارة الجنوية وحكمتها أسرة غاتيلوزي.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["دوق ليتوانيا الأكبر ألغيرداس (أولغيرد) يأخذ بريانسك", "3cad9caf"], "d": ["أخذ جيش دوق ليتوانيا الأكبر ألغيرداس بريانسك. وبقيت المدينة تابعة لدوقية ليتوانيا الكبرى حتى 1500.", "03107c6d"]},
"OLAYLAR_2S_0919:1362-01-01:0":{"b": ["إمارة كييف تنتقل إلى سيادة ليتوانيا", "c4fda115"], "d": ["دخلت إمارة كييف في سيادة ليتوانيا، وصارت في الدولة الليتوانية الروسية إمارة تابعة يحكمها أمراء من سلالة غيديميناس.", "d4a2f5ec"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["الإينانجيون يعترفون بسيادة الجرميانيين", "0679db27"], "d": ["اعترفت إمارة الإينانج، التي حكمت حول دنيزلي، بسيادة الجرميانيين على الأرجح عام 1368.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["دوق سالونيك مانويل يضع منطقة سيرس ودراما تحت الإدارة البيزنطية", "abb99c3e"], "d": ["بمقتل الملك ڤوكاشين ودوق سيرس أوغليشا في جرمن (26 أيلول/سبتمبر 1371) انتهت الإدارة الصربية في منطقة سيرس. ووضع الأمير البيزنطي مانويل الثاني باليولوغوس، الذي حكم في سالونيك، في تشرين الثاني/نوفمبر 1371 سيرس والمنطقة التي فيها دراما تحت الإدارة البيزنطية. وانتقلت المنطقة إلى العثمانيين في أيلول/سبتمبر 1383.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["بوفاة بير حسين بك تنتقل أرزنجان وبايبورت إلى مطهرتن", "3269e55d"], "d": ["عند وفاة أمير أرزنجان بير حسين بك آلت أرزنجان وبايبورت إلى مطهرتن، أحد أمراء الإيرتنيين؛ وصار مطهرتن أمير أرزنجان.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["تاج الدين بك يهزم جيش الإيرتنيين في نيكسار ويتصرف باستقلال", "42982ea7"], "d": ["هزم تاج الدين بك في ربيع 1379 قوات القاضي برهان الدين وبك الإيرتنيين علاء الدين علي اللذين هاجما نيكسار. وقطع دفع الضريبة لإمارة الإيرتنيين وتصرف باستقلال منذ سنة 781 (1379).", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["تيمور يستولي على خوارزم استيلاءً نهائيًّا", "ef76d2c9"], "d": ["نظّم تيمور بعد حملة خوارزم الأولى عام 1371 ثلاث حملات أخرى. وفي حملة 1379 استولى على المنطقة استيلاءً نهائيًّا ونهبها وعاد بغنائم وفيرة.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["ملك البوسنة تفرتكو الأول يؤسس هرسك نوفي", "1628221a"], "d": ["أسّس ملك البوسنة تفرتكو الأول بلدة جديدة في خليج توبلا لتنافس دوبروفنيك في تجارة الملح؛ وعُرفت البلدة فيما بعد باسم نوڤي (هرسك نوڤي).", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["تيمور يأخذ قندهار من الكرتيين ويعطيها لحفيده بير محمد", "84760f70"], "d": ["أُخذت قندهار، التي كانت منذ 1281 في يد الكرتيين أصحاب هراة التابعين للإيلخانيين، في أثناء حملات تيمور على خراسان، وأُعطيت لحفيده بير محمد؛ وصارت المدينة بعد ذلك يحكمها ولاة تيموريون.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["الدلقادري خليل بك يستعيد الأبلستين من المماليك", "ee3da686"], "d": ["استعاد الدلقادري خليل بك عام 1384 الأبلستين التي آلت إلى المماليك عام 1381.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["تيمور يستولي على ديار بكر (آمد) وينهبها", "f8d200a8"], "d": ["استولى تيمور على ديار بكر في 25 أو 26 نيسان/أبريل 1394 ونهب المدينة.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["غيراردو أبياني يترك بيزا لآل ڤيسكونتي ويؤسس سيادة بيومبينو", "ac45a9dd"], "d": ["ترك سيد بيزا غيراردو أبياني المدينة لحاكم ميلانو جان غاليتسو ڤيسكونتي مقابل 200.000 فلورين. وخصّص لنفسه سيادة بيومبينو المؤلفة من بيومبينو وسوڤيريتو وسكارلينو وجزر إلبا وبيانوزا ومونتكريستو.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["ديار بكر تُعطى لقره يولوق عثمان بك — بدء سيادة الآق قويونلو", "38262401"], "d": ["أُعطيت ديار بكر، التي استولى عليها تيمور عام 1394، لقره يولوق عثمان بك عام 1401، وبذلك بدأت سيادة الآق قويونلو في المنطقة.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["أرزنجان تدخل في سيادة القره قويونلو", "5729a50b"], "d": ["بعد المطهرتن آلت أرزنجان إلى سلطان القره قويونلو قره يوسف. وعيّن قره يوسف أول الأمر بير عمر، أحد الرجال الذين يثق بهم، واليًا على المدينة.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["الأسكيا محمد يأخذ زاغة (ديا)", "24561a8c"], "d": ["استولى الأسكيا محمد، الذي اعتلى عرش سونغاي، في نهاية سنة 899 هـ بوساطة أخيه كورمينا-فاري عمر كومزاغو على مدينة زاغة (ديا) في غرب الدلتا الداخلية للنيجر.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["شيباني خان يأخذ بخارى وسمرقند", "8f8f40eb"], "d": ["استفاد محمد شيباني خان من الفوضى بين التيموريين فأخذ بخارى وسمرقند وأسس أسرة الشيبانيين (الأوزبك). وبين 1500 و1507 استولى على جميع مدن ما وراء النهر وخوارزم وخراسان تقريبًا.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["الإسبان يحتلون بجاية", "8faa0133"], "d": ["احتل الجيش الإسباني المؤلف من 8000 رجل، الذي جاء بالسفن، بجاية؛ وتملّك الذعر أهل المدينة فتركوا ديارهم.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["أغاديس تُلحق بسونغاي", "997362b0"], "d": ["ألحق سلطان سونغاي الأسكيا محمد أغاديس، مركز منطقة آير، بغاو؛ وحملت المدينة هذه التبعية حتى انهيار سونغاي في تونديبي عام 1591.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["قيام سلطنة باغرمي", "03829f94"], "d": ["أسّست قبيلة كنغا بقيادة بيرني بيسي دولة قوية مركزها ماسينيا (ماسينيا) شرق بحيرة تشاد. ويؤرَّخ تأسيس أسرة باغرمي تقليديًّا بعام 1522.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["وفاة آخر دوق من آل سفورزا وانتقال ميلانو إلى شارل الخامس", "53230b5c"], "d": ["توفي دوق ميلانو فرانشيسكو الثاني سفورزا بلا ولد في ليلة 1-2 تشرين الثاني/نوفمبر 1535. وانتقلت الدوقية إلى الإمبراطور شارل الخامس وبدأت تُدار بحاكم إسباني.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["الجنوية يستقرون في جزيرة طبرقة", "0cb474f8"], "d": ["بناءً على اتفاقية شارل الخامس مع حاكم تونس التي أذنت ببناء قلعة على الساحل وبصيد المرجان، أُسكنت في جزيرة طبرقة جماعة جنوية من بيغلي. وصارت الجزيرة قاعدة تجارية تديرها أسرة لوميليني.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["بعد وفاة همايون يأخذ الصفويون قندهار من المغول", "318eabc8"], "d": ["بعد وفاة همايون في دلهي عام 1556 استفاد الشاه طهماسب من الصراع بين الولاة المغول في قندهار وزمين داور؛ فدخلت قندهار قوة صفوية جاءت بدعوة والي زمين داور، وعيّن طهماسب ابن عمه السلطان حسين ميرزا واليًا على المدينة. وبقيت المدينة في يد الصفويين حتى 1595.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["روسيا تغزو ليفونيا وتسقط دوربات", "dcb46a8a"], "d": ["غزا إيفان الرابع ليفونيا طلبًا للمنفذ إلى بحر البلطيق وبدأ حرب ليفونيا؛ فأخذ ناروا ودوربات (تارتو) وحاصر ريفال.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["تأسيس قلعة كارلوفاتس", "9b28e6ad"], "d": ["أُسّست قلعة كارلوفاتس في منطقة الفيضان بين كوبا وكورانا لحماية كرواتيا والأراضي الوراثية النمساوية من العثمانيين؛ وبنى القلعة الأرشيدوق كارل الثاني قائد الحدود العسكرية الكرواتية.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["وثيقة تأسيس (لوكاسيو) زاموشتش", "e1157f3b"], "d": ["منح المستشار الأكبر لبولندا يان زاموسكي وثيقة تأسيس (لوكاسيو) مدينة زاموشتش.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["هدنة يام زابولسكي — ليفونيا ودوربات تنتقلان إلى بولندا", "7d02d8ad"], "d": ["وُقّعت هدنة يام زابولسكي بين بولندا-ليتوانيا وروسيا؛ وتخلت موسكو عن دعاواها في ليفونيا وأعادت أراضي بولوتسك. وبقيت دوربات (تارتو) في يد بولندا منذ 1582.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["ذكر قلعة تساريتسين لأول مرة في وثيقة", "ddf65b06"], "d": ["يذكر مرسوم القيصر فيودور إيفانوفيتش المؤرخ في 2 تموز/يوليو 1589 قلعة تساريتسين التي أُنشئت لحماية الحدود الجنوبية لنهر الڤولغا؛ ويُعدّ هذا التاريخ يوم تأسيس المدينة.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["تأسيس قلعة ساراتوف", "a3ca702c"], "d": ["أسّس الأمير زاسيكين ساراتوف قلعةً ومخفرًا لحماية طريق الڤولغا والحدود الشرقية للدولة من غارات البدو الرحّل.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["تأسيس قلعة بيليم", "baf3e7eb"], "d": ["أسّس الفويفود بيوتر غورتشاكوف بيليم على ضفة نهر تاڤدا؛ وصارت القلعة إحدى نقاط الارتكاز في التقدم الروسي في غرب سيبيريا.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["تأسيس قلعة ڤيرخوتوريه", "81be29bb"], "d": ["أُسّست نقطة ڤيرخوتوريه المحصنة على ضفة نهر تورا، في موضع مستوطنة نيرومكار القديمة؛ ويرتبط تأسيسها بالبحث عن طريق أقصر إلى سيبيريا.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["تأسيس قلعة تورينسك على ضفة تورا", "c1d8534e"], "d": ["أُسّست في عام 1600 في منطقة تورينسك الحالية قلعة تورينسك (أوستروغ) القوزاقية الروسية لجباية الضريبة؛ وهي من التحصينات التي أقامها التقدم الروسي في غرب سيبيريا على الطريق.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["الشاه عباس الأول يؤسس مدينة فرح آباد في مازندران", "cab4d0fe"], "d": ["أنشأ الحاكم الصفوي عباس الأول مدينة فرح آباد في مازندران في موضع قريب من ساحل بحر قزوين، وأسكن فيها أناسًا من أنحاء البلاد كلها. وبدأ البناء في 1020/1611.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["تأسيس قلعة براتسك الروسية على أنغارا", "e7b4be59"], "d": ["في أثناء تقدم روسيا نحو سيبيريا الشرقية أُسّست قلعة براتسك على نهر أنغارا.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-02-26:0":{"b": ["معاهدة روسكيلده — سكونه وهالاند وبلكينغه وبورنهولم تنتقل إلى السويد", "afcae41b"], "d": ["وُقّعت معاهدة روسكيلده التي أنهت حرب كارل غوستاف الأولى؛ وتركت الدنمارك-النرويج سكونه وهالاند وبلكينغه وبورنهولم للسويد.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["روسيا تؤسس قلعة بينزا على سورا", "49e8d90b"], "d": ["أُسّست بينزا قلعةً كبيرة عند ملتقى نهري بينزا وسورا؛ وبعد 1684 كوّنت الطرف الغربي لخط دفاع سيزران.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["ماركيت يؤسس البعثة الفرنسية في سو سانت ماري", "86612bcd"], "d": ["أسّس اليسوعي جاك ماركيت بعثة عند أعلى شلالات سو سانت ماري بين بحيرتي سوبيريور وهورون.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["تأسيس أول مخفر لشركة خليج هدسون (واسكاغانيش)", "07b32d57"], "d": ["أسّس ميدار شوار دي غروزييه في خليج جيمس عند مصب نهر روبرت المستوطنة التي عُدّت فيما بعد أول مخفر لشركة خليج هدسون.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["الإدارة الاستعمارية الإسبانية تؤسس بيتيك (هرموسيو)", "11e5cc04"], "d": ["أسّست الإدارة الاستعمارية الإسبانية بلدة في موضع مستوطنة أهلية قديمة؛ وأخذت البلدة عام 1828 اسم خوسيه ماريا غونزاليس دي هرموسيو.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["تأسيس قلعة أومسك الروسية عند ملتقى إرتيش-أوم", "13dcce5e"], "d": ["أُسّست أومسك قلعةً عند الطرف الشرقي لخط تحصينات إيشيم بين توبول وإرتيش؛ وصارت مدينة عام 1804.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["الجونغار يهاجمون لاسا — مقتل لاجانغ خان ودخول التبت تحت الاحتلال الجونغاري", "65beea29"], "d": ["هاجم الجيش الجونغاري بقيادة تسيرينغ دوندوب لاسا، التي كان يدافع عنها حاكم الخوشوت لاجانغ خان، من كل الجهات بعد منتصف الليل؛ وبمساندة من الداخل استولى الجونغار على المدينة ونهبوها ونهبوا قصر بوتالا أيضًا. وقُتل لاجانغ خان وهو يفرّ؛ وأقام الجونغار حكومة تبتية صورية برئاسة sTag-rtse-pa.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["جيش تشينغ يدخل لاسا — نهاية الاحتلال الجونغاري وبدء الحماية التشينغية", "083358c1"], "d": ["من الجيشين اللذين أرسلهما كانغشي إلى التبت وصلت فرقة سيتشوان بقيادة غالبي إلى لاسا بعد مسيرة شاقة وأخذت المدينة بلا مقاومة؛ فقد جمع الجونغار كل قواتهم في دام لمواجهة جيش كوكونور القادم من الشمال. وبانسحاب الجونغار من التبت أقامت التشينغ في لاسا نظام حماية دائمًا.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["حملة أغويو تؤسس حصن لوس آداس", "2031793a"], "d": ["أسّست حملة المركيز دي أغويو حصنًا (بريسيديو، أي مخفرًا عسكريًّا) في لوس آداس وأعادت إسكان البعثة؛ وصار الحصن نقطة حدود تكساس الشرقية لإسبانيا الجديدة في مواجهة لويزيانا الفرنسية.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["تأسيس مخفر كاينسك الروسي في سهوب بارابا", "b14552a8"], "d": ["من بين ثلاثة تحصينات روسية دائمة (ممرات) أُقيمت في سهوب بارابا أُسّس ممر كاينسك في الجزء الأوسط من نهر أوم عند ملتقى جدول كاينكا.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["تأسيس قلعة تروئيتسك الروسية على ضفة أوي", "623d75f2"], "d": ["أُسّست تروئيتسك قلعةً عند ملتقى أوفيلكا بنهر أوي، ونالت براءة المدينة عام 1784.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["بمرسوم إليزافيتا يؤسس مركز جمرك تيميرنيك عند مصب الدون (نواة روستوف)", "46519168"], "d": ["أصدرت الإمبراطورة إليزافيتا بيتروفنا مرسومًا بإنشاء جمرك على الدون عند مصب نهر تيميرنيك؛ ويُعدّ جمرك تيميرنيك بداية التاريخ المبكر لمدينة روستوف على الدون.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["الفرنسيون يؤسسون مخفرًا تجاريًّا في تورنتو على نهر هامبر", "18975f4c"], "d": ["أسّس الفرنسيون مخفرًا ثانيًا على نهر هامبر؛ وفي السنة التالية بنوا حصن رويّيه في موضع إكزيبيشن بليس الحالي.", "66aeb450"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["أحمد شاه الدراني يضم بلخ إلى بلاده", "12c6bbf1"], "d": ["ضمّ الحاكم الأفغاني أحمد شاه الدراني بلخ إلى مجال سيادته.", "e3ef9016"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["تأسيس قلعة بتروبافلوفسك الروسية على إيشيم", "5d16ef42"], "d": ["أُسّست بتروبافلوفسك قلعةً روسية، وصارت بسرعة مركزًا مهمًّا للتجارة بين روسيا وآسيا الوسطى والسهوب الكازاخية.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["طوارق أغاديس يأخذون مملحة بلما من كانم-برنو", "1a563a74"], "d": ["فقدت كانم-برنو، التي كانت تعاني الانحدار في القرن الثامن عشر، عدة مواضع في الصحراء عام 1759 حين انتزع طوارق أغاديس منها مملحة بلما.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["جيش الجهاد لعثمان بن فودي يأخذ زاريا", "41279ca7"], "d": ["في أثناء الجهاد الذي بدأه عثمان بن فودي، رغم فشل الهجوم الأول على ألكالاوا عاصمة غوبير، أُخذت زاريا عام 1806.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["تأسيس مدينة سلطان آباد (أراك)", "674237a0"], "d": ["في العهد القاجاري أسّس الجنرال يوسف خان الكرجي مدينة أراك الحالية وسمّاها سلطان آباد.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["تأسيس بلدة بوفورت (بوفورت ويست)", "c5cb1776"], "d": ["أُسّست بلدة بوفورت في مستعمرة الرأس البريطانية على مزرعة هويفلاكته في الكارو.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["بلخ تقع تحت احتلال أمير بخارى", "cd255a5d"], "d": ["وقعت بلخ، التي كانت تحت السيادة الأفغانية الدرانية، تحت احتلال أمير بخارى عام 1826؛ واستعادها الأفغان عام 1841.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["روسيا تؤسس قلعة أقمولا على إيشيم", "6c727ca9"], "d": ["بنت روسيا قلعة أقمولا في قراوتكول على نهر إيشيم، وجعلتها البلدة المركزية لبلاد قرغيز (قازاق) سيبيريا.", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["تأسيس تحصين كوبال — شمال يديسو يبدأ بالارتباط بروسيا", "8d4c24c6"], "d": ["أسّست روسيا، بطلب من قازاق الجوز الكبير، تحصين كوبال عند سفح ألاتاو يديسو. وبحسب المصدر سهّل هذا انضمام شمال يديسو حتى نهر إيلي إلى روسيا.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["تجار الساحل يستقرون في كازه (طابورة)", "173223b0"], "d": ["هاجر التجار القادمون من ساحل شرق أفريقيا جنوبًا بعد نزاع مع حاكم محلي؛ وأعطاهم رئيس أونيانيمبي فونديكيرا مكان إقامة قرب مركزه إيتيتيميا. وصارت هذه المستوطنة نواة مركز القوافل في طابورة.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["فولاني الحاج عمر يأخذون جني", "aa4e37f8"], "d": ["وقعت جني، التي كان لدولة ماسينا فيها حامية، عام 1861 في أيدي الفولاني بقيادة الحاج عمر.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["الحاج عمر يأخذ حمد الله — نهاية دولة ماسينا", "542f1c0d"], "d": ["هُزمت القوات المتحالفة لماسينا التي لجأ إليها بينا علي الفار من سيغو؛ وآل مركز ماسينا حمد الله إلى الحاج عمر، وأُعدم بينا علي وأحمدو أحمدو.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["براززا يؤسس فرانسيفيل", "d28410d7"], "d": ["أسّس بيير سافورنيان دي براززا باسم فرنسا مخفر فرانسيفيل على نتوء صخري مطل على نهر مباسا.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["اتفاقية الحدود بين دولة الكونغو الحرة والبرتغال — الضفة الجنوبية لمصب الكونغو للبرتغال", "08a16627"], "d": ["رُسمت بموجب الاتفاقية الموقّعة أثناء انعقاد مؤتمر برلين الحدود بين دولة الكونغو الحرة والبرتغال من مصب نهر الكونغو (زائير) إلى جدول أوانغو-أوانغو بالنهر نفسه؛ فكانت الضفة الجنوبية التي فيها سويو للبرتغال، وبقيت كابيندا شمال النهر للبرتغال.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["ساحل حضرموت (المكلا) يدخل في الحماية البريطانية", "dc824725"], "d": ["وُقّعت معاهدة حماية بين إنجلترا والياقعيين (الكعيتيين) المسيطرين على ساحل حضرموت، ومنه الشحر والمكلا؛ وتولّى الإنجليز بالكامل العلاقات الخارجية للإدارة اليافعية في الساحل.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["الفرنسيون يسيطرون على الولوف كلها", "c6d28eaa"], "d": ["سيطر الفرنسيون، الذين استعمروا المنطقة باتفاقات مع رؤساء القبائل، عام 1890 على الولوف كلها.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["الفرنسيون يحتلون جني", "b207bf62"], "d": ["احتلت القوات الفرنسية عام 1893 جني، التي كانت في يد الدولة التي أسسها الحاج عمر، وضمتها إلى السودان الفرنسي.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["تأسيس غويرو مخفرًا عسكريًّا", "bd37b323"], "d": ["أُسّست مدينة غويرو في وسط زيمبابوي الحالية مخفرًا عسكريًّا؛ وصارت فيما بعد مركزًا زراعيًّا ونالت صفة البلدية عام 1914.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["سلطنة باغرمي تدخل في الحماية الفرنسية", "59f20c32"], "d": ["عقد حاكم باغرمي غاورانغ مع فرنسا معاهدة حماية اضطرارية أمام تهديد رابح. ولما توجه رابح، ردًّا على ذلك، إلى احتلال باغرمي أحرق غاورانغ العاصمة ماسينيا بيده.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["مملكة كافا تنضم إلى الحبشة — أسر آخر ملوكها غاكي شيروتشو", "c03c44c5"], "d": ["دخلت قوات منليك الثاني بقيادة راس ولدا جورجيس كافا في آذار/مارس 1897. وبعد اشتباكات شديدة فُتحت كافا؛ وأُسر آخر ملوكها غاكي شيروتشو وسلّم نفسه في تشرين الأول/أكتوبر 1897.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["الفرنسيون يحتلون غاو", "01eabb4c"], "d": ["احتل الفرنسيون عام 1898 غاو، عاصمة السونغاي القديمة على ضفة النيجر؛ وبعد الاحتلال نمت المدينة من جديد وصارت مركز المنطقة.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["تأسيس مستودع إمداد نيروبي لسكة حديد أوغندا", "a3ce3389"], "d": ["أقام الإنجليز في الموقع الحالي لنيروبي، وكان حتى ذلك الحين منطقة مستنقعات خالية في معظمها، مستودع الإمداد لسكة حديد أوغندا التي تربط ممباسا بأوغندا.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["تقسيم أداماوا — يولا تبقى في نيجيريا الشمالية البريطانية", "11104686"], "d": ["قُسمت أداماوا بين نيجيريا الشمالية التابعة لبريطانيا والكاميرون التابعة لألمانيا؛ وصار بوبو أحمدو، الابن الرابع لأداما، أمير يولا في المنطقة البريطانية.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["معركة بورمي — نهاية السيادة السياسية لخلافة سوكوتو", "c7d87e2c"], "d": ["قُتل الخليفة محمد الطاهر، الذي فرّ بعد احتلال الإنجليز سوكوتو، في معركة جديدة مع الإنجليز؛ وانتهت السيادة السياسية لخلافة سوكوتو التي دامت نحو قرن.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["تأسيس ناكورو رسميًّا بلدةً", "d82a2d76"], "d": ["أُسّست ناكورو رسميًّا بلدةً بفضل موقعها على سكة حديد أوغندا، وصارت مركز المنتجات الزراعية في المنطقة.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["افتتاح محطة بحر آرال على خط أورنبورغ-طشقند — تأسيس مستوطنة آرالسك", "85803dcb"], "d": ["حين مرّ خط سكة حديد الإمبراطورية الروسية الرابط بين أورنبورغ وطشقند بالطرف الشمالي الشرقي لبحر آرال، افتُتحت على الساحل محطة «أرالسكويه مورييه»؛ ونشأت بجوار المحطة مستوطنة صيادين. ونالت المستوطنة عام 1938 صفة المدينة وأخذت اسم آرالسك.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["الفرنسيون يأخذون أبشه — نهاية سلطنة وداي", "3c9b117b"], "d": ["واصل الفرنسيون تقدمهم نحو الشرق فاستولوا على أبشه (أبيشة)، عاصمة وداي، وأنهوا سلطنة وداي؛ وانسحب السلطان الأخير من دون أن يستطيع إنقاذ عاصمته.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["تأسيس اتحاد جنوب أفريقيا", "7434a47f"], "d": ["وفقًا لقانون جنوب أفريقيا لعام 1909 اتحدت مستعمرات الرأس وناتال وترانسفال ونهر أورانج في 31 أيار/مايو 1910 باسم اتحاد جنوب أفريقيا التابع للإمبراطورية البريطانية؛ وصارت بريتوريا مركز السلطة التنفيذية وكيب تاون مركز السلطة التشريعية.", "4fed5a23"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["الفرنسيون يحتلون جانت (جانيت)", "f32997c8"], "d": ["احتل الفرنسيون عام 1911 جانت، وهي ناحية عثمانية تابعة لغات. وقد تقاضى مدير الناحية الشيخ عمود راتبه من الدولة العثمانية حتى هذا التاريخ.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["تأسيس أنكوريج مركزًا لسكة حديد ألاسكا", "f5014711"], "d": ["بعد أن أقرّ الكونغرس قانون سكة حديد ألاسكا في 12 آذار/مارس 1914 أقامت لجنة هندسة ألاسكا في ربيع 1915 موقع بناء السكة الحديدية في شيب كريك؛ ونشأت على الساحل مدينة خيام، وسمّى مكتب البريد في نيسان/أبريل 1915 البلدة الجديدة أنكوريج. وصارت المدينة مركز سكة حديد ألاسكا الممتدة شمالًا إلى فيربانكس.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["ربط جغبوب، المركز الصحراوي للسنوسية، بالنظام العثماني — فرمان الإعفاء من عبد المجيد", "039fce6d"], "d": ["بعد أن عاد محمد بن علي السنوسي، الذي أقام في مكة سنوات طويلة، إلى طرابلس الغرب، استقر في واحة جغبوب على الحدود المصرية وبنى زاوية كبيرة على الصخرة المشرفة؛ وتحول المكان، الذي لم يكن سوى بضعة أكواخ، إلى مدينة في وقت قصير. وفي عام 1856 أُعفيت أملاك أتباع الطريقة من الضريبة بفرمان السلطان عبد المجيد، ومُنح المريدون صلاحية جمع الزكاة. وقد جعل هذا الفرمان الواحة الواقعة على طريق القوافل الذي يربط غرب أفريقيا والسودان بالقاهرة جزءًا من النظام المالي والإداري العثماني، وعزز جغبوب مركزًا للتجارة. ويؤكد ولاء أهل المنطقة للخليفة كذلك أدب الرحلة للأميرالاي صادق المؤيد الذي زارها عامي 1884 و1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["بدء حفر قناة السويس وتأسيس بورسعيد", "cef0be8d"], "d": ["بدأت أعمال الحفر في مشروع دي لسبس، الذي وافق عليه الباب العالي في 5 يناير 1856، في 25 أبريل 1859؛ وكانت القناة ستكتمل بعد عشر سنوات، في 16 نوفمبر 1869. وشكّلت قرية الأكواخ المؤلفة من خمسة بيوت التي أُقيمت للعمال عند الطرف المتوسطي للحفر، على الشريط الساحلي بين بحيرة المنزلة والبحر، نواة بورسعيد. وأُعطيت المدينة هذا الاسم، بمعنى «ميناء سعيد»، عام 1860 على يد مسؤولي شركة القناة إهداءً إلى والي مصر آنذاك سعيد باشا. وهكذا وُلد على خريطة الدولة العثمانية ميناء جديد على شريط ساحلي لم يكن فيه أي موطن قبل ذلك.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["زيارة السلطان عبد العزيز إلى مصر وتأسيس الإسماعيلية على برزخ السويس", "bcfacf38"], "d": ["ذهب السلطان عبد العزيز إلى مصر في 3 أبريل 1863 بتشجيع من الصدر الأعظم يوسف كامل باشا، واستُقبل باحتفاء كبير؛ وكان الهدف تقوية ولاء الولاية، التي بدأت منذ تمرد محمد علي باشا القوللو تتحول فعليًا إلى دولة مستقلة، للمركز. وفي العام نفسه أُقيم على البرزخ، في تلال الجسر على ضفاف بحيرة التمساح، المركز الإداري لشركة القناة: أُقيمت أولًا قرية التمساح للمهندسين، ثم قرية العرب للعمال. ولما اهتم الخديوي إسماعيل باشا اهتمامًا وثيقًا بقناة المياه العذبة وبنى لنفسه قصرًا على هذا التل، سُمّيت المستوطنة باسمه الإسماعيلية. ويؤرَّخ تأسيس المدينة بعام 1863؛ ولا يُعرف اليوم الدقيق.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["ولاية مدحت باشا على بغداد وتوطين العشائر — تأسيس الرمادي والناصرية", "0fa98f06"], "d": ["أدار مدحت باشا، الذي أُبعد عن إسطنبول بعد إخراجه من رئاسة شورى الدولة، ولاية بغداد، التي شملت الموصل والبصرة أيضًا، بين عامي 1869 و1872 بصلاحيات واسعة، وكانت قيادة الجيش السادس في عهدته كذلك. وطبّق هنا قانون الأراضي وقانون الولايات الجديد، فوزّع الأراضي بالطابو، وربط العشائر البدوية بحياة الاستقرار وبسلطة الدولة. وكان من ثمار سياسة التوطين هذه تأسيس الرمادي على ضفة الفرات لعشيرة الدليم عام 1869، وتأسيس الناصرية في الجنوب على يد متصرف المنتفق ناصر باشا السعدون؛ ونشأت كلتاهما في مواضع لم يكن فيها موطن حتى ذلك اليوم، ودخلتا الخريطة لأول مرة في هذا التاريخ.", "7babb36f"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["تأسيس باراكوا — أول بلدة في الفتح الإسباني لكوبا", "8c033cf1"], "d": ["بدأ دييغو ڤيلاثكيث دي كوييار فتح كوبا عام 1511 بقوة عبرت من هيسبانيولا، وأسّس نويسترا سينيورا دي لا أسونسيون دي باراكوا، أول بلدة إسبانية في الجزيرة. وصارت باراكوا منطقة القاعدة للحملات التي ستتوجه إلى المكسيك في العقدين التاليين (هرنانديث دي كوردوبا وغريخالبا وكورتيس).", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["معركة سنتلا — سقوط إمارة بوتونشان المايوية وتأسيس سانتا ماريا دي لا ڤيكتوريا", "8489a7d8"], "d": ["رسا أسطول كورتيس الخارج من كوبا في مدينة بوتونشان، مدينة المايا التشونتالية عند مصب نهر غريخالبا. وفاز الإسبان في معركة سهل سنتلا بتفوقهم في الفرسان والسلاح الناري، فأسسوا مكان المدينة بلدة سانتا ماريا دي لا ڤيكتوريا. وهذه أول مستوطنة إسبانية دائمة في البر المكسيكي؛ وكانت مالينتسين (دونيا مارينا)، التي ستترجم لكورتيس، بين الهدايا المقدمة هنا.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["تأسيس بنما — أول مدينة أوروبية على ساحل المحيط الهادئ", "c0d86c22"], "d": ["أسّس والي داريين بيدرارياس دافيلا مدينة بنما على جانب المحيط الهادئ من البرزخ ونقل الإدارة الاستعمارية إليها من الساحل الكاريبي. وصارت المدينة ميناء انطلاق حملات الاستكشاف والفتح نحو الجنوب؛ وجُهّزت منها حملات فرانسيسكو بيثارو إلى بيرو.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["إخضاع تيبياكا — أول فتوحات كورتيس بعد الليلة الحزينة", "a9c27711"], "d": ["بعد أن انسحب كورتيس من تينوتشتيتلان ليلة 30 حزيران/يونيو 1520 (نوتشي ترستي) بخسائر فادحة ولجأ إلى تلاكسكالا، شنّ أول هجوم له على إمارة تيبياكا التابعة للتحالف الثلاثي. وأخذ المدينة وأسّس بلدة إسبانية باسم سيغورا دي لا فرونتيرا؛ فأُمّن الطريق بين ساحل ڤيراكروث وتلاكسكالا وهُيّئت قاعدة الزحف الثاني على العاصمة.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["تأسيس سان سباستيان دي كوليما — انفتاح إسبانيا الجديدة على ساحل المحيط الهادئ", "30332cab"], "d": ["أخضع غونزالو دي ساندوفال، أحد قادة كورتيس، وادي كوليما في غرب المكسيك وأسّس بلدة سان سباستيان دي كوليما. وصارت البلدة إحدى أولى قواعد إسبانيا الجديدة على ساحل المحيط الهادئ، وغذّت في السنوات التالية أحواض بناء السفن لرحلات استكشاف بحر الجنوب.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["تأسيس سان فرانسيسكو دي كيتو — النظام الإسباني في عاصمة الإنكا الشمالية", "7bb9f316"], "d": ["أحرق قائد الإنكا رومينيياوي كيتو، عاصمة الشمال، قبل أن يتركها للإسبان. وأسّس سيباستيان دي بنالكاثار سان فرانسيسكو دي كيتو على الأنقاض؛ فارتبط بذلك مركز دولة الإنكا الثاني بعد كوسكو بالإدارة الإسبانية، وأُديرت الحملة في شمال الأنديز من هنا.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["تأسيس ليما — عاصمة بيرو الإسبانية تُنقل إلى وادي ريماك", "1f15658c"], "d": ["أسّس فرانسيسكو بيثارو، لأن كوسكو الجبلية بعيدة عن الصلة البحرية بإسبانيا، سيوداد دي لوس ريس (ليما) في وادي ريماك على الساحل. وصارت المدينة بسرعة عاصمة نيابة الملك في بيرو ومركز الإدارة الإسبانية في أمريكا الجنوبية.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["تأسيس بوبايان — الجسر بين كيتو وبلاد المويسكا", "bf451979"], "d": ["أسّس بنالكاثار، الذي زحف من كيتو نحو الشمال، بوبايان في وادي كاوكا. وصارت المدينة الطرف الشمالي للتقدم الإسباني القادم من بيرو، وفتحت في السنة التالية الطريق إلى لقائه بكيسادا في بلاد المويسكا.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["الاستيلاء على هونزا — هزيمة الزاكي كيموينتشاتوتشا", "e8c1b661"], "d": ["هاجم غونزالو خيمينيث دي كيسادا، الذي صعد إلى الهضبة من نهر ماغدالينا، هونزا، مركز الزاكازغو أحد رأسي اتحاد المويسكا، وأسر الزاكي كيموينتشاتوتشا. وكان الذهب المأخوذ في المدينة الغنيمة الحقيقية التي غذّت شائعة إلدورادو؛ ودخل بذلك النصف الشمالي من بلاد المويسكا في السيادة الإسبانية.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["تأسيس أسونسيون — القاعدة الإسبانية على نهر باراغواي", "9a6dfa42"], "d": ["حين لم تثبت حملة ريو دي لا بلاتا في بوينس آيرس انسحب الإسبان صعودًا في النهر، وأسّس خوان دي سالازار دي إسبينوسا، استنادًا إلى التحالف الذي أُقيم مع جماعات الغواراني، نويسترا سينيورا دي لا أسونسيون. وبقيت البلدة طوال قرن مركز الإدارة الإسبانية في حوض ريو دي لا بلاتا.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["تأسيس سانتا فيه دي بوغوتا — العاصمة الإسبانية في بلاد المويسكا", "3ed6c301"], "d": ["أسّس كيسادا سانتا فيه دي بوغوتا بجانب باكاتا، مركز الزيبا. وبعد التأسيس مباشرة التقت على الهضبة نفسها أفواج الفتح القادمة من ثلاث جهات — كيسادا وبنالكاثار والقائد الألماني فيدرمان — واتفقوا على أن تُحل دعاواهم في إسبانيا. وصارت المدينة عاصمة مملكة غرناطة الجديدة.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["تأسيس سان خوان دي لا فرونتيرا دي واماننغا — قفل طريق ليما-كوسكو", "3f1cfdbf"], "d": ["كانت المقاومة التي قادها مانكو إنكا من فيلكابامبا تقطع الطريق بين ليما وكوسكو. فأسّس فرانسيسكو بيثارو لتأمين هذا الطريق سان خوان دي لا فرونتيرا دي واماننغا في منتصف المسافة بين العاصمتين؛ واسم البلدة «فرونتيرا» (الثغر) يقول غرض التأسيس مباشرة.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["إعادة تأسيس تونخا مدينةً إسبانية", "c3a12867"], "d": ["بعد عودة كيسادا إلى إسبانيا أعاد غونزالو سواريث رندون تأسيس مدينة تونخا في موضع هونزا، مركز الزاكي، على النظام الإسباني. وبذلك ارتبط النصف الشمالي من بلاد المويسكا، مثل بوغوتا، بنظام بلدي دائم ونظام الإنكوميندا.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["تأسيس سان فرانسيسكو دي كامبيتشي — المحاولة الثالثة والدائمة لفتح يوكاتان", "62af9901"], "d": ["بعد حملتين فاشلتين للاستيلاء على يوكاتان أسّس فرانسيسكو دي مونتيخو (الابن) بلدة سان فرانسيسكو دي كامبيتشي في موضع مدينة المايا كان بيتش. وصار هذا الميناء قاعدة إمداد للقوات التي ستزحف إلى داخل شبه الجزيرة، ونقطة انطلاق الحملة التي انتهت بتأسيس ميريدا بعد سنتين.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["تأسيس سانتياغو ديل نويڤو إكستريمو — بدء فتح تشيلي", "04cd7c3b"], "d": ["أسّس بيدرو دي ڤالديڤيا، الذي زحف جنوبًا من بيرو، سانتياغو ديل نويڤو إكستريمو في وادي مابوتشو. وأُحرقت البلدة في أيلول/سبتمبر من السنة نفسها بهجوم السكان الأصليين بقيادة ميتشيمالونكو ثم أُعيد تأسيسها؛ ومع ذلك أُديرت منها الفتح الإسباني لتشيلي.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["إمارة كوكوم في سوتوتا تدخل في السيادة الإسبانية", "db6a6487"], "d": ["قاومت سوتوتا، إحدى أقوى إمارات المايا في داخل يوكاتان، التقدم الإسباني زمنًا طويلًا تحت أسرة كوكوم. وفي السنوات التي تلت تأسيس ميريدا عام 1542 قبلت الإمارة السيادة الإسبانية؛ وبعد قمع التمرد الشرقي الكبير في 1546-47 صارت هذه التبعية دائمة.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["تأسيس ڤيّا دي أوروبيسا — استيطان وادي الحبوب الذي سيغذي بوتوسي", "d6821cbf"], "d": ["أُسّست ڤيّا دي أوروبيسا في وادي كوتشابامبا بأمر نائب الملك فرانسيسكو دي توليدو. ونُظمت أرض الوادي الخصبة منطقة حبوب تغذي القوى العاملة الكثيرة في مناجم فضة بوتوسي؛ وصارت البلدة مخزن غلال بيرو العليا الاستعمارية.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["سقوط فيلكابامبا — نهاية دولة الإنكا المستقلة", "31b5a95d"], "d": ["بعد سقوط كوسكو عام 1533 حافظ مانكو إنكا وخلفاؤه في جبال فيلكابامبا على دولة إنكا مستقلة دامت أربعين سنة. فاستولت الحملة التي نظمها نائب الملك فرانسيسكو دي توليدو على العاصمة المهجورة؛ وأُمسك توباك أمارو، آخر الحكام الفار، وأُحضر إلى كوسكو وأُعدم هناك. وبذلك انتهى الوجود السياسي لأسرة الإنكا ذات القرون الأربعة في عالم الأنديز.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["تأسيس مونتيري — عاصمة نويڤو ليون", "ec6e44bc"], "d": ["أسّس دييغو دي مونتيمايور، بعد محاولتين فاشلتين، سيوداد ميتروبوليتانا دي نويسترا سينيورا دي مونتيري عند نبع سانتا لوسيا. وصارت هذه المستوطنة على الحدود الشمالية نقطة ارتكاز التوسع الدائم لإسبانيا الجديدة نحو الشمال الشرقي (نويڤو ليون).", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["تأسيس سان فرانسيسكو دي بورخا — السيادة الإسبانية في مايناس", "7ee32d19"], "d": ["أسّس دييغو باكا دي ڤيغا سان فرانسيسكو دي بورخا أسفل مضيق بونغو دي مانسيريتشي على نهر مارانيون، فربط منطقة مايناس بالإدارة الإسبانية. وصارت البلدة نقطة انطلاق شبكة البعثات اليسوعية التي ستستمر في أعالي الأمازون القرن التالي.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["تأسيس بعثة سان أنطونيو دي ڤاليرو — نواة تكساس الإسبانية", "ca9bd147"], "d": ["ردًّا على تسلل الفرنسيين من لويزيانا نحو الغرب قررت إسبانيا إقامة امتداد دائم في تكساس. فأسّس الأب أوليڤاريس بعثة سان أنطونيو دي ڤاليرو على ضفة نهر سان أنطونيو؛ وبعد بضعة أيام أقام الحاكم ألاركون بجانبها حصن سان أنطونيو دي بيخار. وسيُعرف مبنى البعثة فيما بعد باسم ألامو.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["تأسيس ريفوخيو (ماتاموروس الحالية) — استيطان مصب ريو غراندي", "f3b86da7"], "d": ["ملأ برنامج الاستيطان في نويڤو سانتاندير الذي نفّذه خوسيه دي إسكاندون منذ عقد 1740 الحوض الأدنى لريو غراندي بالمزارع والبلدات. وأُسّست نويسترا سينيورا ديل ريفوخيو دي لوس إستيروس على الضفة الجنوبية للنهر إحدى آخر حلقات هذا البرنامج؛ وأخذت اسم ماتاموروس في القرن 19.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["إعلان استقلال أمريكا الوسطى — القيادة العامة لغواتيمالا تنفصل عن إسبانيا", "f998089a"], "d": ["بعد خطة إيغوالا في المكسيك أعلن المجلس المنعقد في غواتيمالا استقلال القيادة العامة عن إسبانيا؛ وبقي القائد العام غابينو غاينثا على رأس الإدارة الانتقالية. وبذلك انتهت السيادة الإسبانية في أراضي غواتيمالا والسلفادور وهندوراس ونيكاراغوا وكوستاريكا الحالية. وبعد أن انضمت المنطقة زمنًا قصيرًا إلى الإمبراطورية المكسيكية أسست عام 1823 ولايات أمريكا الوسطى المتحدة.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["تأسيس نويڤا هلڤيتيا — المكسيك تفتح وادي ساكرامنتو للاستيطان", "067a1f2a"], "d": ["أسّس المهاجر السويسري جون سوتر، بإذن وامتياز أرض نالهما من السلطات المكسيكية، نويڤا هلڤيتيا عند ملتقى نهري ساكرامنتو وأمريكان. وصارت المزرعة المحصنة أقصى مخفر للمكسيك في داخل ألتا كاليفورنيا؛ وستتحول بالعثور على الذهب عام 1848 إلى مركز الهجرة إلى كاليفورنيا.", "1c5eab3d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["ريتيا ونوريكوم تُضمّان إلى روما: تيبيريوس ودروسوس يستوليان على ما وراء الألب", "be6f2a15"], "d": ["في عام 15 ق.م هزم تيبيريوس ودروسوس قبائل الألب وأتمّا ضم ريتيا (وضم نوريكوم)؛ وصارت الضفة العليا للدانوب حدًّا لروما.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["بوفاة أمينتاس تصير غلاطية ولاية رومانية", "e4250ad7"], "d": ["لما قُتل أمينتاس، ملك الغلاطيين الذي عيّنه أنطونيوس، في كيليكية (25 ق.م)، حوّل أغسطس غلاطية إلى ولاية رومانية وضمّ إليها بيسيدية ولايكاونية. وصارت أنقرة (أنكيرا) عاصمتها؛ وفيها كُتب نقش أغسطس «Res Gestae» (Monumentum Ancyranum).", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["أوكتافيانوس ينال لقب «أغسطس»: بدء عهد البرنسيباتوس (الإمبراطورية)", "310297b6"], "d": ["في 16 كانون الثاني 27 منح مجلس الشيوخ أوكتافيانوس لقب أغسطس؛ ونال أوكتافيانوس قيادة (imperium) معظم الولايات لمدة طويلة. ويُعدّ هذا التاريخ بداية الإمبراطورية الرومانية.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["وفاة بوخوس الثاني؛ وانتقال موريطانية إلى سيطرة أوكتافيانوس", "414fa36c"], "d": ["لما مات بوخوس الثاني دون ولد في 33، دخلت موريطانية في الحكم الروماني بتولي أوكتافيانوس لها بالوصية؛ وبقيت مدة تحت الحكم الروماني المباشر ثم أُعطيت ليوبا الثاني في 25.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["أنطونيوس يجعل أرخيلاوس ملكًا على كبادوكية", "1e83e691"], "d": ["منح أنطونيوس عرش كبادوكية لأرخيلاوس عند إعادة تنظيمه الشرق؛ وحكم أرخيلاوس حتى استدعاه تيبيريوس إلى روما في 17 م. وصارت كبادوكية ولاية رومانية في 17 م (وهذا الحدث بند مستقل في الكرونولوجيا).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["فيليبي: أوكتافيانوس وأنطونيوس يهزمان بروتوس وكاسيوس", "4386016f"], "d": ["جرت معركتان منفصلتان قرب فيليبي في تشرين الأول 42؛ فانتحر كاسيوس وبروتوس وزالت القوة الجمهورية. واقتسم الحكام الثلاثة العالم الروماني فيما بينهم.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["يوليوس قيصر يأمر بإعادة تأسيس قورنثة مستعمرةً رومانية", "283a5daa"], "d": ["قبيل اغتيال قيصر بقليل أُسكن في قورنثة مستعمرون من المواطنين الرومان (معظمهم من المعتقين)؛ وصارت المدينة من المراكز المهمة في ولاية أخائية الرومانية. وقرار إعادة التأسيس يعود إلى عام 44 ق.م، والاستيطان إلى 44/43 ق.م.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["مقتل بوريبيستا: تفكك مملكة الداقيين", "9b9edb14"], "d": ["يكتب سترابون أن بوريبيستا قُتل بانقلاب داخلي قبل وفاة قيصر، وأن المملكة قُسّمت إلى خمسة أجزاء ثم أربعة. ولم يُعَد تكوين وحدة داقيا حتى ديكيبالوس (87 م).", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["مقتل قيصر في مجلس الشيوخ في أيدس مارس (15 آذار)", "18649074"], "d": ["طعن جماعة من أعضاء مجلس الشيوخ قيصر، الذي أُعلن ديكتاتورًا مدى الحياة، بالخناجر في 15 آذار 44 في اجتماع لمجلس الشيوخ بمسرح بومبيوس. وهيّأ موته الأرضية لحروب أهلية جديدة ولسلطة أغسطس.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["موندا: قيصر يهزم ولدَي بومبيوس", "e1e93362"], "d": ["في 17 آذار 45 هزم قيصر في موندا جيش غنايوس بومبيوس وسكستوس بومبيوس؛ وبقيت هسبانيا في يد قيصر. وهي آخر المعارك الكبرى في الحرب الأهلية.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["ثابسوس: قيصر يهزم يوبا الأول؛ ونوميديا الشرقية تصير ولاية إفريقيا الجديدة", "77b28c50"], "d": ["في ربيع 46 كسر قيصر في ثابسوس جيش سكيبيو ويوبا الأول؛ وانتحر يوبا. وصار القسم الشرقي من نوميديا ولاية إفريقيا الجديدة التي حكمها سالوستيوس، وأُعطي القسم الغربي لبوخوس وسيتيوس.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["زيلا: قيصر يهزم فارناقس الثاني («veni vidi vici»)", "11bf082a"], "d": ["حاول فارناقس الثاني، ابن ميثريداتس، الإفادة من الحرب الأهلية لاسترداد بونطس؛ فهزمه قيصر في زيلا عام 47 وأعاد تنظيم بونطس تحت السيطرة الرومانية. ولجأ فارناقس إلى البوسفور وهلك هناك.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["فرسالوس: قيصر يهزم بومبيوس", "e821abe8"], "d": ["بعد انسحابه عند دورّاخيوم، كسر قيصر في فرسالوس جيش بومبيوس الأكبر. ولجأ بومبيوس إلى مصر وقُتل فيها؛ وانفتحت ولايات الشرق أمام قيصر.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["أليزيا: قيصر يحاصر فرسنجتوريكس ويهزمه، وتنكسر مقاومة بلاد الغال", "d57cab9f"], "d": ["أُخمدت ثورة بلاد الغال بقيادة فرسنجتوريكس الأرفرني عام 52 ق.م بحصار قيصر لأليزيا ودفاعه عن خط الحصار؛ واستسلم فرسنجتوريكس. ودخلت غاليا في العام التالي بالكامل تحت السيطرة الرومانية.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["بدء حملة قيصر على بلاد الغال: هزيمة الهلفيتيين", "1e594bb3"], "d": ["في عام 58 ق.م أوقف قيصر، بصفته والي غاليا القريبة والبعيدة، هجرة الهلفيتيين قرب بيبراكتي؛ ثم هزم جرمان أريوفيستوس. واستمرت الحملة ثماني سنوات وانتهت بضم بلاد الغال إلى روما.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["ميثريداتس السادس يموت في بانتيكابايون؛ والبوسفور يبقى لفارناقس", "0831b871"], "d": ["انتحر ميثريداتس، الفارّ من بومبيوس، في قلعة بانتيكابايون إثر ثورة ابنه فارناقس (63). وسلّم فارناقس البوسفور لبومبيوس واعتُرف به ملكًا صديقًا لروما.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["بومبيوس يوحّد بيثينية وغرب بونطس ويؤسس ولاية بيثينية وبونطس", "b2865ea8"], "d": ["في ترتيبه للشرق (65-63) وحّد بومبيوس بيثينية مع النصف الغربي من بونطس فأنشأ ولاية بيثينية وبونطس؛ وأُعطيت المناطق الداخلية من بونطس في الشرق لأمراء محليين.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["بومبيوس يعترف بكوماجين صديقةً وحليفةً لروما", "a48ba55c"], "d": ["أقرّ بومبيوس في ترتيبه للشرق مملكة أنطيوخس الأول وجزءًا من منطقة سلوقية (زيوغما) فجعل كوماجين حاجزًا حليفًا بين روما وبارثيا. وضُمت المملكة إلى روما ولاية في 17 م، وبصورة دائمة في 72 م (وهذان الحدثان بندان مستقلان في الكرونولوجيا).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["بومبيوس يهزم ميثريداتس؛ وبونطس تُضم إلى روما", "8f3f50a6"], "d": ["كسر بومبيوس ليلًا جيش ميثريداتس في سهل ليكوس عام 66؛ وفرّ ميثريداتس من كولخيس إلى البوسفور. ودخلت مدن بونطس الساحلية تحت سيطرة روما، وتشكلت الولاية التي وُحّدت مع بيثينية في 63.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["أنطيوخس الأول ثيوس يعتلي عرش كوماجين", "b1680d3f"], "d": ["بنى أنطيوخس الأول، ملك كوماجين، ضريحه ومعبده على جبل نمرود الذي يجمع بين الأصل الفارسي والمقدوني. وكانت المملكة حاجزًا بين روما وبارثيا.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["قورينة تُجعل ولاية رومانية (قيريناييكا)", "f9993ffb"], "d": ["بعد عشرين عامًا من إيصاء بطلميوس أبيون بمملكته لروما (96)، أدخلت روما قورينة (قيريناييكا) في نظام الولايات؛ وضُمت إلى كريت في 67.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["نيكوميديس الرابع يوصي بمملكته لروما", "e29d9fbc"], "d": ["بوفاة نيكوميديس الرابع (75/74) آلت بيثينية بالوصية إلى الشعب الروماني؛ ولم يقبل ميثريداتس السادس ذلك فبدأت حرب ميثريداتس الثالثة. وتحولت بيثينية إلى ولاية رومانية مباشرة.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["بوريبيستا يوحّد قبائل الداقيين والجيتيين", "3648f92e"], "d": ["وفق سترابون جمع بوريبيستا الجيتيين والداقيين في مملكة واحدة، وقام بحملات جنوب الدانوب حتى حدود تراقيا وإليريا. وبدأت المملكة تشكل تهديدًا لروما على امتداد الدانوب.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["سلام داردانوس: ميثريداتس ينسحب من آسيا وبيثينية", "535818ed"], "d": ["في سلام داردانوس المعقود مع سولا قبل ميثريداتس إخلاء جميع فتوحاته (آسيا وبيثينية وكبادوكية وبافلاغونيا) وتسليم 70 سفينة و2000-3000 تالنت. لكن سيطرة أعداء سولا في روما أفضت إلى حرب ميثريداتس الثانية.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["ميثريداتس يحتل ولاية آسيا؛ وفاسبرز أفسس (مذبحة 80.000 روماني)", "3986833b"], "d": ["في بداية حرب ميثريداتس الأولى (89/88) احتل ميثريداتس بيثينية وولاية آسيا، وبأمره في أفسس قُتل المواطنون الرومان قتلًا جماعيًا. وانحازت أثينا أيضًا إلى جانب بونطس (أريستيون).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia: روما تمنح حلفاءها الإيطاليين المواطنة (الحرب الاجتماعية)", "f72ba27d"], "d": ["إثر ثورة حلفاء روما الإيطاليين (91-88) منح قانون Lex Iulia (90) وقانون Lex Plautia Papiria (89) المواطنة الرومانية للحلفاء المخلصين والمستسلمين. وبذلك صارت شبه الجزيرة الإيطالية حتى نهر البو مجتمع مواطنين واحدًا.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["سولا يُجلس أريوبرزانس على عرش كبادوكية", "8bdd078c"], "d": ["في مواجهة إمساك ميثريداتس السادس بكبادوكية عن طريق ملك طفل، أعلنت روما أريوبرزانس ملكًا أثناء ولاية سولا على كيليكية. وصارت كبادوكية في القرن التالي حاجزًا في صراعات روما وفارس وبونطس.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["بطلميوس أبيون يوصي بقورينة لروما", "5edef477"], "d": ["ترك بطلميوس أبيون، حاكم قورينة، مملكته للشعب الروماني حين مات دون ولد (96)؛ فأبقى مجلس الشيوخ المدن حرة، وأخّر روما تحويلها إلى ولاية حتى 74.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["بوخوس يسلّم يوغرطة إلى روما؛ وغرب نوميديا يُضم إلى موريطانية", "7619ad15"], "d": ["تصالح بوخوس الأول، ملك موريطانية وحمو يوغرطة، مع روما بتسليمه يوغرطة إلى سولا؛ وتُرك له في المقابل القسم الغربي من نوميديا. ومات يوغرطة في السجن بروما عام 104.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["بايريسادس الخامس يترك المملكة لميثريداتس السادس: البوسفور يُضم إلى بونطس", "835bbe74"], "d": ["تنازل بايريسادس الخامس، تحت ضغط السكيثيين، عن المملكة لميثريداتس بمعونة قائده ديوفانتوس؛ فصار البوسفور بذلك امتدادًا شماليًا لبونطس. وانتقلت إلى بونطس في هذا التاريخ تجارة الحبوب في البحر الأسود مصدرًا لميثريداتس.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["قائد ميثريداتس ديوفانتوس يهزم السكيثيين في القرم", "d8d48c68"], "d": ["هزم ديوفانتوس جيش بالاكوس بن الملك السكيثي سكيلوروس، واستولى على ما حول نيابوليس في تاوريكا؛ وضُم البوسفور وخرسونيسوس إلى بونطس.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["يوغرطة يستولي على سيرتا: روما تتدخل في شؤون نوميديا", "660eb34a"], "d": ["حاصر يوغرطة سيرتا عام 112 ق.م وقتل أدرباعل؛ ودفع قتلُ التجار الإيطاليين في المدينة روما إلى إعلان الحرب على يوغرطة. واستمرت الحرب حتى 105.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["تأسيس ناربو مارتيوس: غاليا الجنوبية (غاليا ما وراء الألب) تصير ولاية رومانية", "20c4bdfa"], "d": ["دخلت روما بلاد الغال بنداء استغاثة من ماسّاليا (125)، واستولت على وادي الرون بانتصاراتها عند أكوا سكستيا (122) وعلى الألوبروجيين؛ وفي عام 118 ق.م أُسست ناربو مارتيوس أول مستعمرة رومانية في بلاد الغال. وصارت المنطقة ولاية غاليا ما وراء الألب.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["ميثريداتس السادس أوباتور يعتلي عرش بونطس", "c2d5fd41"], "d": ["اعتلى ميثريداتس السادس العرش طفلًا بوفاة ميثريداتس الخامس (120/119)، وبعد سنوات قليلة من الوصاية جعل بونطس قوة منافسة لروما حول البحر الأسود.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["روما تدخل بلاد الغال بنداء ماسّاليا", "eaf7eb0a"], "d": ["لما طلبت ماسّاليا، التي كانت تحت ضغط السالويين والليغوريين، العون من روما، أرسلت روما جيشًا إلى جنوب بلاد الغال عام 125. وأفضى هذا التدخل إلى تأسيس ناربو مارتيوس (118) وإلى ضم غاليا ما وراء الألب.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["هزيمة أريستونيقوس؛ وتأسيس ولاية آسيا من أراضي برغاموم", "7ccdc59e"], "d": ["هُزم أريستونيقوس، الذي ادعى العرش باسم أوميني الثالث، أمام الجيش الروماني وأُسر (129)؛ وبترتيب مانيوس أكويليوس صارت مملكة برغاموم القديمة ولاية آسيا. وكان نظام الضرائب في الولاية (publicani) مصدر دخل كبير لروما.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["سقوط نومانتيا: ضم كلتيبيريا إلى روما", "ced07244"], "d": ["تسلّم سكيبيو أيميليانوس نومانتيا بالمجاعة بعد حصار دام ثمانية أشهر (133)؛ ودُمرت المدينة. وانتهت الحروب الكلتيبيرية وضُمت المنطقة الداخلية من هسبانيا القريبة إلى روما.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["حرب أخائية: الحلف الأخائي يُهزم أمام روما وتُحلّ الأحلاف", "e434cfe0"], "d": ["هُزم الحلف الأخائي، الذي تمرد على روما بسبب نزاع حدودي مع إسبرطة، في لوكوبيترا عام 146؛ ودُمرت قورنثة وحُلّ الحلف فعليًا، ودخل جزء من اليونان تحت إشراف ولاية مقدونيا.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["انتهاء حرب بونيقية الثالثة: تدمير قرطاجة وتأسيس ولاية إفريقيا", "522515b4"], "d": ["بعد حصار دام ثلاث سنوات استولى ب. كورنيليوس سكيبيو أيميليانوس على قرطاجة في ربيع 146؛ فأُحرقت المدينة ودُمرت وضُمت أراضيها إلى روما. وصار ظهير قرطاجة ولاية إفريقيا؛ وبقيت نوميديا ماسينيسا جارةً في الغرب.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["مقدونيا تصير ولاية رومانية", "dc6d2352"], "d": ["بعد إخماد ثورة أندريسكوس (148) جُمعت المناطق الأربع في مقدونيا في ولاية رومانية واحدة (146)؛ وتُركت الرقابة على اليونان جنوب الولاية لإشراف والي مقدونيا. وشُقّ طريق إجناتيا في السنوات التالية من الأدرياتيكي إلى سالونيك.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["ثورة أندريسكوس: إعادة إقامة مملكة مقدونيا لفترة وجيزة وقمع ميتيلوس لها", "0119ff73"], "d": ["وحّد أندريسكوس، الذي ادعى أنه ابن برسيوس، مقدونيا من جديد في 150/149 وهزم أولى القوات الرومانية؛ وفي 148 استردّ ميتيلوس مقدونيا. وكانت الثورة سبب ربط مقدونيا بالحكم الروماني المباشر.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["روما تعلن الحرب على قرطاجة: بدء حرب بونيقية الثالثة", "2e34c235"], "d": ["عُدّ دفاع قرطاجة عن نفسها ضد هجمات ماسينيسا نقضًا للمعاهدة؛ فأعلنت روما الحرب عام 149 وضمّت أوتيكا إليها. وصمدت مدينة قرطاجة ثلاث سنوات تحت الحصار.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["ماسينيسا يهاجم أراضي قرطاجة: الحرب النوميدية القرطاجية", "b47559a5"], "d": ["إثر استيلاء ماسينيسا على أراضٍ قرطاجية (151/150) أعلنت قرطاجة الحرب وهُزمت أمام ماسينيسا؛ وعدّت روما ذلك نقضًا للمعاهدة وأعلنت الحرب عام 149. ومات ماسينيسا عام 148 وهو في التسعين من عمره.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["نهب روما لإبيروس: تدمير سبعين مدينة", "456fb461"], "d": ["بعد حرب مقدونيا الثالثة نُهبت مدن الملوسيين في إبيروس التي بقيت قريبة من برسيوس بأمر أيميليوس باولوس، واستُعبد نحو 150.000 شخص. وبقيت إبيروس فقيرة في القرن التالي تحت الهيمنة الرومانية.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["روما تقسم مقدونيا إلى أربع مناطق ذاتية الإدارة (merides)", "7a795ba0"], "d": ["بقرار من مجلس الشيوخ (167 ق.م) قُسمت مملكة مقدونيا إلى أربع مناطق مراكزها أمفيبوليس وتسالونيكي (سالونيك) وبيلا وبيلاغونيا؛ ومُنع التزاوج وتملّك العقارات بين المناطق، وقُيّد استغلال المناجم.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["روما تأخذ ليكية وكاريا من رودس؛ وإعلان ديلوس ميناءً حرًّا", "09c8143f"], "d": ["عوقبت رودس في حرب مقدونيا الثالثة على محاولتها التوسط بين روما وبرسيوس: فانتزع مجلس الشيوخ ليكية وكاريا من رودس وأعلنهما حرتين، وأعطى ديلوس لأثينا وحوّلها إلى ميناء معفى من الجمارك. وانخفض دخل رودس التجاري انخفاضًا شديدًا.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["بيدنا: أيميليوس باولوس يهزم برسيوس؛ وانتهاء مملكة الأنتيغونيين", "a59c5270"], "d": ["في 22 حزيران 168 هزمت الفيالق الرومانية الكتيبة المقدونية في بيدنا فأنهت حرب مقدونيا الثالثة؛ واستسلم برسيوس في ساموثراكي وسيق إلى روما لموكب النصر. وانتهت أسرة الأنتيغونيين.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["سلام أباميا: أوميني الثاني ينال لبرغاموم خرسونيسوس تراقيا ومعظم فريجيا وليديا وميسيا", "f25ed9af"], "d": ["بعد الهزيمة في مغنيسيا وقّع أنطيوخس الثالث سلامًا مع روما في 188: فتخلى عن شمال جبال طوروس. وأُعطي معظم هذه الأراضي لبرغاموم حليفه أوميني الثاني (خرسونيسوس تراقيا، وفريجيا الكبرى، وليديا، وميسيا، وجزء من أيونيا).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["سلام أباميا: رودس تنال ليكية وجنوب كاريا", "aa5173c6"], "d": ["بعد مغنيسيا أعطت روما حليفتها رودس ليكية والقسم الواقع جنوب مياندر من كاريا. وفقدت رودس هذه الأراضي في 167.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["مانليوس فولسو يهزم قبائل الغلاطيين: استقلال الغلاطيين يدخل تحت إشراف روما", "30ae73d7"], "d": ["بعد مغنيسيا اجتاح كن. مانليوس فولسو بلاد الغلاطيين وكسر التوليستواجيين والتكتوساجيين في أولمبوس وماغابا؛ وقبل الغلاطيون بمعاهدة ألا يعتدوا على جيرانهم. وبقيت غلاطية مستقلة في معظمها لكنها ارتبطت بميزان القوى بين روما وبرغاموم.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["أيتوليا تصالح روما: تفقد أمبراكيا وأوينيادي وتعترف بسيادة روما", "f332c6bf"], "d": ["صالحت أيتوليا، التي وقفت في حرب أنطيوخس إلى جانب أنطيوخس، روما بعد حصار فولفيوس نوبيليور لأمبراكيا؛ فاعترفت بـ«عظمة» روما ودفعت تعويضًا وتركت مدنًا مثل أمبراكيا وأوينيادي.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["مغنيسيا عند سيبيلوس: روما وبرغاموم تهزمان أنطيوخس الثالث", "f650ef21"], "d": ["في شتاء 190/189 كسر ل. سكيبيو وأوميني الثاني جيش أنطيوخس الثالث في مغنيسيا. وبعد النصر أفضى سلام أباميا (188) إلى تخلي أنطيوخس عن شمال طوروس.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["إسبرطة تنضم إلى الحلف الأخائي: فيلوبويمن يضم لاكونيا إلى الحلف بعد نابيس", "2629b6e1"], "d": ["بعد مقتل الطاغية الإسبرطي نابيس (192) ضم الاستراتيجوس الأخائي فيلوبويمن إسبرطة إلى الحلف الأخائي بالقوة. وفقدت إسبرطة استقلالها كليًا بهدم أسوارها عام 188.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["فلامينينوس يعلن حرية اليونانيين في ألعاب برزخ قورنثة", "3d850bf2"], "d": ["بعد كينوسكيفالاي أعلن القائد الروماني ت. كوينكتيوس فلامينينوس في ألعاب البرزخ عام 196 ق.م أن الحاميات المقدونية في قورنثة وخالكيس وديمترياس ستنسحب، وأن المدن اليونانية «حرة معفاة من الضرائب خاضعة لقوانينها». وبذلك استقرت روما في اليونان حكَمًا.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["كينوسكيفالاي: روما تهزم فيليبوس الخامس؛ ومقدونيا مضطرة إلى الانسحاب من اليونان", "9cb44ca6"], "d": ["في حزيران 197 كسرت فيالق فلامينينوس الرومانية الكتيبة المقدونية في كينوسكيفالاي. وفي سلام 196 ترك فيليبوس جميع مواقعه في اليونان (ديمترياس وخالكيس وقورنثة)، وسلّم أسطوله ودفع 1000 تالنت.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["تأسيس ولايتين رومانيتين في هسبانيا: القريبة والبعيدة", "1baa8383"], "d": ["قُسمت الأراضي التي أُخذت من قرطاجة في هسبانيا عام 197 لأول مرة إلى ولايتين منفصلتين، وتولى كلًّا منهما برايتور. ومنذ هذا التاريخ جرت حروب الكلتيبيريين واللوسيتانيين في شبه الجزيرة لتوسيع نظام الولايات الرومانية.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["السلام بعد زاما: قرطاجة تفقد هسبانيا وجزر المتوسط وأسطولها وتتحمل تعويضًا قدره 10.000 تالنت", "8654422d"], "d": ["بعد زاما (202) حصرت روما قرطاجة في أراضيها في إفريقيا: فقبلت شروط ترك هسبانيا وجزر المتوسط وتسليم الأسطول (عدا 10 سفن) ودفع 10.000 تالنت على مدى 50 عامًا وألا تعلن حربًا دون إذن روما. وصارت نوميديا ماسينيسا جارًا مستقلًا.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["روما تكافئ ماسينيسا بمملكة سيفاكس", "54ba7a64"], "d": ["في سلام زاما عيّنت روما ماسينيسا على مملكة سيفاكس وعلى أراضي الحدود المأخوذة من قرطاجة؛ وصارت مطالب ماسينيسا في منطقة «إمبوريا» وفي حدود قرطاجة سببًا للحرب فيما بعد.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["زاما: سكيبيو وماسينيسا يهزمان حنبعل", "52e188e6"], "d": ["في معركة زاما التي جرت بعد استدعاء حنبعل إلى إفريقيا هزمت فيالق سكيبيو وفرسان ماسينيسا النوميديون الجيش القرطاجي. وبهذه المعركة انتهت حرب بونيقية الثانية نهائيًا لصالح روما.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["سيفاكس يُهزم ويؤسر؛ وماسينيسا يوحّد نوميديا", "a42a3cb0"], "d": ["هزم سكيبيو وماسينيسا جيش سيفاكس عام 203 وأسرا سيفاكس؛ واستولى ماسينيسا بدعم روما على سيرتا وعلى مملكة سيفاكس. وصارت نوميديا مملكة قوية بتوحيد قسميها الشرقي والغربي.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["إيليبا وغاديس: هسبانيا تنتقل من قرطاجة إلى روما", "31e5a50c"], "d": ["هزم سكيبيو في إيليبا عام 206 جيش هاسدروبال جيسكو وماجو وأنهى السيطرة القرطاجية في هسبانيا؛ وانتقلت غاديس أيضًا إلى روما بعد قليل. وفقدت قرطاجة مناجم الفضة في هسبانيا ومخزونها من الجنود.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["فابيوس ماكسيموس يستردّ تارنتوم من حنبعل", "bd605091"], "d": ["انتقلت تارنتوم، التي استسلمت لحنبعل في 212، إلى ق. فابيوس ماكسيموس عام 209 بخيانة. وبسقوط المدينة خسر حنبعل أثمن موانئه في جنوب إيطاليا.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["سقوط كابوا في يد روما: ضياع قاعدة حنبعل في كمبانيا", "cfcb9c9a"], "d": ["حاصرت روما كابوا، التي انحازت إلى حنبعل بعد كاناي، سنتين، واستولت على المدينة رغم مناورة حنبعل بالزحف على روما وعاقبتها عقابًا شديدًا؛ وأُلغي حكم كابوا الذاتي. وتراجع حنبعل إلى الدفاع في جنوب إيطاليا.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["كاناي: حنبعل يطوّق الجيش الروماني ويبيده؛ وجنوب إيطاليا يبدأ بالانتقال إلى قرطاجة", "94f5110a"], "d": ["في كاناي في أبوليا عام 216 أباد نظام التطويق الذي اتبعه حنبعل جيشًا رومانيًا يبلغ نحو سبعين ألف رجل. وانتقلت كابوا وتارنتوم وكثير من مدن جنوب إيطاليا إلى صف قرطاجة.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["الجيش الروماني ينزل في هسبانيا: أول قاعدة رومانية في إمبوريون", "8cb47853"], "d": ["بعد زحف حنبعل إلى إيطاليا نزل كن. كورنيليوس سكيبيو في إمبوريون عام 218 ق.م فبدأ الوجود الروماني في هسبانيا على نهر إيبرو؛ وصارت شبه الجزيرة الجبهة الثانية في حرب بونيقية الثانية.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["حنبعل يعبر الألب ويدخل إيطاليا", "a1d3bf5a"], "d": ["عبر حنبعل نهر إيبرو وجبال البرانس ونهر الرون وتجاوز الألب في الخريف ونزل إلى شمال إيطاليا؛ وهزم الجيوش الرومانية عند تيكينوس وتريبيا. وبذلك انتقل مركز حرب قرطاجة في إيطاليا إلى قلب روما.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["حنبعل يستولي على ساغونتوم: اشتعال فتيل حرب بونيقية الثانية", "a497a334"], "d": ["استولى حنبعل بعد حصار دام ثمانية أشهر على ساغونتوم حليفة روما (219 ق.م)؛ وأرسلت روما سفيرًا تطالب بتسليم حنبعل، فلما رُفض الطلب أُعلنت الحرب. واستمرت الحرب سبع عشرة سنة في إيطاليا وهسبانيا وإفريقيا.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["سيلاسيا: أنتيغونوس دوسون يهزم كليومينيس؛ وإسبرطة تتعرض لأول مرة لاحتلال أجنبي", "dc64a8db"], "d": ["في صيف 222 هزم التحالف المقدوني الأخائي في سيلاسيا الجيش الإسبرطي بقيادة كليومينيس؛ ففرّ كليومينيس إلى مصر. ودخل دوسون إسبرطة وأعادها إلى نظام ليكورغوس؛ وشهد الإسبرطيون لأول مرة في تاريخهم احتلال جيش أجنبي.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["ميديولانوم (ميلانو) تسقط في يد روما: هزيمة الإنسوبريين وانفتاح شمال إيطاليا أمام روما", "d3ec639f"], "d": ["بعد هزيمتها الغاليين في تيلامون (225) سيطرت روما على معظم سهل البو بانتصار مارسيلوس في كلاستيديوم عام 222 ق.م وبالاستيلاء على ميديولانوم. ونُظمت المنطقة غاليا القريبة.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["الحلف الأخائي يعطي أكروقورنثة لأنطيغونوس دوسون: قورنثة تعود إلى مقدونيا", "c8ec9d0c"], "d": ["طلب الحلف الأخائي، تحت ضغط كليومينيس الثالث، العون من مقدونيا على يد أراتوس، وسلّم أكروقورنثة وقورنثة لأنطيغونوس دوسون؛ وأسس دوسون الحلف الهلليني (Hellenikos symmachia).", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["معاهدة إيبرو: قرطاجة تقبل ألا تعبر شمال إيبرو", "a199de0b"], "d": ["عقد هاسدروبال، الذي واصل فتح هسبانيا الذي بدأه هاميلقار، معاهدة إيبرو مع روما: ألا تعبر قرطاجة إيبرو بالسلاح. واستند هجوم حنبعل على ساغونتوم في 219 إلى تأويل هذه المعاهدة.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["روما تنتزع سردينيا وكورسيكا من قرطاجة", "4f7295ee"], "d": ["لما طلب المرتزقة المتمردون القرطاجيون في سردينيا العون من روما، احتلت روما الجزيرة؛ واضطرت قرطاجة، تحت تهديد الحرب، إلى ترك الجزيرتين ودفع 1200 تالنت إضافية. وأنشأت روما ولايتها الثانية (Sardinia et Corsica).", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["جزر إيغاتس: تدمير الأسطول القرطاجي؛ وصقلية تصير أولى الولايات الرومانية", "8bd16e8f"], "d": ["هزم لوتاتيوس كاتولوس أسطول هانّو القرطاجي أمام إيغاتس في آذار 241؛ ثم أخلت قرطاجة صقلية بسلام لوتاتيوس وقبلت دفع 3200 تالنت تعويض حرب. وصارت صقلية (عدا سيراكوزة هييرون) أول ولاية رومانية.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["أراتوس يستولي على أكروقورنثة: قورنثة تنتقل من مقدونيا إلى الحلف الأخائي", "a88dfda6"], "d": ["عطّل أراتوس السيكيوني بغارة ليلية حامية أنطيغونوس غوناتاس في أكروقورنثة وضم قورنثة إلى الحلف الأخائي؛ وانضمت ميغارا وتروزين وإبيداوروس أيضًا إلى الحلف. وفقدت مقدونيا قلعتها المفتاحية في البيلوبونيز.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["أراتوس يضم سيكيون إلى الحلف الأخائي", "6f413f9c"], "d": ["أطاح أراتوس الشاب بطاغية سيكيون وربط المدينة بالحلف الأخائي؛ ووسّعت هذه الخطوة الحلف إلى الساحلين الشمالي والجنوبي لخليج قورنثة وأدت إلى انتخاب أراتوس استراتيجوسًا.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["هييرون الثاني يتحالف مع روما: شرق صقلية يصير حليفًا لروما", "5e95a134"], "d": ["كان هييرون قد تحالف مع قرطاجة ضد روما في بدايات حرب بونيقية الأولى بسبب مسألة ميسانا؛ وفي 263 عقد مع روما سلامًا وتحالفًا وبقي حليفًا مخلصًا لروما طوال حياته (حتى 215). وصارت سيراكوزة دولة حليفة تبقى خارج الولاية في صقلية الرومانية.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["نيقوميديس الأول يؤسس نيقوميديا (إزميت)", "a89ed42a"], "d": ["أسس نيقوميديس نيقوميديا على الطرف الشرقي للخليج بعد تدمير أستاكوس؛ وصارت المدينة في القرون التالية مركز بيثينية، وفي عهد دقلديانوس مركز العاصمة الشرقية لروما.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["بدء حرب بونيقية الأولى: أبيوس كلاوديوس يعبر إلى ميسانا", "636e1533"], "d": ["لما طلب المامرتيون في ميسانا العون من قرطاجة ثم من روما ضد هييرون ملك سيراكوزة، عبر القنصل الروماني أبيوس كلاوديوس كاوديكس إلى صقلية عام 264 وانتزع ميسانا من الحامية القرطاجية. وبذلك دخلت روما لأول مرة حربًا خارج إيطاليا.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["سقوط فولسينيي: آخر مدينة كبرى مستقلة في إتروريا تنتقل إلى روما", "b6aed092"], "d": ["استولت روما عام 264 على فولسينيي التي استنجدت بها بسبب ثورة العبيد، ونقلت سكان المدينة إلى مكان جديد. ودخلت إتروريا بعد ذلك فعليًا تحت سيادة روما.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["مقتل بيروس في أرغوس", "2b4996fa"], "d": ["في حملة البيلوبونيز جُرح بيروس بقرميدة في قتال الشوارع في أرغوس ومات (272). وفقدت إبيروس ثقلها أمام مقدونيا وأعادت علاقاتها مع روما.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["تارنتوم تستسلم لروما: جنوب إيطاليا يُضم إلى روما", "6e87c924"], "d": ["بعد رحيل بيروس انسحبت حامية إبيروس من تارنتوم واستسلمت المدينة لروما (272). وصارت مدن جنوب إيطاليا اليونانية، مع بروتيوم ولوقانيا، حليفة لروما؛ وبذلك أصبحت روما سيدة شبه الجزيرة الإيطالية حتى سهل البو.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["ماليفينتوم (بنيفنتوم): بيروس ينسحب من إيطاليا", "ab67e9f5"], "d": ["فشلت عودة بيروس من حملة صقلية وهجومه من جديد على روما أمام مانيوس كوريوس دنتاتوس في ماليفينتوم؛ وعاد بيروس إلى إبيروس في 275. وترك حامية صغيرة في تارنتوم؛ وبقيت روما بلا منافس في إيطاليا.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["أنطيوخس الأول يهزم الغلاطيين في «معركة الفيلة»", "1e88c2d0"], "d": ["هزم أنطيوخس الأول الغلاطيين بفيلته فنال لقب سوتر («المنقذ»)؛ وعاد الغلاطيون إلى نظام الاستقرار وجباية الإتاوة والغارات في وسط الأناضول. واستمرت الاشتباكات مع برغاموم وبيثينية في القرون التالية.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["أنطيغونوس غوناتاس يصير ملك مقدونيا: ترسخ أسرة الأنتيغونيين", "4b907dd6"], "d": ["نال غوناتاس الشهرة بهزيمته الغلاطيين في ليسيماخيا عام 277 واستقر على عرش مقدونيا في 276. وحكمت الأسرة مقدونيا حتى 168؛ وأبقت في يدها قلاع قورنثة وخالكيس والبيرايوس في اليونان.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["نيقوميديس الأول يعبّر الغلاطيين إلى الأناضول", "9e5ab10b"], "d": ["عبّر نيقوميديس الأول ملك بيثينية القبائل الغلاطية (الكلتية) عبر البوسفور وضمها إلى خدمته ضد أخيه زيبويتس وضغط سلوقس؛ واستقر الغلاطيون فيما بعد في وسط الأناضول. وتاريخ العبور 278/277.", "62946908"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["الحلف الأيتولي يدافع عن دلفي ضد غارة الغلاطيين", "5488966a"], "d": ["اجتاز جيش برينوس الغلاطي ثرموبيلاي وتقدم نحو دلفي؛ وبددت مقاومة الأيتوليين والفوكيين الغارة. وزاد ثقل أيتوليا في أمفيكتيونية دلفي بهذا النصر.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["بيروس يعبر إلى إيطاليا لنجدة تارنتوم؛ ويهزم الرومان في هيراكليا", "55f18e85"], "d": ["نزل بيروس إيطاليا عام 280 بنداء تارنتوم ضد روما، وهزم بالفيلة والفرسان جيش فاليريوس لايفينوس في هيراكليا لكنه تكبد خسائر فادحة. وانتصر من جديد في أسكولوم عام 279، وعبر إلى صقلية في 278-276.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["إعادة تأسيس الحلف الأخائي: باتراي ودومي وتريتايا وفاراي", "81bba071"], "d": ["في أخائية الخاضعة لسيطرة الأنتيغونيين أعادت أربع مدن (دومي وباتراي وتريتايا وفاراي) تأسيس حلف اتحادي عام 280 ق.م؛ وانضمت إليه أيجيون ومدن أخرى في السنوات التالية. وتحول الحلف بقيادة أراتوس إلى قوة كبرى في البيلوبونيز.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["فيلتايروس ينتقل إلى سلوقس بعد كوروبيديون؛ وبرغاموم تؤسس فعليًا أسرة مستقلة", "ac6b3e31"], "d": ["بعد سقوط ليسيماخوس انضم فيلتايروس مع الخزينة إلى سلوقس وحفظ برغاموم وأثراها؛ وبموت سلوقس (281) استقل فعليًا. ويذكر ليفيوس أن الأسرة الأتالية حكمت برغاموم من 283 إلى 129.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["ليسيماخوس يُخرج بيروس من مقدونيا ويصير الملك الوحيد لمقدونيا", "a83e6c64"], "d": ["بعد الشتاء الذي استسلم فيه ديميتريوس لسلوقس عام 285 طرد ليسيماخوس بيروس من مقدونيا وحكم البلاد منفردًا. وبلغت دولته منطقة واسعة تشمل تراقيا ومقدونيا وغرب الأناضول.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["بيروس وليسيماخوس يقتسمان مقدونيا؛ وسقوط ديميتريوس بوليورقيتس", "63371ab8"], "d": ["في صيف 287، لما عبر ديميتريوس إلى آسيا، قسّم بيروس وليسيماخوس مقدونيا المشتركة إلى منطقتين؛ وسقط ديميتريوس. ولم يدم هذا الاقتسام إلا سنتين.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["سمنيوم تُضم إلى روما: انتهاء حرب السمنيين الثالثة", "bede9942"], "d": ["هزم مانيوس كوريوس دنتاتوس السمنيين والسابينيين هزيمة حاسمة؛ وصارت سمنيوم حليفة لروما. وصارت روما سيدة وسط إيطاليا وواجهت مدن جنوب إيطاليا اليونانية (تارنتوم).", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["إعلان ديميتريوس بوليورقيتس ملكًا على مقدونيا", "a2b1eba3"], "d": ["أفاد ديميتريوس من الصراع على العرش في أسرة كاساندروس فأعلنه الجيش ملكًا على مقدونيا في خريف 294. وهي أول سيادة لسلالة أنطيغونوس في مقدونيا؛ وانهارت في 288، وثبّتها غوناتاس في 276.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["سنتينوم: حلف الإتروسكيين والأمبريين والسمنيين والغاليين ينهزم أمام روما", "b5affc1b"], "d": ["في حرب السمنيين الثالثة قضت هذه المعركة في سنتينوم على آخر حلف كبير في إيطاليا ضد روما؛ وأُجبرت المدن الإتروسكية واحدة بعد أخرى على التحالف مع روما.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["بيروس يعود إلى عرش إبيروس بدعم بطلميوس", "6288bf69"], "d": ["عاد بيروس، الذي بقي رهينة في مصر بعد إبسوس، إلى إبيروس بمعونة بطلميوس واسترد العرش. وصار لإبيروس بعد ذلك كلمة في شؤون مقدونيا وإيطاليا.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["ليسيماخوس يودع خزينته في برغاموم؛ وفيلتايروس يصير حارس القلعة", "e1b4ab77"], "d": ["بعد إبسوس أودع ليسيماخوس خزينته في قلعة برغاموم على التل وأسند الحراسة إلى الخصي فيلتايروس. وانضم فيلتايروس إلى سلوقس في 281 ووضع أساس الأسرة.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["ميثريداتس الأول كتيستس يؤسس أسرة بونطس", "490c338c"], "d": ["نجا ميثريداتس، الذي اقترب من أنطيغونوس مونوفثالموس، عام 302 من خطر القتل ولجأ إلى كيميايتا في المنطقة الجبلية من بونطس كبادوكية، وفيها كوّن نواة مملكة بونطس. واستمرت الأسرة حتى 63.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["حصار ديميتريوس بوليورقيتس لرودس ينتهي بالفشل", "dae6f4d6"], "d": ["حاصر ديميتريوس عام 305 بآلات حصار عملاقة رودس التي بقيت إلى جانب بطلميوس ضد أنطيغونوس؛ وصمد الرودسيون سنة واحدة وتحقق السلام في صيف 304. وأُقيم في المدينة تمثال إله الشمس هيليوس (كولوسوس) بمال هذا الانتصار.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["ديميتريوس يهزم بطلميوس في سلاميس القبرصية؛ وأنطيغونوس وديميتريوس يتخذان لقب الملك", "cc308941"], "d": ["في ربيع 306 هزم ديميتريوس بوليورقيتس أسطول بطلميوس أمام قبرص ووضع قبرص في يد أنطيغونوس؛ وفي أشهر الصيف اتخذ أنطيغونوس وديميتريوس لقب الملك، وتبعهما سائر الدياذوخوي بوقت قصير. واسترد بطلميوس قبرص في 294.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["ليسيماخوس يؤسس ليسيماخيا: عاصمة في خرسونيسوس تراقيا", "83b83160"], "d": ["جعل ليسيماخوس ليسيماخيا التي أسسها عند عنق شبه جزيرة غاليبولي عاصمة لمملكته في تراقيا؛ وتجمع في يده المضيق ومعبر الدردنيل. وخربها زلزال في القرن 3 ق.م.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["سلام الدياذوخوي: أنطيغونوس يُقرّ بإدارة آسيا، وكاساندروس بإدارة أوروبا، وبطلميوس بإدارة مصر", "811c80f0"], "d": ["في السلام الموقَّع في كانون الأول 311 اعتُرف بأنطيغونوس قائدًا لآسيا وبكاساندروس استراتيجوسًا لأوروبا وبليسيماخوس لتراقيا وببطلميوس حاكمًا لمصر وما حولها؛ وأُقر مبدأ حرية المدن اليونانية. وبقيت بابل سلوقس خارج هذا السلام.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["صور تنتقل إلى أنطيغونوس: فينيقية تُنتزع من بطلميوس", "30f78257"], "d": ["دخل أنطيغونوس سوريا عام 315 واستولى على فينيقية وحاصر صور؛ وسقطت المدينة في 314. وصار الساحل الفينيقي والساحل حتى غزة في يده (وأُعيدت غزة إلى بطلميوس في 312 في معركة غزة).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["كاساندروس يؤسس سالونيك", "7043bd8a"], "d": ["جمع كاساندروس أكثر من عشرين مستوطنة شمال خليج ثرماي وأسس مدينة باسم زوجته ثسالونيكي (ابنة فيليبوس الثاني). وصارت سالونيك أهم ميناء في مقدونيا طوال الألف سنة التالية.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["كاساندروس يعيد تأسيس طيبة", "0167e784"], "d": ["أُعيدت تأسيس طيبة التي هدمها الإسكندر، بدعم كاساندروس ومعونات من أثينا وإيفويا، بعد إصلاح أسوارها. وصار للحلف البويوتي مركز من جديد.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["غابيني: أنطيغونوس يهزم أومينس ويصير سيد آسيا حتى إيران", "d2990dfd"], "d": ["في شتاء 316/5 هُزم جيش أومينس في غابيني، وسلّمه جنوده إلى أنطيغونوس فأُعدم. وصار أنطيغونوس السيد الوحيد لمنطقة واسعة تمتد من الهضبة الفارسية إلى الأناضول؛ وفرّ سلوقس إلى مصر.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["ترتيب تريباراديسوس: أنطيغونوس مونوفثالموس يصير استراتيجوس آسيا", "69f6fafb"], "d": ["بعد مقتل برديقاس في مصر (أيار 320) أعاد أنطيباتروس توزيع الساترابيات في تريباراديسوس؛ وعُيّن أنطيغونوس على رأس قوات آسيا، واستولى سلوقس على بابل. وشرع أنطيغونوس من هذا المنصب في تأسيس إمبراطوريته.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["كرانون: خسارة حرب لاميا؛ دخول حامية مقدونية أثينا وتعليق الديمقراطية", "6931c4f6"], "d": ["في 5 أيلول 322 هُزم الحلف اليوناني في كرانون أمام أنطيباتروس وكراتيروس؛ وقبلت أثينا دخول حامية مقدونية في مونيخيا وحصر معيار المواطنة بأصحاب الأملاك. وانتحر ديموستينيس، وانتهت الديمقراطية الأثينية الكلاسيكية فعليًا.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["حرب لاميا: المدن اليونانية تثور على الهيمنة المقدونية بعد وفاة الإسكندر", "c31c7da4"], "d": ["بخبر وفاة الإسكندر (حزيران 323) ثارت أثينا والحلف الأيتولي على أنطيباتروس؛ وحوصر أنطيباتروس في لاميا. وانتهت الحرب بانتصار مقدونيا في كرانون (أيلول 322)، وأعيد التفوق المقدوني في إطار حلف قورنثة.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["هيداسبس: هزيمة بوروس؛ والبنجاب يُربط بالإسكندر", "abab206b"], "d": ["في أيار 326، عبر الإسكندر نهر جيلوم بدعم راجا تاكسيلا أمبهي وهزم بوروس؛ وتُركت مملكة بوروس للإسكندر تابعة. وتقدم الإسكندر شرقًا من هذه النقطة لكنه توقف عند هيفاسيس باعتراض الجيش.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["الجيش يرفض التقدم على ضفة هيفاسيس (بياس): الحد الشرقي للإسكندر", "17b23afc"], "d": ["بسبب أمطار الرياح الموسمية والإرهاق رفض الجيش المقدوني عبور هيفاسيس؛ فأقام الإسكندر اثني عشر مذبحًا واضطر إلى العودة. وصارت هيفاسيس الحد الشرقي للفتوحات المقدونية في الهند.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["باكتريا وسوغديانا تخضعان للإسكندر؛ والإسكندر يتزوج روكسانه", "a050508d"], "d": ["بين 329 و327 فُتحت منطقة ما وراء أوكسوس بقتال عصابات مكثف؛ وقُتل سبيتامينيس، وسلّمت صخرة سوغديانا وقلعة خوريينيس. وربط الإسكندر النبلاء المحليين بالحكم بزواجه من الأميرة الباكترية روكسانه.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["الساحل الغربي للأناضول ينتقل إلى الإسكندر: أفسس وميليتوس وهاليكارناسوس", "f67084a4"], "d": ["فتحت أفسس أبوابها بنظام ديمقراطي، وفُتحت ميليتوس بعد حصار (صيف 334)؛ وانتهى حصار هاليكارناسوس في الخريف بسقوط المدينة، وأُعطيت ساترابية كاريا لآدا. وبذلك طبق الإسكندر استراتيجية الاستيلاء براً على موانئ الأسطول الفارسي.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["هدم طيبة بأمر الإسكندر", "26c4193c"], "d": ["استولى الإسكندر في الخريف على طيبة التي ثارت بوفاة فيليبوس؛ ووضع حامية مقدونية في قادميا وهدم المدينة واسترق أهلها (عدا بيت بنداروس). وانتهى الحلف البويوتي فعليًا بهذا الهدم (أعاد كاساندروس تأسيسها في 316).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["اغتيال فيليبوس الثاني في أيجاي؛ والإسكندر يعتلي العرش", "417d909e"], "d": ["حلّ محل فيليبوس، الذي قتله حارسه بوسانياس في المسرح أثناء احتفال زواج ابنته كليوباترا، ابنه الإسكندر الذي أعلنه الجيش ملكًا. وبقيت الحملة على فارس والسيطرة على اليونان للإسكندر.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["تأسيس حلف قورنثة: توحيد المدن اليونانية تحت هيمنة فيليبوس الثاني", "c38074dc"], "d": ["بعد خايرونيا جمع فيليبوس المدن اليونانية في قورنثة تحت سلام مشترك (koine eirene) وعهد دفاع مشترك؛ وتقرر الجند وقيادة الهيمون لحملة على فارس. ولم تنضم إلا إسبرطة.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["خايرونيا: فيليبوس يهزم جيش أثينا وطيبة ويتسلم السيطرة على اليونان", "5e5d77e7"], "d": ["في آب 338 في سهل خايرونيا هُزم الجيش الأثيني الطيبي بهجوم الفرسان الذي قاده الإسكندر الشاب؛ ووُضعت حامية مقدونية في طيبة، وعُفي عن أثينا بتسامح. وأنهى النصر استقلال المدن اليونانية ومهّد الطريق إلى حلف قورنثة.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["حل الحلف اللاتيني: لاتيوم تُربط بروما", "58849f84"], "d": ["في ختام الحرب اللاتينية (340-338) حلّت روما الحلف اللاتيني؛ وانضمت المدن إلى المواطنة الرومانية أو رُبطت بروما واحدة واحدة، ومُنع التحالف بينها. وهذا أساس نموذج توسع روما في إيطاليا.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["فيليبوس الثاني يهزم ملك السكيثيين أتياس", "e4dee658"], "d": ["انتهت حرب الملك أتياس مع فيليبوس على ضفاف إستروس (الدانوب) بمقتل أتياس؛ وتعرض فيليبوس في عودته لهجوم من التريباليين. وانتقلت القوة السكيثية في الغرب إلى ما وراء الدانوب.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["فيليبوس يخضع تراقيا مع أسرة الأودريسيين", "b543427a"], "d": ["تقدم فيليبوس في حملات 342-341 ق.م إلى داخل تراقيا، وفرض الجزية على الملك الأودريسي كيرسوبليبتس، وأسس مدنًا مثل فيليبوبوليس (فيليبه). وصارت تراقيا امتدادًا شرقيًا لمقدونيا.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["تدمير أولينثوس: حلف خالكيديكي ينتقل إلى مقدونيا", "89d77301"], "d": ["رغم طلب أولينثوس العون من أثينا، استولى فيليبوس على المدينة بالخيانة ودمرها؛ وضُمت شبه جزيرة خالكيديكي إلى مقدونيا. وتستند خطب ديموستينيس الأولينثية إلى هذا النداء.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["انتهاء الحرب الاجتماعية: بيزنطة وخيوس ورودس وكوس تنفصل عن حلف أثينا الثاني", "856a9763"], "d": ["انتهت الثورة التي بدأت عام 357 ق.م بهزيمة قادة أثينا في خيوس وانقلاب الدعم الفارسي ضد أثينا وقبول أثينا السلام؛ ونال أربعة أعضاء مهمين استقلالهم. وضعف الحلف وبقي عاجزًا أمام مقدونيا.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["فيليبوس يأخذ أمفيبوليس من أثينا", "2c793bc6"], "d": ["حاصر فيليبوس أمفيبوليس الأثينية عند مصب ستريمون واستولى عليها، فنال مناجم الذهب والفضة وموارد الأخشاب فيها وانفتح على الساحل التراقي. وأشعل هذا الفتح الصراع الأثيني المقدوني.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["فيليبوس الثاني يصير ملك مقدونيا", "d557268d"], "d": ["لما قُتل برديقاس الثالث في حرب مع الإيليريين (360/359 ق.م) صار فيليبوس وصيًا أولًا ثم ملكًا؛ فدفع أخطار إيليريا وبايونيا وتراقيا وأجرى إصلاح الجيش (كتيبة الساريسا). ومع هذه المملكة يبدأ صعود مقدونيا.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["مانتينيا: موت إيباميندوس وانتهاء هيمنة بويوتيا", "94be8d5c"], "d": ["فاز الجيش الطيبي بالمعركة لكن إيباميندوس جُرح ومات؛ ويختم كسينوفون بأن «الشك والاضطراب في اليونان أكثر مما قبل». وانتهت هيمنة طيبة القصيرة في العام نفسه، وبقي التوازن الأثيني الإسبرطي الطيبي.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["تأسيس الحلف الأركادي: تفكك هذا الجزء من الحلف البيلوبونيزي", "42fdc676"], "d": ["بعد لوكترا أسست مدن أركاديا حلفًا اتحاديًا بدعم طيبة وبنت العاصمة الجديدة ميغالوبوليس. وبذلك تفكك حلف البيلوبونيز لإسبرطة فعليًا؛ وانكمشت إسبرطة إلى لاكونيا وحدها.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["مسينيا تنفصل عن إسبرطة؛ وتأسيس مسيني", "e4ef9302"], "d": ["في حملة إيباميندوس على البيلوبونيز بعد لوكترا (شتاء 370/69) أُطلق هيلوتات مسينيا وأُسست مدينة مسيني القوية الأسوار عند سفح جبل إيثومي. وفقدت إسبرطة لأول مرة منذ قرون أراضي مسينيا التي شكلت أساسها الاقتصادي.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["لوكترا: الجيش الطيبي يهزم الإسبرطيين؛ وإسبرطة تفقد تفوقها البري", "e7829597"], "d": ["أفضى نظام الجناح الأيمن العميق الكثيف لإيباميندوس إلى هزيمة قوة الملك كليومبروتوس الإسبرطية في لوكترا؛ وبموت نحو 400 إسبرطي (سبارتيات) عجزت إسبرطة عن تعويض خسارتها السكانية. وبدأ عهد هيمنة بقيادة طيبة.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["تأسيس حلف أثينا الثاني (مرسوم أريستوتيليس)", "0e5dcaf2"], "d": ["دعت أثينا مدن إيجة إلى الحلف على مبدأ الاستقلال الذاتي وعدم أخذ الجزية ضد إسبرطة؛ وصدر المرسوم باقتراح أريستوتيليس وكُتبت قائمة المدن الأعضاء على الحجر. وأعاد تأسيس الحلف لأثينا قوتها البحرية.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["بيلوبيداس يحرر طيبة؛ وطرد حامية إسبرطة من قادميا", "eb15a9d7"], "d": ["استُردّت قادميا طيبة، التي احتلتها إسبرطة عام 382 ق.م وتركت فيها حامية، بغارة ليلية للمنفيين؛ وعادت طيبة مركز الحلف البويوتي. وهذا الحدث بداية تفكك هيمنة إسبرطة.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["أليا: الغاليون يهزمون الجيش الروماني وينهبون المدينة", "db864bc9"], "d": ["هزم الغاليون السينونيون الجيش الروماني على ضفة أليا، أحد روافد التيبر؛ واحتُلت روما ونُهبت عدا الكابيتوليوم. ويكتب ليفيوس أن «يوم أليا» (18 تموز) عُدّ شؤمًا عند الرومان.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["قورنثة تتحد مع أرغوس (إيزوبوليتيا أرغوس وقورنثة)", "135a3d3a"], "d": ["أقامت قورنثة أثناء حرب قورنثة (395-387 ق.م) اتحاد مواطنة مشتركة مع أرغوس؛ وبقيت حامية أرغوس في قورنثة. وأبطلت إسبرطة هذا الاتحاد بسلام الملك (386).", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["سقوط فيي في يد روما: ضياع أول مدينة إتروسكية كبرى في الجنوب", "0d1c4fe4"], "d": ["استولى كاميلوس على فيي بعد حصار دام عشر سنوات (بحسب التقليد 396 ق.م)؛ واستُرق أهلها وضُمت أراضيها إلى روما، وكاد ager Romanus لروما يتضاعف. وانكسرت قوة المدن الإتروسكية جنوب التيبر.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["أثينا تستسلم لإسبرطة؛ وانتهاء الإمبراطورية البحرية الأثينية وحلف ديلوس", "43f2ddf9"], "d": ["استسلمت أثينا بالمجاعة بعد أن فقدت أسطولها في أيغوسبوتامي؛ وهُدمت الأسوار الطويلة وتفككت الإمبراطورية البحرية، وجاء حكم الثلاثين الذي أقامه الإسبرطيون في المدينة. واستقرت في الجزر والسواحل التراقية للأعضاء السابقين في الحلف حكومات ديكارخيا التي أسسها ليساندروس وحاميات إسبرطة.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["ديونيسيوس الأول يصير طاغية سيراكوزة", "1ad10305"], "d": ["في سنوات استيلاء قرطاجة على أكراغاس وجيلا صار ديونيسيوس عام 405 استراتيجوس سيراكوزة ثم طاغيتها؛ وعقد سلامًا مع قرطاجة (405) وربط مدن صقلية اليونانية به. وجعلت سلطة ديونيسيوس التي دامت 38 عامًا صقلية إحدى القوى الكبرى في المتوسط.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["أيغوسبوتامي: تدمير الأسطول الأثيني؛ وحلف ديلوس على شفا الانهيار", "ce62187c"], "d": ["في أيلول 405 استولى ليساندروس بغارة على الأسطول الأثيني الراسي في أيغوسبوتامي؛ وفُقد الأسطول كله تقريبًا وآلاف الأسرى. وأُغلق طريق الهلسبونت وانقطع تموين أثينا بالحبوب؛ واستسلمت أثينا بعد أشهر قليلة.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["تأسيس مدينة رودس: اتحاد ليندوس وإياليسوس وكاميروس", "2de55901"], "d": ["في عام 408 ق.م أسست مدن جزيرة رودس الثلاث دولة مشتركة واتحدت في مدينة رودس الجديدة؛ وصارت المدينة التي بُنيت بمخطط هيبوداموس من أهم القواعد البحرية ومراكز التجارة في العالم الهلنستي.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["هانيبال ماغو يدمر سيلينوس وهيميرا: قرطاجة تستقر في غرب صقلية", "358f4417"], "d": ["نزل هانيبال ماغو في صقلية بنداء سيجيستا واستولى على سيلينوس وهيميرا عام 409 ق.م؛ وصارت المنطقة epikratia لقرطاجة. واستمر الصراع القرطاجي السيراكوزي قرنين.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["حملة صقلية تنتهي بالكارثة: الجيش الأثيني يُباد أمام سيراكوزة", "b363df0d"], "d": ["انتهت حملة صقلية التي بدأتها أثينا عام 415 ق.م، بعد العجز عن حصار سيراكوزة، باستسلام عند نهر أسيناروس أثناء انسحاب نيكياس وديموستينيس (خريف 413 ق.م). وفقدت أثينا جيشها ومعظم أسطولها.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["سيتالكيس يتحالف مع أثينا: مملكة الأودريسيين تدخل الحرب البيلوبونيزية", "4562f13d"], "d": ["جعلت أثينا ابن سيتالكيس مواطنًا أثينيًا وعقدت معه حلفًا؛ وهاجم سيتالكيس مقدونيا عام 429. وبلغت قوة الأودريسيين ذروتها في هذه الفترة.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["بدء الحرب البيلوبونيزية: حلف البيلوبونيز يتعبأ ضد أثينا", "2adee4a1"], "d": ["انتُهك السلام فعليًا بغارة طيبة الليلية على بلاتيا (ربيع 431)؛ وفي أوائل الصيف اجتاح جيش حلف البيلوبونيز بقيادة الملك أرخيداموس أتيكا. واستمرت الحرب 27 عامًا بين الإمبراطورية البحرية لأثينا والحلف البري لإسبرطة.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["سيبوتا: الحرب القورنثية الكورقورية تجر أثينا إلى التدخل", "dc07b0ac"], "d": ["في المعركة البحرية التي خاضتها قورنثة مع مستعمرتها كورقورا بسبب إبيدامنوس ساندت أثينا كورقورا. وكان غضب قورنثة على أثينا من الأسباب المباشرة للحرب البيلوبونيزية.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["سبارتوكوس يصير أرخونًا على البوسفور: أسرة السبارتوكيين", "ddc76f79"], "d": ["حلّ سبارتوكوس التراقي الأصل محل أسرة الأركيانكتيدين في بانتيكابايون (438/7)؛ وأسس السبارتوكيون مملكة البوسفور وأداروا تصدير الحبوب إلى أثينا. واستمرت الأسرة حتى 109 ق.م.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["سلام الثلاثين سنة: أثينا تفقد إمبراطوريتها البرية (بويوتيا وميغارا وأخائية)", "4f33ff13"], "d": ["بعد هزيمة البويوتيين الجيش الأثيني في كورونيا (447) ثم ثورات إيفويا وميغارا وغزو إسبرطة لأتيكا، وقّعت أثينا سلام الثلاثين سنة. وتركت أثينا ميغارا ونيسايا وبيغاي وتروزين وأخائية في البيلوبونيز؛ وحافظت على إمبراطوريتها البحرية وحدها.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["تيريس يؤسس مملكة الأودريسيين: أول دولة كبرى في تراقيا", "83caf189"], "d": ["يكتب ثوكيديدس أن تيريس أسس أول مملكة كبرى في تراقيا؛ وبلّغ ابنه سيتالكيس المملكة من الدانوب إلى إيجة. وانتهجت مملكة الأودريسيين سياسة توازن بين أثينا ومقدونيا وفارس.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["نقل خزينة الحلف من ديلوس إلى أثينا", "173f2e5b"], "d": ["نُقلت الخزينة المشتركة من ديلوس إلى أثينا بحجة الهزيمة في حملة مصر والخوف من الأسطول الفارسي؛ وتبدأ من هذه السنة قوائم «الستين» التي تُعطى لإلهة أثينا. ويُفسَّر هذا الإجراء علامةً على تحول الحلف عمليًا إلى إمبراطورية أثينية.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["قمع ثورة ثاسوس؛ وتحول حلف ديلوس إلى إمبراطورية لا يمكن للأعضاء الانفصال عنها", "d24bd124"], "d": ["اصطدمت ثاسوس بأثينا بسبب المناجم وحاولت الانفصال عن الحلف؛ وبعد حصار دام سنتين (463 ق.م) هدمت أسوارها وسلمت أسطولها وفقدت منطقة المناجم على الساحل التراقي. وهي أول سابقة تُظهر أن عضوية الحلف لا يمكن تركها.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["معركة كيمي البحرية: سيراكوزة تهزم الأسطول الإتروسكي، وانكسار القوة البحرية الإتروسكية", "2e81670b"], "d": ["بنداء استغاثة من كيمي هزم هييرون الأول، طاغية سيراكوزة، الأسطول الإتروسكي أمام كيمي؛ واحتفل هييرون بالنصر بإهداء خوذة إلى دلفي (خوذة إتروسكية كما ذكر ليفيوس). وتزعزعت هيمنة الإتروسكيين في كمبانيا.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["تأسيس حلف ديلوس: حلف إيجي برئاسة أثينا", "f0de153a"], "d": ["بعد أسلوب باوسانياس في الحكم طلبت المدن الأيونية القيادة من أثينا؛ وأُسست خزينة مشتركة في ديلوس بالجزية التي حددها أريستيديس (460 تالنت). ووفر الحلف لأثينا أسطولًا دائمًا على إيجة وقاعدة ضريبية.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["سلاميس (29 أيلول 480) وبلاتيا: ردّ الغزو الفارسي", "479b17e6"], "d": ["بعد أن استولى خشايارشا على أثينا وأحرقها هُزم الأسطول الفارسي في مضيق سلاميس بحيلة ثيميستوكليس (29 أيلول 480)؛ وفي العام التالي هزم الجيش البري اليوناني بقيادة باوسانياس مردونيوس في بلاتيا وأنهى الغزو. وبذلك تحررت يونان إيجة من السيادة الفارسية.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["هيميرا: يونانيو صقلية يهزمون الجيش القرطاجي", "ece09580"], "d": ["هزم حلف غيلون وثيرون جيش هاميلقار القرطاجي أمام هيميرا؛ ولم تستطع قرطاجة أن تقوم بحملة كبرى على صقلية مرة أخرى نصف قرن. ووفق هيرودوتس وديودوروس كُسبت سلاميس في اليوم نفسه (تقليد).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["ماراثون: أثينا توقف الغارة الفارسية", "0967ce7c"], "d": ["هزم الهوبليتات الأثينيون والبلاتيون بقيادة ميلتيادس القوة الفارسية في سهل ماراثون ومنعوا نزولها إلى أتيكا. وغذّى النصر ثقة الديمقراطية الأثينية بنفسها والسياسة البحرية التي امتدت بعدها إلى حلف ديلوس.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["مردونيوس يخضع مقدونيا لفارس", "7bde569c"], "d": ["عبر مردونيوس، صهر داريوس، تراقيا وأدخل مقدونيا تحت السيادة الفارسية؛ وقدم الملك المقدوني التراب والماء لفارس. وتخلصت مقدونيا من هذه التبعية بعد بلاتيا (479).", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum: روما تتحالف مع الحلف اللاتيني", "56db407d"], "d": ["بالمعاهدة التي تحمل اسم سبوريوس كاسيوس أقامت روما والحلف اللاتيني حلفًا على أساس الدفاع المتبادل واقتسام الغنائم والجيش المشترك. وهذه المعاهدة إطار العلاقات الرومانية اللاتينية حتى الحرب اللاتينية (340-338).", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["حملة حلف البيلوبونيز على أثينا تنهار بانسحاب قورنثة", "b44adf6b"], "d": ["ساقت إسبرطة جيش حلف البيلوبونيز إلى أتيكا ضد أثينا الديمقراطية بقيادة كليسثينيس؛ وأفشل الحملة انسحاب الجيش القورنثي في إليوسيس وخلاف الملكين الإسبرطيين. ويُعد الحدث أول مثال معروف لبدء عمل حق التصويت للحلفاء في مجلس الحلف.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["إصلاح كليسثينيس: وضع الأساس المؤسسي للديمقراطية الأثينية", "b2421c86"], "d": ["بعد سقوط هيبياس نظم كليسثينيس المواطنين عبر الديموس، وهي وحدات سكنية، وعبر عشر قبائل جديدة؛ وصار مجلس الخمسمئة مركز هذا النظام. وهو الترتيب الذي نشأت فيه مفهومات الإيسونوميا والديموكراتيا.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["طرد آخر الملوك تاركوينيوس سوبربوس؛ وانتهاء الملكية وبدء الجمهورية", "5a4a9061"], "d": ["وفق ليفيوس طُرد تاركوينيوس سوبربوس وأسرته من المدينة عام 509 ق.م وانتُخب أول القناصل (بروتوس وكولاتينوس). ويربط بوليبيوس أول معاهدة بين روما وقرطاجة بسنة أول القناصل؛ وبينما يُعد التاريخ «تقليدًا» في الكتابة التاريخية الحديثة فإنه يستقر في أواخر القرن 6 ق.م.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["أول معاهدة بين روما وقرطاجة (بوليبيوس 3.22)", "cdef940f"], "d": ["ينقل بوليبيوس بنصها المعاهدة المعقودة بين روما وقرطاجة في سنة أول القناصل، وهي التي تجعل سواحل لاتيوم لروما وتفصل قرطاجة في غرب صقلية وليبيا. وتُذكر روما بصفتها سيدة لاتيوم.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["معركة ألاليا البحرية: الإتروسكيون والقرطاجيون يُخرجون الفوكيين من كورسيكا", "25efbea8"], "d": ["انتصر اليونانيون الفوكيون في ألاليا على الورق لكنهم فقدوا معظم أسطولهم؛ وتركوا كورسيكا وانسحبوا إلى إيليا في جنوب إيطاليا. وقامت في الجزيرة سيادة إتروسكية (كايريه).", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["معاهدة إسبرطة وتيجيا: تشكل نواة حلف البيلوبونيز", "57098e47"], "d": ["هزمت إسبرطة تيجيا في أركاديا وحملتها على قبول حلف أبدي (symmachia) مقابل ألا تفسد أراضيها؛ وانتشر النموذج نفسه إلى مدن البيلوبونيز وولد حلف البيلوبونيز برئاسة إسبرطة. وعمل الحلف في داخله بشكل مجلس لإسبرطة والحلفاء (تحت قيادة إسبرطة).", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["الفوكيون يؤسسون ماسّاليا (مرسيليا)", "5d46bdf2"], "d": ["أسس المستوطنون الفوكيون ماسّاليا عند مصب الرون نحو 600 ق.م؛ وصارت المدينة مركز التجارة اليونانية في غرب المتوسط والاتصال بالعالم الكلتي.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["باتوس الثيري يؤسس قورينة", "67fd477f"], "d": ["أسس المستوطنون القادمون من ثيرا قورينة بقيادة باتوس وفق نبوءة دلفي؛ وحكمت أسرة الباتيادين حتى 440. ويعطي ليفيوس تاريخ التأسيس «نحو 630».", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["إسبرطة تكسب حرب مسينيا الأولى: ضم مسينيا إلى إسبرطة", "74ad461c"], "d": ["في التقليد الذي ينقله باوسانياس دامت حرب مسينيا الأولى عشرين سنة، وبسقوط إيثومي انتقل سهل مسينيا إلى إسبرطة؛ وهبط أهله إلى مرتبة الهيلوتات. وعُدّ هذا الفتح الحدث الأساسي الذي حدد قوة إسبرطة الزراعية ومجتمعها العسكري.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["تأسيس سيراكوزة على يد القورنثي أرخياس", "10217104"], "d": ["وفق ثوكيديدس أسس القورنثي أرخياس سيراكوزة بعد سنة من ناكسوس. وصارت المدينة أكبر المدن اليونانية في صقلية.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["التأسيس التقليدي لقرطاجة (تيمايوس: 814/813 ق.م)", "908099b5"], "d": ["وفق تيمايوس أسس المستوطنون الصوريون قرطاجة عام 814/813 ق.م؛ ويذكر يوستينوس 825. وتشير الطبقات الأثرية إلى أواخر القرن 8 ق.م.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["تدمير مراكز القصور الميكينية: انهيار النظام القصري في البيلوبونيز", "d2c79152"], "d": ["في نهاية الهلادي IIIB أو بداية IIIC تُظهر مراكز القصور في بيلوس وتيرينس وميكيني طبقة تدمير أو هجر؛ وينتهي اقتصاد القصور القائم على الكتابة الخطية ب. وسبب التدمير (زلزال، صراع داخلي، شعوب البحر، جفاف) محل جدل؛ وطبقات التدمير لا تعود إلى سنة واحدة بل تمتد على بضعة عقود.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["تخريب قصور مينوس في كريت؛ وبدء السيطرة الميكينية في كنوسوس", "1a7f7f2b"], "d": ["في نهاية المينوي المتأخر IB (منتصف القرن 15 ق.م) تتعرض مراكز القصور والفيلات في كريت للتدمير؛ وفي المرحلة اللاحقة في كنوسوس تدل ألواح الخطية ب على إدارة قصرية مكتوبة باليونانية، أي سيطرة ميكينية. وبذلك تنتهي الهيمنة المينوية في كريت.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["غابة تويتوبورغ: إبادة ثلاثة فيالق لفاروس؛ وروما تترك خط الإلب", "1684ae43"], "d": ["في عام 9 م أباد الحلف الجرماني بقيادة أرمينيوس الفيلق السابع عشر والثامن عشر والتاسع عشر لب. كوينكتيليوس فاروس في غابة تويتوبورغ. وتخلى أغسطس عن الفتوحات وراء الراين وترسخت حدود الراين.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["وفاة أغسطس؛ وتيبيريوس يصير إمبراطورًا", "0221344d"], "d": ["توفي أغسطس في نولا في 19 آب 14؛ وخلفه تيبيريوس. وبذلك ترسخ مبدأ التوريث (التبني من الأسرة) في البرنسيباتوس.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["قتل الملك بطلميوس بأمر كاليغولا؛ وانتهاء استقلال موريطانية", "11337627"], "d": ["قُتل بطلميوس بن يوبا الثاني في لوغدونوم عام 40 م بأمر كاليغولا؛ ثم اندلعت ثورة إيدمون في موريطانية وقسّم كلاوديوس البلاد في 44 إلى ولايتين هما طنجية وقيصرية.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["كلاوديوس يغزو بريطانيا", "f42ba7f7"], "d": ["نزلت أربعة فيالق بقيادة أولوس بلاوتيوس على ساحل كنت في عام 43 م؛ وسقطت كامولودونوم (كولشستر) وأقام كلاوديوس في المدينة وقتًا قصيرًا. وصار جنوب بريطانيا ولاية رومانية جديدة.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["روما تجعل تراقيا ولاية: انتهاء أسرة الأودريسيين", "af2ba1b2"], "d": ["إثر قتل زوجة الملك روميتالكيس الثالث ملك تراقيا له وما تلاه من فوضى حوّل كلاوديوس تراقيا عام 46 إلى ولاية رومانية. وهي من الخطوات الأخيرة التي أتمت نظام الولايات الرومانية في الشرق في البلقان.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["تراجان يفتح داقيا: سقوط ساراميزيجيتوسا ووفاة ديكيبالوس وتأسيس ولاية داكيا", "a9277172"], "d": ["في حرب الداقيين الثانية (105-106) استولى تراجان على ساراميزيجيتوسا؛ وانتحر ديكيبالوس ليفلت من الأسر. وصارت داقيا ولاية رومانية وارتبطت مناجم الذهب بالاقتصاد الروماني. المراحل السابقة للحرب (101-105) بنود مستقلة في الكرونولوجيا..", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["هادريانوس يبدأ بناء السور على الحد الشمالي في بريطانيا", "f4a886ec"], "d": ["بنى هادريانوس سور حدود على خط تاين سولواي بعد زيارته بريطانيا عام 122 م. ويرمز السور إلى سياسة روما الحدودية الدفاعية؛ وجُرّب التقدم بسور أنطونينوس (142) لكنه لم يدم.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["سبتيميوس سفيروس يجعل بلاد الرافدين ولاية؛ ونهب طيسفون", "df466924"], "d": ["في الحرب البارثية (195-198) استولى سفيروس على نصيبين ونهب طيسفون ونظم بلاد الرافدين العليا ولاية رومانية. وبلغ التقدم الأقصى لروما نحو الشرق في القرن 3 م.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana: منح المواطنة الرومانية لجميع الأحرار في الإمبراطورية", "dd4e4024"], "d": ["جعل كاراكلا الأحرار في الولايات مواطنين رومانًا في عام 212 م؛ وزال التمييز بين المواطن والأجنبي في الإمبراطورية. ووسّع الترتيب أيضًا القاعدة الضريبية.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["بوستوموس يؤسس إمبراطورية الغال الانفصالية", "4dcda41d"], "d": ["إثر وقوع فاليريان أسيرًا في يد البارثيين (260) أعلن بوستوموس بجيوش الراين إمبراطورية في بلاد الغال؛ وانفصلت غاليا وبريطانيا ومعظم هسبانيا عن روما حتى 274. ولم يستطع غاليانوس إنهاء الانفصال.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["أورليانوس يخلي داكيا: التخلي عن شمال الدانوب", "db2ca714"], "d": ["بسبب ضغط القوط أخلى أورليانوس ولاية داكيا وسحب الفيالق والسكان المدنيين إلى جنوب الدانوب (داكيا ريبينسيس). وتركت روما بعد 165 سنة أول أرض كبرى لها شمال الدانوب.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["أورليانوس يهزم إمبراطورية تدمر: أراضي زنوبيا الشرقية تعود إلى روما", "0a358790"], "d": ["هزم أورليانوس عام 272 جيش زنوبيا في أنطاكية وحمص وحاصر تدمر؛ وأُسرت زنوبيا. وعادت سوريا ومصر وجنوب الأناضول إلى روما.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["أورليانوس يهزم إمبراطورية الغال: روما تتوحد من جديد", "c1a6a642"], "d": ["هزم أورليانوس تتريكوس عام 274 في كاتالاونوم؛ وعادت غاليا وبريطانيا وهسبانيا إلى روما. وتوحدت الإمبراطورية بعد انقسام دام 14 عامًا ونال أورليانوس لقب «Restitutor Orbis» («مجدد العالم»).", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["يوليانوس يُسكن الفرنجة السالين في توكساندريا بصفتهم foederati لروما", "0fb618fe"], "d": ["هزم القيصر يوليانوس الفرنجة السالين عام 358 وسمح لهم بالاستقرار في توكساندريا (الحدود الهولندية البلجيكية اليوم) في الأراضي الرومانية. وهي بداية استقرار المنطقة التي ستنشأ فيها مملكة الفرنجة تحت الحماية الرومانية.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["الهون يعبرون الدون ويهاجمون الآلان والأوستروغوط: بداية الهجرة الكبرى", "659eb875"], "d": ["وفق أميانوس عبر الهون الدون عام 375 وهزموا الآلان، ثم أنهوا مملكة ملك الأوستروغوط إرمانريك؛ فاتجه شعب القوط الغربيين (التيرفنجي) إلى الدانوب. وبذلك بدأ عصر هيمنة الهون في أوروبا.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["قوط التيرفنجي يعبرون الدانوب ويستقرون في الأراضي الرومانية", "3e9de0e6"], "d": ["بضغط الهون نال قوط التيرفنجي بقيادة فريتيجرن عام 376 إذنًا من فالنس بعبور الدانوب والاستقرار في الأراضي الرومانية؛ وتحولت مشكلات التموين والإدارة إلى تمرد. وكانت النتيجة هزيمة أدريانوبل (أدرنة) عام 378.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["الوندال والآلان والسوابيون يعبرون الراين ويدخلون بلاد الغال", "2b3354ba"], "d": ["في التاريخ التقليدي 31 كانون الأول 406 (على الراين المتجمد) دخل الوندال والآلان والسوابيون غاليا الرومانية؛ وانهار الدفاع على الراين. ثم أدى عبورهم إلى هسبانيا (409) إلى انتزاع الولايات الأساسية من روما الغربية.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["الوندال والآلان والسوابيون يعبرون إلى هسبانيا: اقتسام هسبانيا", "b7036608"], "d": ["في خريف 409 عبرت جماعات الوندال والآلان والسوابيين البرانس من غاليا، واقتسمت شبه الجزيرة في 411: فأخذ الهاسدينغ والسوابيون غالايكيا، وأخذ السيلينغ بايتيكا، وأخذ الآلان لوسيتانيا وقرطاجنة. ومهّد القوط الغربيون (416-418) بسحق السيلينغ والآلان لعبور الوندال إلى إفريقيا.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["روما تسكن القوط الغربيين في أكيتانيا الثانية: مملكة القوط الغربيين المتمركزة في تولوز", "38a7699e"], "d": ["بعد أن استخدمت روما بقيادة كونستانتيوس قوط واليا الغربيين ضد الوندال والآلان في هسبانيا، أسكنتهم عام 418 في أكيتانيا الثانية في وادي الغارون بصفتهم foederati. وتُعد مملكة القوط الغربيين المتمركزة في تولوز أول مملكة جرمانية على أرض رومانية.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["معاهدة مارغوس: الهون ينالون من روما 700 ليبرا من الذهب سنويًا", "833d8854"], "d": ["بعد وفاة ملك الهون روا (433/4) عقد أتيلا وبليدا معاهدة مع روما الشرقية في مارغوس: رُفعت الجزية السنوية من 350 إلى 700 ليبرا من الذهب، وأُعيد اللاجئون الهون. ونال الهون حق التجارة على حدود الدانوب.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["معاهدة هيبو: روما تعترف بالوندال بصفتهم foederati في أجزاء من نوميديا وموريطانية", "f7dba59f"], "d": ["عقد ملك الوندال جيزريق بعد عبوره إلى إفريقيا عام 429 معاهدة هيبو مع روما في 435؛ وأبقى الوندال بيدهم نوميديا وجزءًا من موريطانية بصفتهم foederati. وانتُقضت المعاهدة بالاستيلاء على قرطاجة عام 439.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["أتيلا يستولي على قلاع الدانوب: فيمناكيوم وسنجيدونوم (بلغراد) تنتقلان إلى الهون", "0abb2c54"], "d": ["بسبب انشغال جيش روما الشرقية بحملة صقلية والوندال عبر أتيلا الدانوب عام 441؛ فسقطت مارغوس وفيمناكيوم وسنجيدونوم. وسقطت سيرميوم أيضًا في هذه الحملات ووصل الهون إلى داخل البلقان.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["روما والوندال يعقدان معاهدة جديدة: إفريقيا البروقنصلية وبيزاكينا وجزء من نوميديا تبقى للوندال", "e5700ddc"], "d": ["بموجب المعاهدة التي عقدها جيزريق، المستولي على قرطاجة (439)، مع فالنتينيانوس الثالث عام 442 صار حقوقيًا جزء من إفريقيا البروقنصلية وبيزاكينا وأباريتانا ونوميديا أرضًا وندالية؛ ولم تحتفظ روما إلا بموريطانية وغرب نوميديا.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["سلام أناطوليوس: شريط واسع جنوب الدانوب يُترك للهون", "ee8ad838"], "d": ["بعد هزيمة روما الشرقية في أوتوس عقد أناطوليوس عام 447 سلامًا مع أتيلا: تركت روما للهون جنوب الدانوب شريطًا بعرض خمسة أيام يمتد من سنجيدونوم إلى نوفاي، ورُفعت الجزية السنوية إلى 2100 ليبرا من الذهب.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["معركة كاتالاونوم (شالون): أيتيوس وثيودوريك الأول يخرجان أتيلا من بلاد الغال", "80f10e32"], "d": ["في عام 451 دخل أتيلا بلاد الغال وحاصر أورليان؛ فردّه حلف أيتيوس وملك القوط الغربيين ثيودوريك الأول في سهل كاتالاونوم (وثيودوريك يلفظ أنفاسه). وبذلك توقف تقدم الهون في أوروبا الغربية.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["أتيلا يدخل إيطاليا؛ وتدمير أكويليا", "1349c67a"], "d": ["في عام 452 دخل أتيلا شمال إيطاليا عبر ما وراء الألب وسوّى أكويليا بالأرض ونهب سهل البو؛ وانسحب بسبب المرض وهجوم روما الشرقية المضاد. وشكّل سكان أكويليا الفارون في البحيرات الساحلية نواة البندقية.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["وفاة أتيلا؛ وتفكك دولة الهون", "47009384"], "d": ["مات أتيلا في ليلة عرسه عام 453؛ وأنهى اقتسام أبنائه وثورة الرعايا الجرمان بعد سنة في نيداو (454) تفوق الهون. وانسحب الهون إلى أوروبا الشرقية.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["مملكة القوط الغربيين بقيادة يوريك تنفصل فعليًا عن روما: أوفيرن تُترك للقوط الغربيين", "4bbe7b0c"], "d": ["وسّع يوريك مملكته بفتوحات في هسبانيا وبلاد الغال منذ 466؛ وفي 475 ترك يوليوس نيبوس أوفيرن واعترف فعليًا بسيادته المستقلة. وسيطرت مملكة القوط الغربيين على أراضي روما الغربية من اللوار إلى المتوسط.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["مقتل يوليوس نيبوس في دلماسيا: آخر إمبراطور شرعي لروما الغربية", "3b965f33"], "d": ["قُتل نيبوس، الذي انسحب إلى دلماسيا بعد سقوط روميولوس، عام 480؛ ولم يبق بعد موته من يطالب بعرش روما الغربية، وواصل أودواكر سلطته الفعلية في إيطاليا باسم زينون.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["ثيودوريك يُدخل الأوستروغوط إلى إيطاليا: أودواكر يُهزم عند إيسونتسو وفيرونا", "6a998bf8"], "d": ["بموافقة الإمبراطور الروماني الشرقي زينون دخل ثيودوريك إيطاليا عام 489 وهزم أودواكر عند إيسونتسو وفيرونا؛ وتحصن أودواكر في رافينا. وانتهى الحصار الذي دام ثلاث سنوات بتسليم رافينا عام 493.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["ثيودوريك يقتل أودواكر في رافينا؛ وإيطاليا تصير مملكة الأوستروغوط", "5a2db0ed"], "d": ["بعد حصار رافينا ثلاث سنوات اتفق أودواكر وثيودوريك في آذار 493 على حكم مشترك؛ ثم قتل ثيودوريك أودواكر في مأدبة. وصارت إيطاليا مملكة الأوستروغوط بموافقة روما الشرقية وعاصمتها رافينا.", "1ba7527e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["صلح ساموس: نال مبعوثو كوش السلام من أغسطس؛ ورفعت روما الجزية التي فرضتها على كوش، ورُسمت الحدود في النوبة السفلى (هييرا سيكامينوس)", "c3c4c20d"], "d": ["ذهب مبعوثو الكنداكة، بتوجيه من بترونيوس، إلى ساموس حيث وجدوا أغسطس؛ فقبل أغسطس كل مطالبهم ورفع الجزية التي فرضها بترونيوس على كوش. وبنتيجة السلام استقرت الحدود الرومانية الكوشية جنوب فيلة عند خط هييرا سيكامينوس (المحرقة)، ولم يقع صراع جدي نحو ثلاثمئة سنة.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["خرج بترونيوس في حملة على كوش فاستولى على بسلكيس وبرمنيس ونبتة؛ وأقام حامية في إبريم", "4884ed51"], "d": ["هزم الوالي بترونيوس، بنحو عشرة آلاف راجل وثمانمئة فارس، ثلاثين ألف جندي كوشي، واستولى على بسلكيس، وفتح قلعة برمنيس (قصر إبريم) من الهجمة الأولى، وسوّى نبتة، حيث قصر الكنداكة، بالأرض. ولما رأى التقدم أبعد صعبًا عاد، وترك في برمنيس حامية من أربعمئة رجل ومؤونة سنتين. وحين حاولت الكنداكة استرداد برمنيس، لحق بها بترونيوس وحمى القلعة.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["بقيادة الكنداكة استولت كوش على إلفنتين وسوان وفيلة؛ وحطمت تماثيل أغسطس", "aa665fad"], "d": ["حين سُحب جزء من القوات الرومانية في مصر لحملة إيليوس غالوس على بلاد العرب، دخل الكوشيون طيبة؛ وهزموا الحامية المؤلفة من ثلاث كتائب في سوان، واستولوا على سوان وإلفنتين وفيلة، وأسروا الأهالي، وأسقطوا تماثيل قيصر. ويكتب سترابون أن الملكة التي كانت تحكم كوش في ذلك الوقت امرأة بلقب «الكنداكة» عوراء.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["صار كورنيليوس غالوس أول والٍ على مصر؛ وقمع تمردي هيرونبوليس وطيبة، وأُمّنت الحدود مع كوش", "9f688855"], "d": ["جعل أوكتافيانوس مصر ولاية خاصة خاضعة للضريبة وأوكل إدارتها إلى والٍ من طبقة الفرسان لا إلى عضو في مجلس الشيوخ؛ وكان أول والٍ كورنيليوس غالوس. ويكتب سترابون أن غالوس استولى على بلدة متمردة في هيرونبوليس بعدد قليل من الجنود، وقمع بسرعة الانتفاضة التي اندلعت في طيبة بسبب الضريبة. وتفيد مسلة غالوس في فيلة أن مبعوثي حاكم كوش استُقبلوا هناك وأن إقليم تريكونتاسخوينوس وُضع تحت الحماية.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["دخل أوكتافيانوس الإسكندرية؛ وانتهت دولة البطالمة وانتقلت مصر إلى روما", "553804ca"], "d": ["بعد انتقال أسطول أنطونيوس وفرسانه إلى أوكتافيانوس، دخل أوكتافيانوس الإسكندرية؛ فانتحر أنطونيوس، وماتت كليوباترا بعد قليل. وعفا أوكتافيانوس عن أهل الإسكندرية، ولم يزر مقابر البطالمة قائلًا «أردت أن أرى ملكًا، لا موتى»، ومنح مصر لكورنيليوس غالوس بوصفها بلدًا خاضعًا للضريبة. وبهذا التاريخ انتهت مملكة البطالمة التي دامت ثلاثمئة سنة.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["معركة أكتيوم البحرية: هزم أوكتافيانوس أنطونيوس وكليوباترا", "7e46cc73"], "d": ["هزم أسطول أوكتافيانوس في أكتيوم أسطول أنطونيوس وكليوباترا؛ وانسحب الاثنان إلى مصر. ويذكر ديو هذا اليوم بالتحديد، مع أنه كاتب يتجنب ذكر التواريخ، لأن أوكتافيانوس أمسك الإمبراطورية بيده وحده منذ ذلك الحين وحُسبت سنوات حكمه من هذا اليوم.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["تبرعات الإسكندرية: أعلن أنطونيوس كليوباترا وأولادها حكامًا للممالك الشرقية", "24e24981"], "d": ["أقام أنطونيوس عروشًا من ذهب أمام الجمهور المحتشد في الجمنازيون، وأعلن كليوباترا ملكة على مصر وقبرص وليبيا وكويلي سوريا، وقيصرون شريكًا لها في الحكم، وأولادها ملوكًا على أرمينيا وميديا وبارثيا وفينيقيا-سوريا-كيليكيا. وتحولت هذه المراسم في روما إلى دعاية ضد أنطونيوس وعجّلت الحرب الأهلية.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["منح أنطونيوس كليوباترا قبرص وفينيقيا وكويلي سوريا وجزءًا من كيليكيا", "cf19a357"], "d": ["وفق بلوتارخوس، حين جاء أنطونيوس إلى سوريا منح كليوباترا فينيقيا وكويلي سوريا وقبرص ومعظم كيليكيا وجانب اليهودية المنتج للبلسم وجزء الأنباط الممتد إلى البحر. وهكذا سيطرت دولة البطالمة، لأول مرة منذ بطليموس الثالث، على مساحة واسعة من شرق المتوسط (رغم غضب روما).", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["حرب الإسكندرية: هزم قيصر بطليموس الثالث عشر وترك مصر لكليوباترا", "96c9b516"], "d": ["حين جاء قيصر إلى الإسكندرية وأراد التحكيم بين كليوباترا وبطليموس الثالث عشر، حاصرته قوات القصر؛ وفي حرب الشوارع التي استمرت طوال الشتاء وصلته النجدة، وغرق بطليموس الثالث عشر في معركة النيل. وأعطى قيصر مصر لكليوباترا ولأخيها الصغير بطليموس الرابع عشر؛ وبقيت الفيالق الرومانية في الإسكندرية.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["أعاد غابينيوس بطليموس الثاني عشر إلى عرش مصر بجيش روماني؛ وبقيت حامية رومانية في الإسكندرية", "41d8f47d"], "d": ["اشترى بطليموس الثاني عشر (أوليتس) المطرود دخول مصر برشوة كبيرة دفعها إلى والي سوريا غابينيوس؛ فترك غابينيوس حملة البارثيين ودخل مصر من بيلوسيوم وأعاد أوليتس إلى العرش. وهذه هي اللحظة التي ارتبط فيها استقلال مصر فعليًا بضمان روما. وحوكم غابينيوس لاحقًا في روما.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["ضمّت روما قبرص منتزعة إياها من البطالمة؛ وأُرسل كاتو إلى الجزيرة", "678b2115"], "d": ["لم يقاوم ملك قبرص، أخو بطليموس الثاني عشر، استيلاء روما على الجزيرة باقتراح من كلوديوس؛ وأُرسل كاتو لتسلم الجزيرة. وخسرت دولة البطالمة قبرص وفقدت آخر قاعدة بحرية على الساحل. ويذكر بلوتارخوس «إرسال» كاتو «إلى قبرص» في سيرة بومبيوس.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«يوم إليوسيس»: أجبر المبعوث الروماني بوبيليوس لايناس أنطيوخس الرابع على الانسحاب من مصر", "e6883e6a"], "d": ["بعد معركة بيدنا (22 يونيو 168 ق.م) مباشرة، أبلغ المبعوث الروماني غايوس بوبيليوس لايناس أنطيوخس، الذي كان يحاصر الإسكندرية، أمر مجلس الشيوخ بإيقاف الحرب؛ ورسم دائرة حوله ليفكر الملك في جوابه. فانسحب أنطيوخس. وحافظت مصر على استقلالها دون أن تفقده بحماية روما.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["هاجم أنطيوخس الرابع مصر؛ وتقدم في الحرب السورية السادسة إلى منف ونوقراطيس", "b85e6712"], "d": ["رد أنطيوخس الرابع على استعداد بطليموس السادس لاسترداد كويلي سوريا، فدخل مصر ونزل من بيلوسيوم إلى النيل؛ ودافع عن حقه في كويلي سوريا وأحسن معاملة الأهالي في نوقراطيس. وانتهت الحرب بعد عام بتدخل روما، دون أن تدمر مصر لكن بإضعاف الدولة.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["قُمع تمرد طيبة: استعاد كومانوس صعيد مصر إلى سيادة البطالمة", "4c0e4f10"], "d": ["بعد نحو عشرين عامًا من الحكم الانفصالي، استعاد قائد البطالمة كومانوس طيبة من الفرعون الوطني عنخ ون نفر، وارتبط صعيد مصر من جديد بدولة البطالمة.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["أصدر مجمع منف مرسوم رشيد: منح بطليموس الخامس المعابد إعفاءات ضريبية", "5643b91f"], "d": ["أقر المجمع الذي عقده كهنة مصر في منف تولي بطليموس الخامس العرش، وأعلن الإعفاءات الضريبية التي منحها الملك للمعابد، وقمع التمردات، وتأسيس عبادة الملك. وكُتب المرسوم بالإغريقية والديموطيقية والهيروغليفية؛ وحجر رشيد هو هذا النص ثلاثي اللغات. ويشير النص أيضًا إلى قمع المتمردين في الدلتا (ليكوبوليس).", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["معركة بانيون: هزم أنطيوخس الثالث سكوباس؛ وانتقلت كويلي سوريا من البطالمة إلى السلوقيين", "97e30e58"], "d": ["في الحرب السورية الخامسة هزم أنطيوخس الثالث قائد البطالمة الإيتولي سكوباس في بانيون؛ ووفق يوسيفوس استرد أنطيوخس مدن كويلي سوريا التي كان سكوباس قد استولى عليها وأخذ السامرة أيضًا، وانضم اليهود إلى أنطيوخس بمحض إرادتهم. وانتقلت كويلي سوريا (سوريا-فلسطين) بعد ذلك إلى حكم السلوقيين؛ وانسحبت دولة البطالمة من المنطقة.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["ظهور فراعنة وطنيين انفصاليين في طيبة: انفصل صعيد مصر عن سيادة البطالمة", "d10abb36"], "d": ["كما يقول بوليبيوس، تكبّر المصريون الوطنيون الذين سُلّحوا بعد نصر رفح بالانتصار وتوقفوا عن طاعة أمر الملك؛ فاندلعت انتفاضات في الدلتا وصعيد مصر. وأمسك فراعنة وطنيون في طيبة (حورونفر ثم عنخ ون نفر) صعيد مصر نحو عشرين عامًا ضد البطالمة.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["معركة رفح: هزم بطليموس الرابع أنطيوخس الثالث؛ وبقيت كويلي سوريا في يد البطالمة", "34362178"], "d": ["في رفح هزم جيش بطليموس الرابع، الذي ضم عددًا كبيرًا من مشاة الكتائب (الهوبليت) المصريين الوطنيين، جيش أنطيوخس الثالث؛ وانسحب أنطيوخس من كويلي سوريا وبقيت المنطقة في يد البطالمة حتى 200. وغذّى تسليح المصريين الوطنيين لاحقًا التمردات الانفصالية في صعيد مصر.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["استرد أنطيوخس الثالث سلوقية بيرية من البطالمة", "39ee3a52"], "d": ["حاصر أنطيوخس الثالث سلوقية بيرية التي كانت في يد البطالمة واستولى عليها برشوة الضباط؛ ويكتب بوليبيوس أن المدينة كانت تحتلها حامية تابعة لملوك مصر منذ عهد بطليموس الثالث. وبهذا النصر حصل السلوقيون على ميناء أنطاكية واستعدوا للزحف على كويلي سوريا (الحرب السورية الرابعة).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["غزا بطليموس الثالث سوريا وبلاد الرافدين في حرب لاوديكي؛ وانتقلت سلوقية بيرية إلى البطالمة", "04472253"], "d": ["توفي بطليموس الثاني في 28 يناير 246 ق.م؛ وهاجم بطليموس الثالث دولة السلوقيين لحماية أخته برنيقة. واستُقبل في سلوقية بيرية وفي أنطاكية؛ وتفيد حولية بابل (BCHP 11) أن جيشه وصل إلى بابل اعتبارًا من ديسمبر 246 ق.م. ويدّعي نقش أدوليس أنه فتح غرب الفرات وكيليكيا وبمفيليا وتراقيا. وبقيت سلوقية بيرية في يد البطالمة سنوات طويلة.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["احتل بطليموس كويلي سوريا بعد إبسوس؛ واعترض سلوقس (أصل الحروب السورية)", "a109388f"], "d": ["بعد معركة إبسوس (301 ق.م) اتفق سلوقس وليسيماخوس وكاساندروس على منح سوريا بأكملها لسلوقس؛ أما بطليموس فاحتل كويلي سوريا بجنده وأبقاها في يده. وولّد هذا الخلاف ست حروب سورية في القرنين التاليين. ودافع أنطيوخس الثالث لاحقًا عن هذا الادعاء كما ينقل بوليبيوس.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["أعلن بطليموس نفسه ملكًا؛ وتأسست أسرة البطالمة رسميًا", "008c723a"], "d": ["بعد اتخاذ أنتيغونوس وديمتريوس لقب ملك (306 ق.م)، اتخذ بطليموس أيضًا لقب ملك؛ وبدأت مصر تُعرف بوصفها مملكة هلنستية مستقلة. وعجّل تقديم الأسرة بوصفها فراعنة لمصر المصالحة مع طبقة الكهنة الوطنية.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["معركة غزة: هزم بطليموس وسلوقس ديمتريوس (سوريا في يد بطليموس لفترة قصيرة)", "ea0d264f"], "d": ["هُزم ديمتريوس بن أنتيغونوس أمام غزة أمام الجيش المشترك لبطليموس وسلوقس؛ ودخل بطليموس كويلي سوريا. وبهجوم مضاد من أنتيغونوس خرجت المنطقة من اليد بعد قليل، وثبّت الصلح (311 ق.م) ذلك.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["فشلت حملة برديكاس على مصر عند عبور النيل؛ وقُتل برديكاس على يد جيشه", "c1792117"], "d": ["في حرب الدياذوخوي دخل برديكاس، نائب الإسكندر، مصر ضد بطليموس الذي اختطف موكب جنازة الإسكندر، لكنه لم يتمكن من عبور النيل، وفقد عددًا كبيرًا من رجاله، وقتله ضباطه. وأبقى بطليموس مصر في يده.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["ضم بطليموس قوريني (برقة) إلى مصر", "65316c50"], "d": ["تدخل بطليموس في الصراع الداخلي في قوريني، وربط إقليم برقة الليبي بمصر بقيادة أوفيلاس. وهكذا وسّع بطليموس مصر نحو الغرب أيضًا؛ وبقيت برقة في القرون التالية في يد فرع من أسرة البطالمة.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["استشار الإسكندر كاهن آمون في واحة سيوة", "c437ced0"], "d": ["انتقل الإسكندر من الساحل إلى الصحراء وذهب إلى واحة سيوة حيث معبد آمون، واستشار الوحي؛ ويكتب أريانوس أنه تلقى الجواب الذي يرضيه. وغذّت هذه الزيارة شرعية الإسكندر في مصر وروايات عدّه ابنًا للإله لاحقًا.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["دخل الإسكندر مصر؛ واستسلم الساتراب الفارسي مازاكيس، وانتقلت مصر إلى الحكم المقدوني", "c4a5f014"], "d": ["وصل الإسكندر، المنطلق من غزة، إلى بيلوسيوم في اليوم السابع، وكان أسطوله قد بلغها أيضًا. ولم يقاوم الساتراب مازاكيس، الذي لم يبق له دعم فارسي بعد إسوس، واستقبل الإسكندر في المدن استقبالًا وديًا. وأقام الإسكندر حامية في بيلوسيوم وتقدم إلى منف؛ وترك الإدارة لواليين وطنيين (دولواسبيس وبتيسيس)، وعيّن قادة مقدونيين في منف وبيلوسيوم. وخرجت مصر من الهيمنة الفارسية وانضمت إلى إمبراطورية الإسكندر.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["أعاد أرتحشستا الثالث فتح مصر؛ وفرّ نختنبو الثاني إلى النوبة", "55d78a8d"], "d": ["انهار الدفاع عن بيلوسيوم في زحف أرتحشستا الثالث على مصر بعد استيلائه على صيدا؛ وفرّ نختنبو الثاني إلى صعيد مصر والنوبة دون أن ينتظر الحصار في منف. وصارت مصر للمرة الثانية ساتربية فارسية؛ ومصير آخر فرعون وطني مجهول.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["خرج تاخوس في حملة على سوريا؛ واستولى نختنبو الثاني على العرش بانقلاب، وبدّل أجيسيلاوس صفه", "4e1e9804"], "d": ["جمع تاخوس مرتزقة إغريقًا (أجيسيلاوس ملك إسبرطة والأثيني خابرياس) لمهاجمة سوريا الفارسية؛ وأثناء الحملة أعلن ابن أخيه نختنبو الثاني نفسه ملكًا. ووقف أجيسيلاوس إلى جانب نختنبو؛ ويكتب بلوتارخوس أن قتال أجيسيلاوس في شيخوخته مقابل أجر من أجل «متمرد بربري» انتُقد في بلاد الإغريق.", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["صدّ نختنبو الأول الغزو الفارسي (فرنبازوس-إفيكراتس)", "0a8bc67d"], "d": ["رد نختنبو الأول، مؤسس الأسرة الثلاثين، إنزال الجيش الفارسي بقيادة فرنبازوس والأثيني إفيكراتس في الدلتا بفضل فيضان النيل والخلاف بين القادة. وأطال هذا النجاح استقلال مصر 30 سنة أخرى.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["تمرد إيناروس: انتفاضة مصرية بدعم أثيني ضيّقت على الفرس في منف، وانهارت في بروسوبيتيس سنة 454", "0cd93c33"], "d": ["أثار الليبي إيناروس مصر كلها تقريبًا ضد أرتحشستا وطلب العون من الأثينيين؛ فدخل الأسطول الأثيني النيل واستولى على ثلثي منف وحاصر «القلعة البيضاء» المتبقية. وأباد القائد الفارسي مغابيزوس الأثينيين في جزيرة بروسوبيتيس بعد حصار دام سنة وستة أشهر (بتجفيف القناة)؛ وأُسر إيناروس وصُلب. أما أميرتايوس في مستنقعات الدلتا فلم يُقبض عليه.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["ثارت مصر على الهيمنة الفارسية؛ وقمع خشايارشا الأول التمرد وحكم مصر بشدة أكبر", "9d3d7462"], "d": ["قُمع تمرد مصر، الذي بدأ قبل وفاة داريوس الأول، في السنوات الأولى من حكم خشايارشا الأول؛ فعيّن خشايارشا أخاه أخايمنيس ساتربًا وبدأ يحكم مصر بشدة أكبر مما كان في عهد داريوس.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["فشلت حملة قمبيز على كوش بسبب العطش وانعدام المؤن؛ وبقيت حدود مصر الجنوبية عند إلفنتين", "4ebbad8c"], "d": ["بعد مصر خطط قمبيز لحملة على «الإثيوبيين طوال العمر» (كوش)؛ ووفق هيرودوت أرسل ملك كوش قوسه إلى المبعوثين الفرس وقال لهم أن يهاجموا «حين يتمكنون من شد القوس بسهولة». وبقي الجيش في الصحراء بلا مؤن وعاد. ويذكر سترابون كذلك المكان الذي هلك فيه جيش قمبيز في عاصفة بالصحراء. وبقيت كوش مستقلة؛ ووقفت حدود الفرس الجنوبية عند إلفنتين.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["هزم أحمس الثاني (أماسيس) أبريس وتولى عرش مصر؛ واستقر التجار الإغريق في نوقراطيس", "75a24b0b"], "d": ["عاد أبريس من حملة ليبيا بمرتزقة إغريق، فهُزم في مومفيس أمام أماسيس الذي تولى قيادة الوحدات الوطنية في الجيش؛ وحكم أماسيس مصر من سايس، وخصص لنوقراطيس للإغريق ميناءً تجاريًا وحيدًا. وفي نهاية حكمه (526 ق.م) تعاظم التهديد الفارسي.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["أرسل بسماتيك الثاني حملة إلى النوبة: كُسر ضغط كوش على حدود مصر", "8f0aaf9d"], "d": ["تُذكر حملة بسماتيك الثاني على النوبة عند هيرودوت بوصفها «حملته على إثيوبيا»؛ وترك الجيش المصري والمرتزقة الإغريق والكاريون نقوشًا إغريقية في أبو سمبل. وتفيد مسلة السنة 3 في طيبة (الكرنك) أن هزيمة ثقيلة أُنزلت بمملكة كوش، وتخلدها مسلة النصر في كلابشة؛ ويُعدّ أن الحملة تقدمت حتى الشلال الثالث أو الرابع. ووفق المصادر انتقل المركز السياسي لكوش في العهد اللاحق (أسبلتا، نحو 591 ق.م) جنوبًا إلى مروي.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["هاجم نبوخذنصر حدود مصر؛ وفي معركة مكشوفة تكبد الطرفان خسائر فادحة، وانسحب البابليون", "45655313"], "d": ["زحف ملك بابل نبوخذنصر على مصر في السنة 4 من حكمه؛ وجمع ملك مصر جيشه والتقى به، وأنهك الطرفان بعضهما بعضًا إنهاكًا شديدًا في معركة ميدانية مكشوفة. وعاد نبوخذنصر إلى بابل وانسحب ليعيد تجهيز جيشه. ودافعت مصر عن حدودها، لكن سوريا-فلسطين كانت قد بقيت لبابل.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["معركة قرقميش: هزم نبوخذنصر الجيش المصري؛ وخسرت مصر سوريا", "ba486ac1"], "d": ["عبر ولي العهد نبوخذنصر الفرات بالجيش البابلي ضد الجيش المصري الموجود في قرقميش فهزمه، وأباد الهاربين في منطقة حماة، واستولى على منطقة حماة كلها. وانسحبت مصر من سوريا وعادت إلى ما وراء حدود سيناء؛ وصارت بابل صاحبة سوريا-فلسطين.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["دخل نكاو الثاني سوريا-فلسطين؛ وهزم يوشيا في مجدو وتقدم نحو الفرات", "f887d6fd"], "d": ["زحف نكاو الثاني على سوريا قاصدًا الاستيلاء على الولايات الغربية لآشور المنهارة؛ وقتل ملك يهوذا يوشيا الذي اعترض طريقه في مجدو. ويقول هيرودوت «هزم نكاو السوريين في مجدولوس واستولى على مدينة سورية كبيرة هي كاديتيس». وهكذا سيطرت مصر فترة قصيرة على سوريا-فلسطين حتى الفرات.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["بسماتيك الأول يبسط سيطرته على صعيد مصر بتبني ابنته نيتوكريس لدى «زوجة الإله» في طيبة", "bf768452"], "d": ["رتّب بسماتيك الأول في السنة 9 من حكمه إرسال ابنته نيتوكريس إلى طيبة لتتبنّاها شبنوبت، ابنة ملك كوش تهارقا (زوجة الإله في طيبة)؛ وتنازلت شبنوبت عن أملاكها لنيتوكريس، وهكذا انتقلت ثروة معابد طيبة إلى يد السايتيين. وتدل مسلة التبني على أن بسماتيك نال السيطرة الكاملة على طيبة في سنته 9، وأن تانتماني فقد صعيد مصر حتى ذلك التاريخ.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["نهب الجيش الآشوري طيبة؛ وانسحب تانتماني جنوبًا، وانهارت هيمنة كوش على مصر", "777fc1a5"], "d": ["طارد جيوش آشوربانيبال تانتماني من منف وتقدمت حتى طيبة ونهبت المدينة؛ ونُقلت كنوز معابد طيبة إلى نينوى. وانسحب تانتماني إلى النوبة؛ وانحلت هيمنة كوش على صعيد مصر. ويُذكر هذا النهب في العهد القديم باسم «نو آمون» (ناحوم 3: 8).", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["بدأت الأسرة السادسة والعشرون: وصل بسماتيك الأول إلى الحكم في سايس تابعًا لآشور في مصر السفلى", "f270eac3"], "d": ["من بين أمراء الدلتا الذين أقامهم الآشوريون في مصر، بدأ حاكم سايس بسماتيك الأول الأسرة السادسة والعشرين (السايتية). ووفق هيرودوت، نجا بسماتيك من بين «الملوك الاثني عشر» وطُرد إلى المستنقع، ثم استعاد الدلتا. وبعد آشور وكوش عادت مصر إلى يد أسرة وطنية؛ واستغرق كسب طيبة وصعيد مصر بضع سنوات.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["نزل تانتماني من كوش واستعاد طيبة ومنف؛ وحاصر التابعين لآشور", "f84c87a4"], "d": ["نزل تانتماني، خليفة تهارقا، شمالًا في النهر بعد تتويجه في نبتة وفق مسلة الحلم: قدّم القرابين لخنوم في إلفنتين، وجاء إلى طيبة ومنف فاستولى على المدينة بعد أن ذبح من عارضوه فيها، أما الأمراء في الدلتا فاختبأوا أو خضعوا. وهدد هذا المسعى النظام الذي أقامه بسماتيك الأول وآشور في الدلتا، وجلب الحملة الآشورية العقابية.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["دخل آسرحدون مصر واستولى على منف؛ وانسحب تهارقا جنوبًا", "a138bcac"], "d": ["زحف ملك آشور آسرحدون على مصر في السنة 10 من حكمه؛ وأوقع الجيش الآشوري مذبحة كبرى في مصر، وفرّ ملك كوش تهارقا جنوبًا. وصارت الإمارات في الدلتا تابعة لآشور، وانتقلت منف ومصر الشمالية مؤقتًا إلى يد آشور. ومات آسرحدون في الطريق بعد سنتين وهو يخرج في حملة جديدة.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["التقى سنحاريب في حملة يهوذا بجيش كوش ومصر في التقة", "7f423351"], "d": ["في حملة ملك آشور سنحاريب على كنعان جاء الجيش المصري الكوشي لنجدة يهوذا واشتبك مع الآشوريين في التقة؛ وانسحب الجيش الآشوري دون أن يتمكن من الاستيلاء على القدس. ويروي يوسيفوس أن سنحاريب غادر بيلوسيوم حين بلغه أن ملك كوش ترهاقا قادم بجيش كبير. وهذا أول صدام مباشر بين كوش ومصر وآشور.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["نزل بيي (بعنخي) إلى مصر: هزم تحالف تفنخت وأخضع حكام منف والدلتا", "bb36f7c4"], "d": ["كان تفنخت من سايس قد أقام تحالفًا من الدلتا إلى منف ومصر الوسطى وحاصر هيراكليوبوليس. فخرج بيي من نبتة، ونزل شمالًا في السنة 21 من حكمه، واستولى على المدن المتحالفة (هرموبوليس ومنف وهليوبوليس) وقبل استسلام أمراء الدلتا؛ ثم عاد إلى نبتة. وهكذا صارت كوش رأس مصر كلها (الأسرة 25).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["تقدم كاشتا ملك كوش (نبتة) إلى صعيد مصر؛ ونفذ نفوذه إلى إلفنتين وطيبة", "b0f5be7f"], "d": ["استفاد ملوك كوش في نبتة من تفتت مصر في العصر الانتقالي الثالث، فتقوّوا نحو الشمال. ويُفهم من الآثار أن كاشتا أقام نفوذه في صعيد مصر حتى إلفنتين؛ وأُقيمت أمنيرديس الأولى (أخت بيي) من أسرة كوش في طيبة بلقب «زوجة الإله» لآمون، وصار هذا المنصب وسيلة كوش في طيبة. وهكذا تهيأ الأساس لتأسيس الأسرة 25.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["حملة شيشنق على كنعان: دخلت القدس ومدن إسرائيل ويهوذا في قائمة الكرنك", "1607ae3a"], "d": ["تتطابق حملة شيشنق على كنعان مع رواية التوراة التي تفيد أخذ الجزية من القدس في السنة 5 من الملك رحبعام (1 ملوك 14: 25)؛ وتُسرد في بوابة بوباستيت بالكرنك نحو 150 اسم مدينة (نحو خمسين إلى ستين منها لإسرائيل ونحو مئة ليهوذا). ويروي يوسيفوس كذلك أن شيشاق استولى على القدس وحمل الكنز. وهذه الحملة أطول حملة خارجية لمصر في العصر الانتقالي الثالث.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["أسس شيشنق الأول (من أصل المشواش/الليبي) الأسرة الثانية والعشرين؛ والعاصمة بوباستيس", "dae122c7"], "d": ["كان قادة المشواش من أصل ليبي قد استقروا في الدلتا بعد الدولة الحديثة؛ ومن بينهم وحّد شيشنق الأول مصر من جديد بعد الأسرة الحادية والعشرين في تانيس. وربط طيبة بالأسرة بتعيين ابنه كبيرًا لكهنة آمون. وأتاح هذا العصر نهوضًا قصيرًا وجّه مصر من جديد نحو السياسة الخارجية (حملة كنعان).", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["انتهت الدولة الحديثة: في أواخر سنوات رمسيس الحادي عشر استقل سمندس (تانيس) في الدلتا وكبير كهنة آمون في طيبة استقلالًا فعليًا", "1828ceb0"], "d": ["انهارت الدولة المركزية في أواخر عهد رمسيس الحادي عشر: كبير كهنة آمون حريحور يسيطر على صعيد مصر في طيبة، ونسوبنبدد (سمندس) يحكم في تانيس بالدلتا؛ وتسجل قصة ونآمون هذا الانقسام (رحلة ونآمون من حريحور إلى سمندس). وأسس سمندس في النهاية الأسرة الحادية والعشرين؛ وخرجت النوبة كذلك من رقابة مصر وسط هذا الاضطراب.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["هزم رمسيس الثالث شعوب البحر برًّا (جاهي) وبحرًا في الدلتا", "9068ae7b"], "d": ["في السنة 8 من رمسيس الثالث توجهت البيليست والتجكر والدانين والشردن وسائر شعوب البحر برًّا وبحرًا نحو حدود مصر؛ فأوقفهم الجيش المصري أولًا على حدود كنعان ثم في المعركة البحرية عند مصبات الدلتا. وتوثق نقوش مدينة هابو ذلك. وأبقت مصر كنعان في يدها، لكن نفوذها في شرق المتوسط بدأ يتآكل بعد هذا العصر.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["هزم مرنبتاح تحالف الليبيين وشعوب البحر في غرب الدلتا؛ وذُكر اسم «إسرائيل» لأول مرة في كنعان", "e512311e"], "d": ["في السنة 5 من مرنبتاح غزا المشواش بقيادة الليبو و«الشعوب القادمة من البحر» (الإكواش والتريش واللوكا والشردانا والشكلش) غرب الدلتا؛ وشتتهم الجيش المصري في معركة دامت ست ساعات في بيريرة. وتذكر مسلة النصر التي تروي الأحداث نفسها، وتُسمّي في كنعان عسقلان وجازر ويانوعام و«إسرائيل»؛ وهذا أقدم ذكر معروف لاسم إسرائيل.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["«المعاهدة الأبدية» بين رمسيس الثاني وحاتوسيلي الثالث: انتهت الحرب المصرية الحثية", "100f2a75"], "d": ["في السنة 21 من رمسيس الثاني جاء المبعوثون الحثيون بلوح المعاهدة إلى بر رعمسيس. وأنهت المعاهدة حرب سوريا التي دامت نحو خمس عشرة سنة: تخلى الطرفان عن مزيد من مخططات الفتح في سوريا، وأقاما حلفًا دفاعيًا، وقبلا تسليم الهاربين والمساعدة المتبادلة. ووفق تلخيص بريستد، لا تُذكر الحدود في النص؛ وبقي نطاق نفوذ الدولتين في الأمر الواقع (حزام قادش-عمورو في يد حاتي، وكنعان في يد مصر).", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["التقى رمسيس الثاني في قادش بالحثيين بقيادة موواتالي الثاني؛ وانتهت المعركة بالتعادل", "f5ad96db"], "d": ["التقى رمسيس الثاني بالجيش الحثي أمام قادش على نهر العاصي (الأورونت)؛ وبكمين العربات الحربية الحثية أوشك الجيش المصري على التشتت، فشن رمسيس هجومًا مضادًا بحرسه وصدّهم. ولم تسفر المعركة عن نتيجة حاسمة؛ وبقيت قادش وعمورو تحت السيطرة الحثية، وبقيت حدود مصر الشمالية على سواحل كنعان.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["قام سيتي الأول بحملة من جنوب كنعان حتى الساحل الفينيقي: استعادت مصر الهيمنة على كنعان وساحل لبنان، واستولى على قادش", "ad7bf1cd"], "d": ["وفق نقوش الكرنك، أخضعت حملة سيتي الأول في السنة 1 أولًا البدو الشاسو، ثم صعد شمالًا عبر فلسطين فأخضع بيهر وبيت شان ويانوعام وصور وأمراء لبنان. ويُصوَّر في الصف الأعلى من النقوش أخذ قادش أيضًا. ويبين بريستد أن الحدود الشمالية الدائمة لم تمتد وراء الخط الشرقي الغربي على الساحل الفينيقي، وأن القوة الحثية لم تُكسر؛ وهذه خلفية معركة قادش لرمسيس الثاني.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["في عصر العمارنة انحلت هيمنة مصر في شمال سوريا؛ وانتقلت عمورو وقادش إلى مجال النفوذ الحثي", "90d00c5a"], "d": ["تبين رسائل العمارنة (EA) أن تابعي شمال سوريا (عزيرو من عمورو وحكام قادش) كانوا يلعبون بين مصر وميتاني وحاتي، وأن مصر لم تستطع التدخل في المنطقة. وبنتيجة حملات الملك الحثي شوبيلوليوما الأول التي أنهكت ميتاني دخلت عمورو وقادش في النفوذ الحثي؛ وهكذا تراجعت حدود مصر الشمالية في سوريا إلى كنعان.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["نقل أمنحتب الرابع (إخناتون) عاصمة مصر إلى أخيتاتون (العمارنة)", "53cadac3"], "d": ["جعل إخناتون عبادة آتون ديانة الدولة، وأعلن عاصمةً مدينةً جديدة تُبنى في الصحراء في مصر الوسطى (أخيتاتون)؛ وتؤرَّخ «مسلات الحدود» التي حددت حدود المدينة إلى السنتين 4 و5. وتبين رسائل العمارنة أن تابعي سوريا في هذا العصر طلبوا النجدة لكن مصر لم تجب.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["بلغ أمنحتب الثاني نبتة في النوبة وأقام مسلة الحدود الجنوبية: أقصى نقطة جنوبية لمصر", "2f61f824"], "d": ["عبر أمنحتب الثاني إلى النوبة عائدًا من حملة سوريا (يوليو)؛ ووفق نقوش المعابد في إلفنتين وعمدا علّق ستة من الأمراء السبعة الذين جيء بهم من سوريا على أسوار طيبة، والسابع على أسوار نبتة. ووفق بريستد أقام الملك في نبتة أو فوقها مباشرة مسلة تبين الحدود الجنوبية: وهكذا امتدت سيادة مصر الفعلية في النوبة إلى ما بعد تومبوس (الشلال الثالث) حتى منطقة الشلال الرابع.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["عبر تحتمس الثالث الفرات ودخل أراضي ميتاني؛ وأقام مسلة حدود في نهرين", "ebdbeebe"], "d": ["في السنة 33 تقدم تحتمس الثالث من رتنو وعبر الفرات، ونهب بلدات نهرين، وأقام مسلة حدود شرق النهر؛ ووضع مسلة ثانية بجانب مسلة أبيه. وهذه الحملة أبعد نقطة بلغها النفوذ المصري في الشمال، وتبين عتبة الصدام المباشر مع ميتاني.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["هزم تحتمس الثالث في مجدو تحالف كنعان بقيادة قادش؛ ودخلت كنعان-سوريا في الهيمنة المصرية", "439dc6e8"], "d": ["في السنة 23 من تحتمس الثالث، في اليوم 21 من الشهر 1 من فصل شمو، هزم أمام مجدو تحالف كنعان الذي كان على رأسه حاكم قادش؛ ففرّ العدو إلى المدينة وسلمت مجدو بعد حصار طويل. وهذه الحملة المسجلة في حوليات الكرنك رسّخت تبعية كنعان وجنوب سوريا لمصر، وكانت بداية توسع الإمبراطورية.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["قام تحتمس الأول بحملة آسيوية بلغت ضفة الفرات (نهرين)", "50ce0679"], "d": ["وفق نقوش أحمس بن نخبت وأحمس بن إبانا، شن تحتمس الأول بعد حملة النوبة حملة كبرى على نهرين؛ ولاحقًا أضاف تحتمس الثالث مسلته إلى جانب مسلة الحدود التي أقامها أبوه على الفرات. وهذه أول فترة مسجلة بلغ فيها النفوذ المصري الفرات.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["قام أحمس بحملة على النوبة السفلى وأخضع أهل المراعي النوبيين", "dbbd94b7"], "d": ["بعد أن هزم أحمس الآسيويين، صعد جنوبًا في النهر إلى خنت حن نفر وأخضع أهل المراعي النوبيين. وهذه الحملة الخطوة الأولى في ضم النوبة السفلى، التي كانت في يد كرمة منذ خط قلاع الدولة الوسطى، إلى مصر.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["استولى أحمس على أواريس عاصمة الهكسوس وحاصر شاروهين وأسقطها", "b7bb3099"], "d": ["حاصر أحمس أواريس في شرق الدلتا واستولى عليها؛ وفرّ الهكسوس إلى آسيا وطاردهم حتى شاروهين في جنوب كنعان. ويفيد نقش أحمس بن إبانا أن شاروهين حوصرت 6 سنوات. وهكذا خرجت الدلتا المصرية من سيطرة الهكسوس، وصارت مصر في موضع يتيح لها ممارسة نفوذ سياسي في كنعان.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["اعتلى أحمس الأول العرش في طيبة؛ وبدأت الأسرة الثامنة عشرة وعصر الدولة الحديثة", "0798cfa3"], "d": ["اعتلى أحمس، أخو كاموس آخر ملوك الأسرة السابعة عشرة في طيبة، العرش طفلًا؛ وكان في عهده سيطرد الهكسوس من مصر ويعيد الهيمنة على النوبة وكنعان، ويبدأ الأسرة الثامنة عشرة وعصر الدولة الحديثة. ولم يكن اعتلاء العرش نهاية الهكسوس، بل بداية المرحلة الأخيرة من الصراع.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["انقسمت مصر إلى قسمين: حكم الهكسوس (الأسرة الخامسة عشرة) مصر السفلى والوسطى من أواريس، وحكمت الأسرة السابعة عشرة في طيبة صعيد مصر", "cd743737"], "d": ["أسس «الحكام الأجانب» (الهكسوس) من أصل كنعاني، المستقرون في أواريس في شرق الدلتا، الأسرة الخامسة عشرة وحكموا مصر السفلى ومصر الوسطى حتى قوسيه (قوصية)؛ وظلت الأسرة السابعة عشرة الوطنية في طيبة تمسك صعيد مصر. ووقفت مملكة كرمة جنوب طيبة قوة مستقلة. ويؤكد بريستد، برواية حصار أحمس، أن أواريس كانت عاصمة الهكسوس.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["جعل سنوسرت الثالث حدود مصر الجنوبية عند سمنة على الشلال الثاني؛ ومنع النوبيين من العبور", "753ef5fd"], "d": ["تحدد مسلة سمنة المؤرخة في السنة 8 من سنوسرت الثالث «الحدود الجنوبية»: يُمنع النوبيون من عبور هذا الخط برًّا أو نهرًا، إلا من يأتون إلى إيكن للتجارة. وأقام الملك في النوبة السفلى سلسلة قلاع (بوهين وسمنة وكمة وأورونارتي وغيرها) أوقفت امتداد كرمة شمالًا. وهذه أبعد حدود دائمة للدولة الوسطى جنوبًا في النوبة.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["أسس أمنمحات الأول الأسرة الثانية عشرة؛ ونُقلت العاصمة إلى إيتجتاوي", "26c43dad"], "d": ["أسس أمنمحات الأول، الذي صار ملكًا وهو وزير، الأسرة الثانية عشرة ونقل العاصمة من طيبة إلى المدينة الجديدة (إيتجتاوي) بين منف والفيوم. وأقامت هذه الأسرة أكثر عصور الدولة الوسطى استقرارًا ونظام القلاع نحو النوبة.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["هزم منتوحتب الثاني هيراكليوبوليس ووحّد مصر من جديد (سماتاوي)", "dbc6136f"], "d": ["نحو السنة 39 من حكمه أزال منتوحتب الثاني هيراكليوبوليس وجمع مصر العليا والسفلى في حكم واحد، وأضاف إلى لقبه اسم «موحّد الأرضين» (سماتاوي). ونُقلت الإدارة المركزية إلى طيبة؛ وقُلصت صلاحيات حكام الأقاليم.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["اعتلى منتوحتب الثاني العرش في طيبة؛ وبدأ عصر الدولة الوسطى واشتدت الحرب على هيراكليوبوليس", "edde038d"], "d": ["يُعدّ عهد منتوحتب الثاني الطويل (51 سنة) بداية الدولة الوسطى. وفي النصف الأول من عهده كانت طيبة في حرب مع هيراكليوبوليس؛ وفي السنة 14 أرسل الملك جيشًا نحو الشمال حين انتهكت قوات هيراكليوبوليس المقبرة المقدسة في أبيدوس. أما التوحيد الفعلي لمصر فتحقق بعد ذلك بكثير، في السنوات نحو 39 من عهده (البند الوارد أدناه).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["بدأت الأسرة الحادية عشرة في طيبة: أقامت أسرة إنتف مملكة مستقلة في صعيد مصر", "0e021743"], "d": ["اتخذ حكام أقاليم طيبة من نسل إنتف لقب ملك وأقاموا ممالكهم الخاصة في أقصى جنوب صعيد مصر (من إلفنتين إلى أبيدوس). ويذكر إنتف اللاحق في نقشه أنه استولى على إقليم ثينيس الذي توجد فيه أبيدوس وأنه «فتح جميع قلاعه»؛ وهكذا رُسمت الحدود بين طيبة وهيراكليوبوليس حول أبيدوس.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["في هيراكليوبوليس (حنن نسوت) الأسرتان التاسعة والعاشرة: حكمت أسرة خيتي مصر الشمالية", "9dde2d0c"], "d": ["في العصر الانتقالي الأول ملأت الأسرة في هيراكليوبوليس فراغ منف؛ وقاتل حكام الأقاليم الموالون، مثل حاكم أسيوط في مصر الوسطى تفيبي، إلى جانب هذه المملكة ضد الجنوب (طيبة). ويروي نقش مقبرة أسيوط تقدم الجنوبيين شمالًا من إلفنتين ودفعهم إلى «الحدود الجنوبية». وهكذا انقسمت مصر إلى قوتين رئيسيتين: هيراكليوبوليس (الشمال) وطيبة (الجنوب).", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["انهارت الدولة القديمة: تفككت الدولة المركزية بعد بيبي الثاني، وبدأ العصر الانتقالي الأول", "0339e96b"], "d": ["بعد عهد بيبي الثاني الطويل جدًا انتهت الأسرة السادسة؛ وتقسمت المملكة إلى مناطق ظل حكام الأقاليم فيها مستقلين فعليًا. وتبين نقوش المقابر (أسيوط وإلفنتين وغيرها) أن الحكام المحليين أرّخوا بأسمائهم وحشدوا جنودهم. أما الأسرتان السابعة والثامنة القصيرتا العمر في منف فلم تستطيعا السيطرة على البلاد كلها.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["رحلات حاكم إلفنتين حرخوف إلى بلاد يام: رابط دبلوماسي-تجاري وراء النوبة", "705b9808"], "d": ["قام حرخوف حاكم إلفنتين بعدة رحلات جنوبًا إلى بلاد يام لمرنرع وبيبي الثاني؛ ويروي نقشه الطريق الذي تسلطه والمنتجات التي جاء بها. وتُحفظ في نقش المقبرة كذلك الرسالة التي كتبها إليه الملك الطفل بيبي الثاني. وهذه الرحلات سجل الاتصال بمجتمعات ما قبل كرمة/كرمة القديمة على الحدود الجنوبية للدولة القديمة.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["حملة كبرى بقيادة وني على حدود كنعان بوحدات نوبية في عهد الأسرة السادسة", "69c94c55"], "d": ["وفق السيرة الذاتية لوني، جمع الملك جيشًا من عشرات الآلاف ضد «ساكني الرمل الآسيويين»؛ وتألف الجيش من مصر الجنوبية (حتى إلفنتين) ومن الشمال، ومن وحدات جُندت كذلك من قبائل النوبة (إرتجت وماجا ويام ووات وكاو). ويبين النص أن الدولة القديمة استخدمت النوبة خزانًا للجنود وأنها استطاعت أن تقوم بحملة حتى جنوب كنعان.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["بُني الهرم الأكبر لخوفو (خوفو) في الجيزة", "282359fc"], "d": ["هرم الملك خوفو من الأسرة الرابعة في الجيزة رمز لحشد اليد العاملة والموارد في الدولة القديمة. ويصور الحديث المصري للكهنة الذي ينقله هيرودوت خوفو طاغيةً أغلق المعابد وأجبر الشعب على نقل الحجارة؛ وهذا بوضعه هذا نظرة عصر لاحق، لا وثيقة معاصرة.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["اعتلى زوسر (الأسرة الثالثة) العرش؛ عصر الدولة القديمة والهرم المدرج في سقارة", "23e99ef4"], "d": ["بحكم زوسر (نترخت) تبدأ الدولة القديمة المتمركزة في منف؛ وأُقيم له الهرم المدرج، أول نموذج كبير للعمارة الحجرية. وفي هذا العصر تدير الدولة وادي النيل والدلتا من المركز؛ ومناجم سيناء وحدود النوبة (إلفنتين) تحت سيطرة الدولة.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["وحّد نعرمر (مينا) مصر العليا والسفلى؛ وبدأت الأسرة الأولى وصارت منف العاصمة", "cd3fadb1"], "d": ["نعرمر، حاكم مصر العليا (محيط ثينيس/أبيدوس)، هو الشخص نفسه مع مينا عند معظم علماء المصريات. وبضمه مصر السفلى إلى حكمه صار وادي النيل والدلتا دولة واحدة لأول مرة. ووفق الرواية القديمة أقام مينا موضع منف بتحويل مجرى النيل؛ والتوحيد ليس حدثًا واحدًا، بل نتيجة سيرورة طويلة مستمرة منذ نقادة الثالثة.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["أُعلن فسباسيانوس إمبراطورًا في الإسكندرية: حبوب مصر حسمت مصير الحرب الأهلية", "02b78348"], "d": ["أحلف والي مصر تيبريوس ألكسندر الفيالق في الإسكندرية الولاء باسم فسباسيانوس؛ وتم القسم في 1 يوليو، واعتبر فسباسيانوس هذا اليوم يوم توليه العرش. وأقسم الجيش اليهودي أمام فسباسيانوس بعد يومين. ويُعدّ إنتاج مصر من الحبوب السند الاستراتيجي لهذا المسعى.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["ثورة اليهود في مصر وقوريني وقبرص: قمعت روما المنطقة بصعوبة في عهد تراجان", "54787782"], "d": ["أثناء حملة تراجان على البارثيين، قتل اليهود في قوريني، بقيادة أندرياس، الرومان والإغريق؛ ووفق ديو جرت أحداث مماثلة في مصر وقبرص، وعُبّر عن عدد القتلى بمئات الآلاف. وقمع لوسيوس كيتوس، الذي أرسله تراجان، التمرد؛ ومُنع اليهود من دخول قبرص.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["تمرد البوكولي: ثورة في الدلتا هددت الإسكندرية، وقمعها أفيديوس كاسيوس", "5f94e6bf"], "d": ["ثار أهل الدلتا الملقبون بالبوكولي (الرعاة) بقيادة كاهن اسمه إيزيدوروس؛ ووفق ديو هزم المتمردون وحدة رومانية وأوشكوا على الاستيلاء على الإسكندرية. وقمع كاسيوس، الذي أُرسل من سوريا، الانتفاضة بتفريق وحدة المتمردين.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["أعلن أفيديوس كاسيوس نفسه إمبراطورًا في سوريا ومصر؛ وقُتل بعد ثلاثة أشهر", "ce33ca9d"], "d": ["أعلن كاسيوس، قائد الولايات الشرقية، نفسه إمبراطورًا عند بلوغ خبر وفاة ماركوس أوريليوس؛ وانتشر التمرد إلى سوريا ومصر (يرد عند ديو أن والي مصر فلافيوس كالفيسيوس لم يُقتل لاحقًا بسبب صلته بالتمرد بل نُفي إلى جزيرة). وقُتل كاسيوس، وفق ديو، على يد أحد ضباطه بعد «حلم إمبراطوري» دام ثلاثة أشهر وستة أيام؛ وزار ماركوس أوريليوس مصر وسوريا ولم يعاقب أحدًا.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["احتلت تدمر (زنوبيا) مصر؛ وهُزم القائد الروماني بروبوس", "54568441"], "d": ["دخل زبداس، قائد تدمر الذي كان يتحرك باسم زنوبيا، مصر بجيش من سبعين ألفًا؛ واستعاد القائد الروماني تيناغينو بروبوس الإسكندرية حينًا ثم هُزم وتحصن في قلعة بابليون، وانتحر حين أُسر. وعُدّت مصر لسنة أو سنتين جزءًا من دولة تدمر باسم زنوبيا.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["أُعلن دوميتيوس دوميتيانوس إمبراطورًا في مصر؛ وقمع دقلديانوس التمرد بحصار طيبة ثم الإسكندرية", "3c765005"], "d": ["ردًّا على الإصلاح الضريبي وسحب الوحدات الرومانية إلى الجبهة البارثية، أُعلن دوميتيوس دوميتيانوس أوغسطس في مصر في يوليو-أغسطس 297؛ واعترفت به معظم مصر بما فيها الإسكندرية. وقمع دقلديانوس في الخريف متمردي طيبة وحاصر الإسكندرية؛ ومات دوميتيانوس في ديسمبر 297، وواصل أوريليوس أخيلليوس الدفاع عن المدينة، وسلمت المدينة على الأرجح في مارس 298 بعد حصار دام نحو ثمانية أشهر.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["سحب دقلديانوس حدود مصر الجنوبية إلى خط إلفنتين/فيلة؛ وتُركت النوبة السفلى للنوباتاي", "725574bb"], "d": ["يروي بروكوبيوس أن دقلديانوس رأى كلفة الاحتفاظ بالصحراء الواسعة في أقصى جنوب مصر (دوديكاسخوينوس)، فترك ما جنوب إلفنتين للنوباتاي والبليميس وثبّت الحدود عند إلفنتين (ويُروى أن دفعة سنوية رُتبت لهم مقابل ذلك). وهكذا تراجعت الإدارة الرومانية عن حدود هييرا سيكامينوس التي رسمها أغسطس.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["هزم عيزانا ملك أكسوم كوش؛ وانتهت مملكة مروي (نحو 350 م)", "7c9d95d7"], "d": ["هاجم عيزانا ملك أكسوم مملكة كوش التي أضعفها ضغط النوبا والبليميس؛ وتروي نقوش عيزانا حملته على شعبي النوبا وكاسو (كوش)، وعُثر في مروي على نقشين إغريقيين مجزأين يعودان إلى نصر أكسوم. وتؤرَّخ آخر الأهرامات في مروي إلى منتصف القرن 4؛ وتفككت دولة كوش إلى ممالك نوباتيا ومقرة وعلوة.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["هدم ثيوفيلوس السرابيوم في الإسكندرية: أُغلق مركز الوثنية في مصر", "119a26c7"], "d": ["بعد مراسيم تيودوسيوس الأول التي حظرت العبادات الوثنية، هدم أسقف الإسكندرية ثيوفيلوس معبد سرابيس (السرابيوم)؛ وبلغ التوتر بين المسيحيين والوثنيين في المدينة ذروته في هذه الحادثة. ومصير النصوص المقدسة ومجموعات الكتب مثار جدل.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["توفي تيودوسيوس الأول؛ وانقسمت الإمبراطورية نهائيًا إلى قسمين، وبقيت مصر في الشرق الروماني (أركاديوس)", "54a12472"], "d": ["عند وفاة تيودوسيوس أخذ ابناه أركاديوس الشرق وهونوريوس الغرب؛ وبقيت مصر، مع أنها كانت المصدر الرئيس لحاجة روما إلى الحبوب، ولاية في الإمبراطورية الشرقية (البيزنطية)، وصارت في القرون التالية مصدر الحبوب للقسطنطينية.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["مجمع خلقيدونية: أُدين بطريرك الإسكندرية ديوسقورس؛ وانفصلت الكنيسة المصرية عن كنيسة الإمبراطورية", "5d2d05c6"], "d": ["حين أدان مجمع خلقيدونية بطريرك الإسكندرية في مصر ديوسقورس لم يقبل معظم مسيحيي مصر القرارات؛ وهكذا انفصلت في مصر الكنيسة القبطية (المصرية) عن كنيسة الإمبراطورية (الملكيين). وهيأ هذا الانقسام في القرون التالية الأساس لابتعاد مصر سياسيًا عن بيزنطة.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["المعاهدة بين أغسطس وفرهاد الرابع: أُعيدت رايات روما التي فقدها كراسوس", "be5f8bda"], "d": ["أعاد فرهاد الرابع إلى أغسطس رايات روما المفقودة لكراسوس وأنطونيوس بإيماءة دبلوماسية. وثبتت المعاهدة الفرات حدًّا بين روما وبارثيا وتركت أرمينيا منطقة عازلة.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["غزا باكوروس ولابيينوس سوريا وفلسطين", "68669aa1"], "d": ["غزا الأمير البارثي باكوروس ولابيينوس، الذي فرّ من روما ولجأ إلى بارثيا، ولايات روما السورية، واستوليا على أنطاكية وفلسطين. وهزم فنتيديوس، قائد أنطونيوس، البارثيين في غندروس سنة 38 واسترد المنطقة.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["معركة كاراي (حران): أباد سورينا جيش كراسوس الروماني", "3a91cd75"], "d": ["هُزمت فيالق كراسوس الرومانية قرب حران أمام الفرسان البارثيين والرماة الخيالة؛ وقُتل كراسوس. والمعركة من أثقل هزائم روما في الشرق، وثبتت حدود الفرات لصالح بارثيا.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["التقى سولا مبعوث البارثيين أوروبازوس على الفرات؛ أول اتصال دبلوماسي بين روما وبارثيا", "f8913f2b"], "d": ["التقى سولا، والي كبادوكيا، أوروبازوس مبعوث الملك البارثي ميثريداتس الثاني على ضفة الفرات؛ وأقامت روما وبارثيا أول اتصال رسمي. وسيصير الفرات لاحقًا الحد بين الدولتين.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["قُتل أنطيوخس السابع سيديتيس في حملة على بارثيا؛ ولم يستطع السلوقيون استرداد بلاد الرافدين", "e5897112"], "d": ["استرد أنطيوخس السابع سيديتيس من بارثيا بلاد الرافدين وميديا في 130-129، لكنه فقد جيشه وحياته بتمرد في مواضع الشتاء وهجوم بارثي. وأنهى هذا الإخفاق مطالبة السلوقيين بالشرق.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["أسر البارثيون ديمتريوس الثاني نيكاتور؛ وفقد السلوقيون بابل وبلاد الرافدين نهائيًا", "94a764ce"], "d": ["أسر جيش ميثريداتس الأول البارثي الملك السلوقي ديمتريوس الثاني واحتجزه في بلاط بارثيا. وضم ميثريداتس بلاد الرافدين إلى الإمبراطورية البارثية؛ وانحصرت الدولة السلوقية على الساحل وتراجعت إلى سوريا.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["ثورة المكابيين: بدأت الانتفاضة في اليهودية ضد المحظورات الدينية لأنطيوخس الرابع", "41c25b76"], "d": ["حين كرّس أنطيوخس الرابع إبيفانيس معبد القدس لزيوس الأولمبي وحظر الممارسات الدينية اليهودية، ثار متتيا وأبناؤه في مودين. واسترد يهوذا المكابي المعبد وطهّره سنة 164 (حانوكا)؛ وولدت دولة الحشمونائيم.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["اعتلى ميثريداتس الأول عرش بارثيا؛ وبدأ عصر توسع الإمبراطورية البارثية", "cc77639b"], "d": ["حوّل ميثريداتس الأول بارثيا إلى إمبراطورية: استولى على ميديا (147) وبابل وسلوقية (141)، وأقام سيادته على عيلام وفارس. وسيصير طيسفون لاحقًا العاصمة الشتوية.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["معاهدة أباميا: انسحب السلوقيون من غرب جبال طوروس ودفعوا تعويضًا", "f5197a70"], "d": ["منحت المعاهدة بين روما وأنطيوخس الثالث الأناضول غرب طوروس لحلفاء روما (برغامة ورودس)؛ وحُدد عدد سفن السلوقيين وفيلتهم، ودُفع تعويض قدره 15.000 تالنت. وصار السلوقيون بعد ذلك دولة سورية-ما بين النهرين.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["حملة أنطيوخس الثالث الشرقية (209-204): خضع ملوك بارثيا وباكتريا لجزية السلوقيين", "5c81f302"], "d": ["زحف أنطيوخس الثالث على ميديا وبارثيا وباكتريا لاسترداد أراضي السلوقيين الشرقية المفقودة: فرُبط أرساكيس الثاني وإيثيديموس بالجزية. وبعد هذه الحملة نال أنطيوخس لقب «الكبير».", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["استولى أرساكيس الأول وتيريداتس على بارثافا وأسسا الدولة البارثية (الأرشاقية)", "2cd572ca"], "d": ["أطاح أرساكيس، زعيم قبيلة البارني البدوية، بالساتراب السلوقي أندراغوراس واستولى على بارثافا وصار أول ملوك مملكة بارثيا؛ وعاصمتها هيكاتومبيلوس. وستكون الدولة البارثية سيدة بلاد الرافدين وإيران في القرون الثلاثة التالية.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["انفصل ساتراب باكتريا ديودوتوس عن السلوقيين؛ وولدت مملكة اليونان-الباكتريين", "52faafa6"], "d": ["أعلن ديودوتوس، ساتراب باكتريا وصغديانا، استقلاله مستفيدًا من ضعف أنطيوخس الثاني. وأجبرت مملكة اليونان-الباكتريين الدولة السلوقية على التراجع بحدودها الشرقية عن بارثافا وباكتريا.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["الحرب السورية الأولى (274-272): استرد السلوقيون دمشق؛ وعُقد الصلح", "0c17ee3d"], "d": ["بعد أن هزم أنطيوخس الأول الغلاطيين في «معركة الفيلة» (275) وأمّن نفسه، حارب بطليموس الثاني من جديد: فاسترد قائد سلوقي دمشق، وهاجم ماغاس مصر، وعُقد الصلح في النهاية سنة 272. والحرب بداية الصراع البطلمي-السلوقي على كويلي سوريا.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["حرب كاريا: انتزع بطليموس الثاني إيونيا وكاريا وليكيا وبمفيليا وجزءًا من كيليكيا من أنطيوخس الأول", "afe190ca"], "d": ["استولى بطليموس الثاني، بحملة قصيرة ناجحة، على الساحلين الجنوبي والغربي للأناضول، وبلغ دمشق؛ وعقد هدنة حين رأى أن قوة أنطيوخس ليست أدنى من قوة أبيه. وقبل أنطيوخس الخسارة لأنه كان عليه أن ينظم فتوح أبيه داخل الأناضول.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["قُتل سلوقس الأول على يد بطليموس كيرونوس؛ واعتلى أنطيوخس الأول العرش", "4703b674"], "d": ["طعن بطليموس كيرونوس سلوقس، الذي هزم ليسيماخوس في كوروبيدون واستولى على الأناضول، بالخنجر أثناء عبوره إلى أوروبا. وورث ابنه أنطيوخس الأول الدولة لكنه سيعاني في غرب الأناضول.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["أسس سلوقس الأول أنطاكية", "f4b98967"], "d": ["أسس سلوقس بعد إبسوس أنطاكية على نهر العاصي (الأورونت) في سوريا باسم أبيه؛ وصارت المدينة العاصمة الغربية للمملكة السلوقية وإحدى أكبر مدن العصور القديمة. وكانت سلوقية على دجلة قد أُسست قبل ذلك عاصمةً شرقية.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["معركة إبسوس: هزم سلوقس وليسيماخوس أنتيغونوس؛ وانتقلت سوريا إلى سلوقس", "93bf2aa9"], "d": ["في المعركة الحاسمة من حروب الدياذوخوي هزم سلوقس وليسيماخوس أنتيغونوس (وقُتل أنتيغونوس في المعركة). وآل الشرق كله وسوريا إلى حصة سلوقس؛ أما بطليموس فاحتل كويلي سوريا فأرسى سبب الحروب السورية الأولى.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["أسس سلوقس الأول سلوقية على دجلة", "032efabd"], "d": ["أسس سلوقس سلوقية على ضفة دجلة قرب بابل وبدأ ينقل إليها سكان بابل. وصارت سلوقية، بسكانها البالغين نحو 300 ألف، أكبر مدينة هلنستية في الشرق ثم جارة العاصمة للإمبراطورية البارثية.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["أبرم سلوقس الأول معاهدة مع تشاندراغوبتا موريا في الهند؛ وتُركت أراخوسيا وجدروسيا وباروباميسادي لموريا", "3ef3bdee"], "d": ["زحف سلوقس على الهند لاسترداد الساتربيات الهندية للإسكندر، لكنه اتفق مع تشاندراغوبتا وبادل جزءًا من أراضيه الشرقية بـ500 فيل حربي. ونقلت المعاهدة حدود إمبراطورية موريا الغربية إلى الهندوكوش، وزودت سلوقس بالفيلة لمواجهة الغرب.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["إحراق قصور برسيبوليس (أبريل)", "6e6cdfe0"], "d": ["أحرق الإسكندر عدة مبانٍ قصرية في برسيبوليس في أبريل 330؛ وتُذكر مبررات هي ألا تقع الخزينة في يد العدو وألا يكون هناك حاكم واحد بعد. ويظهر أثريًا أن قصر خشايارشا احترق أيضًا؛ وهُجرت المدينة كلها.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-01-01:0":{"b": ["دخل الإسكندر بابل؛ وسلمها مازايوس وانتقلت ساتربية بابل إلى الإسكندر", "c8d2afb3"], "d": ["بعد غوغميلا فتح ساتراب بابل مازايوس الأبواب للإسكندر؛ وأمر الإسكندر بإصلاح معبد مردوخ واستخدم المدينة 34 يومًا. وانتقلت بابل من الحكم الفارسي إلى الحكم المقدوني.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-01-01:1":{"b": ["استولى الإسكندر على سوسة؛ وأُخذت الخزينة الفارسية", "fbf417db"], "d": ["دخل الإسكندر، المغادر بابل، سوسة؛ وسلم الساتراب أبوليتس المدينة والخزينة الكبرى. وصارت سوسة الأساس المالي لحملة مقدونيا الشرقية.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["معركة غوغميلا: هزم الإسكندر جيش داريوس الثالث هزيمة حاسمة", "a5b082d7"], "d": ["في غوغميلا تفرق جيش داريوس، المؤلف من عدد كبير من العربات الحربية والفرسان، في الهجوم الذي اخترق فيه الإسكندر الدفاع عن الجناح الأيسر؛ وفرّ داريوس مرة أخرى. وحددت المعركة نهاية الإمبراطورية الفارسية؛ وفتحت بابل وسوسة أبوابهما.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["حصار صور: استولى الإسكندر على المدينة في الجزيرة بالردم ودمرها", "89ede146"], "d": ["استولى الإسكندر في سبعة أشهر على جزيرة صور، قاعدة الأسطول الفارسي، ببناء ممر اصطناعي؛ ونُهبت المدينة وقُتل معظم أهلها أو استُعبدوا. وهكذا انهارت القوة البحرية الفارسية وانفتح الطريق إلى مصر.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["معركة إسوس: هزم الإسكندر داريوس الثالث؛ وفرّ داريوس تاركًا أسرته", "3803fc30"], "d": ["في سهل ساحلي ضيق هُزم جيش داريوس الثالث الكبير أمام الإسكندر؛ وفرّ الملك الفارسي تاركًا أسرته وخزينته. وأتاح نصر إسوس انتقال سوريا والساحل الفينيقي ثم مصر إلى الإسكندر.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["معركة غرانيكوس: هزم الإسكندر الساترابات الفرس", "1aae30d4"], "d": ["عبر الإسكندر ملك مقدونيا إلى آسيا في مايو 334، وهزم الساترابات الفرس في غرانيكوس في أوائل يونيو. وانفتحت أبواب غرب الأناضول؛ وسلمت ساردس ومدن إيونيا للإسكندر.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["اعتلى داريوس الثالث العرش الفارسي (مقتل أرسيس)", "706f8a9f"], "d": ["قتل الخصي باغواس أرتحشستا الرابع؛ وصار ساتراب أرمينيا أرتاشاتا ملكًا باسم داريوس الثالث (كودومانوس). وفي أكتوبر 336 قُتل فيليب في مقدونيا وتولى الإسكندر العرش.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["توفي أرتحشستا الثالث؛ واعتلى أرتحشستا الرابع (أرسيس) العرش", "d38e2edc"], "d": ["توفي أرتحشستا الثالث في صيف 338 لأسباب طبيعية (رغم رواية ديودوروس عن التسميم)؛ وتولى أرسيس العرش. وتتزامن تمردات مصر وبابل واستعدادات ملك مقدونيا فيليب في الأناضول مع الفترة نفسها.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["استولى أرتحشستا الثالث على صيدا ودمرها؛ وقُمع تمرد تينيس", "d1b533cc"], "d": ["في أثناء تمرد تينيس ملك صيدا المناهض للفرس بدعم مصر، استولى أرتحشستا الثالث على المدينة؛ وخان تينيس الفرس، فأحرقت المدينة نفسها وهلك عدد كبير. وعادت المدن الفينيقية إلى السيطرة الفارسية وانفتح طريق فتح مصر.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["سلام الملك (أنتالكيداس): تُركت مدن الإغريق في الأناضول وقبرص لفارس", "17e871ad"], "d": ["بالسلام الذي أملاه الملك الفارسي أرتحشستا الثاني عُدّت مدن الإغريق في آسيا وقبرص تابعة لفارس، ومُنحت المدن الإغريقية استقلالًا ذاتيًا. وطبّقت إسبرطة السلام بوصفها متحدثة باسم فارس.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["معركة كوناكسا: هُزم كورش الصغير أمام أخيه الأكبر أرتحشستا الثاني وقُتل", "90346087"], "d": ["زحف كورش الصغير بالعشرة آلاف، المؤلفين من المرتزقة الإغريق، على بابل، فهُزم أمام أخيه الأكبر أرتحشستا الثاني في كوناكسا وقُتل في المعركة. وتُروى مسيرة عودة العشرة آلاف إلى البحر الأسود في «أناباسيس» لكسينوفون.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["عبر خشايارشا الهلسبونت؛ وثرموبيلاي وسقوط أثينا", "9bf22df1"], "d": ["هزم خشايارشا بجيشه الكبير في ثرموبيلاي وحدة ليونيداس الإسبرطية-الحليفة ودخل أتيكا؛ وأُخليت أثينا وأُحرقت مع الأكروبوليس. وتقدم الجيش الفارسي حتى وسط بلاد الإغريق.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["معركة سلاميس البحرية: هزم الأسطول الإغريقي الأسطول الفارسي", "010e3aab"], "d": ["هزم الأسطول الإغريقي بقيادة ثيميستوكليس الأسطول الفارسي في المضيق الضيق في سلاميس فاستولى على التفوق البحري. وعاد خشايارشا إلى آسيا بمعظم جيشه البري، وبقي مردونيوس في بلاد الإغريق.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["قمع خشايارشا الأول تمردي بيل-شيماني وشمش-إريبا في بابل", "ebcef5a9"], "d": ["اندلع تمردان في بابل في بداية عهد خشايارشا الأول (بيل-شيماني وشمش-إريبا). وقمعهما خشايارشا؛ وقسّم ساتربية بابل وقلّص امتيازات المدينة.", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["معركة لادي البحرية: هزم الأسطول الفارسي الأسطول الأيوني؛ وسقطت ميليتوس", "86396cf1"], "d": ["هزم الأسطول الفارسي، الذي كان معظمه فينيقيًا، الأسطول الأيوني في لادي؛ وحوصرت ميليتوس ودُمرت، ونُفي أهلها إلى بلاد الرافدين. وانتهى التمرد الأيوني وعادت إيونيا إلى السيطرة الفارسية.", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["أحرق الأيونيون ساردس", "adf677bd"], "d": ["زحف الأيونيون ووحدات الأثينيين والإريتريين إلى ساردس مركز الساتربية الفارسية وأحرقوها. وقرر داريوس بعد ذلك معاقبة أثينا؛ وهذه الحادثة مبرر حملة ماراثون.", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["بدأ التمرد الأيوني: لما أخفقت حملة أريستاغوراس على ناكسوس ثارت مدن إيونيا الإغريقية على فارس", "aab8ff2f"], "d": ["حين انهارت حملة أريستاغوراس طاغية ميليتوس على ناكسوس، أطاحت مدن إيونيا بطغاتها وطلبت النجدة من أثينا وإريتريا. وهذا التمرد فتيل الحروب الفارسية-الإغريقية.", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["عبر داريوس إستروس (الدانوب) وخرج في حملة على السكيثيين؛ وضُمت تراقيا إلى الساتربية الفارسية", "a5891101"], "d": ["عبر داريوس البوسفور بجسر إلى تراقيا، وأخضع الجيتيين وعبر الدانوب وخرج في حملة على السكيثيين. ومع أنه لم يهزم السكيثيين فقد ضم مغابازوس تراقيا وساحل مقدونيا إلى السيادة الفارسية.", "f464fbf8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-05-08:0":{"b": ["هزم جيش داريوس المتمرد الميدي فرافارتيش (فراورتس)", "4a9c4633"], "d": ["هُزم جيش فرافارتيش الذي أعلن نفسه في ميديا ملكًا من نسل كياخسارس؛ وبينما كان فرافارتيش يفر قُبض عليه في راغاي (قرب طهران) وقُتل بالتعذيب. وعادت ميديا ولاية فارسية.", "efea5aea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-12-28:0":{"b": ["هزم قائد داريوس متمرد مرجيانا فرادا؛ وقُمعت آخر الانتفاضات الكبرى", "76e0ea1c"], "d": ["سار داداريشي ساتراب باكتريا 300 كم عبر صحراء قره قوم، وهزم متمرد مرجيانا فرادا في 28 ديسمبر 521. وفي السنة الأولى من حكم داريوس قُمعت جميع التمردات بتسع عشرة معركة.", "5c0c9cfa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-03-11:0":{"b": ["استولى غومات (بردية) على العرش الفارسي؛ ومات قمبيز في عودته من مصر", "1606d9c1"], "d": ["وفق نقش بيستون، أعلن الكاهن غومات نفسه بردية (سميرديس) ابن كورش وصار على العرش في مارس 522؛ ومات قمبيز في سوريا. وقتل داريوس وستة من النبلاء غومات في 29 سبتمبر 522.", "f143e726"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-09-29:0":{"b": ["قتل داريوس وستة من النبلاء غومات؛ واعتلى داريوس الأول العرش الفارسي", "08897d54"], "d": ["قتل داريوس مع ستة من شركائه النبلاء بردية المزيف في قلعة سيكايوفاتي في ميديا. وأشعل موت غومات انتفاضات في أماكن كثيرة من الإمبراطورية؛ وقمعها داريوس في سنة واحدة بتسع عشرة معركة.", "daebf974"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-12-18:0":{"b": ["استرد داريوس بابل؛ وأُسر نيدينتو-بيل (نبوخذنصر الثالث) وقُتل", "365cdd51"], "d": ["عند موت غومات أعلن نيدينتو-بيل نفسه ابن نبونيد ونبوخذنصر الثالث وفصل بابل عن فارس. وعبر جيش داريوس دجلة في 13 ديسمبر على قِرَب منفوخة، وهزم جيش التمرد، واسترد بابل في 18 ديسمبر، وقُتل نيدينتو-بيل. وقُمع في هذه الأثناء تمرد عيلام في سوسة.", "4bd29dc6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0529-01-01:0":{"b": ["توفي كورش؛ واعتلى ابنه قمبيز العرش", "de69f4d5"], "d": ["مات كورش، وفق هيرودوت، في الحرب في بلاد الماساجيتاي (وعند كسينوفون مات في قصره)؛ وبلغ خبر موته بابل في ديسمبر 530 وأُرّخت الوثائق بـ«السنة الأولى من قمبيز». ووسّع قمبيز الإمبراطورية بفتح مصر.", "9900a295"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:0":{"b": ["مرسوم كورش: تمكن اليهود المنفيون في بابل من العودة إلى القدس، وأُذن بإعادة بناء المعبد", "715eac6b"], "d": ["أعاد كورش، بعد استيلائه على بابل، تماثيل آلهة الشعوب المنفية وسمح لها بالعودة إلى مواطنها (أسطوانة كورش). وتنقل التوراة (عزرا 1: 1-4) هذا المرسوم بشأن اليهود: يمكن للمنفيين العودة إلى القدس وإعادة بناء المعبد. وصارت المنطقة الساتربية الفارسية «يهود».", "a8c7f81c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:1":{"b": ["قبلت دول المدن الفينيقية (صور وصيدا وجبيل) الحكم الفارسي؛ وصارت نواة الأسطول الفارسي", "d9f7f277"], "d": ["بسقوط بابل دخل الساحل الفينيقي في الحكم الفارسي ضمن ساتربية «عبر النهر» (إبير-ناري). وصارت الأساطيل الفينيقية عماد القوة البحرية الفارسية؛ وحافظت صيدا وصور على حق الإدارة الداخلية المميزة.", "bb0c17fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-01-01:0":{"b": ["معركة أوبيس: هزم كورش الجيش البابلي على ضفة دجلة", "d91708c6"], "d": ["لقي الفرس بقيادة كورش الجيش الأكدي في أوبيس على دجلة وهزموه؛ وتراجع أهل بابل، وجرى النهب والمذبحة. وفتحت المعركة الطريق أمام سقوط بابل بعد أسبوعين.", "20739fbd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-10:0":{"b": ["انتقلت سيبار إلى الفرس دون قتال؛ وفرّ نبونيد", "47f6d3a5"], "d": ["بعد معركة أوبيس سقطت سيبار في يد كورش دون قتال في 14 تشريتو، وفرّ نبونيد. وسيدخل الفرس بابل بعد يومين.", "5a23a85c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-12:0":{"b": ["دخل الجيش الفارسي بقيادة غوبرياس (أوغبارو) بابل دون قتال؛ وانتهت بابل الحديثة", "f67bf0e3"], "d": ["دخل أوغبارو (غوبرياس) حاكم غوتيوم وجيش كورش بابل في 16 تشريتو دون اشتباك؛ وأُسر نبونيد. ولم تتوقف الطقوس في إيساجيلا. ودخل كورش المدينة في 3 أراحسمنو (29 أكتوبر)، وانتقلت الإمبراطورية البابلية إلى الهيمنة الفارسية.", "891c267b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-29:0":{"b": ["دخل كورش بابل؛ وانتقلت السيطرة على بابل إلى الأخمينيين وعُيّن غوبرياس واليًا", "fd45fa83"], "d": ["دخل كورش بابل في 3 أراحسمنو؛ وحيّا أهل المدينة وجعل غوبارو (غوبرياس) والي المدينة. وأُعيدت إلى أماكنها في كسليمو-أدارو تماثيل الآلهة الأكدية التي جمعها نبونيد في المدينة. وشارك ابنه قمبيز، بصفته ولي العهد، في طقس نابو.", "17d2bc46"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0546-01-01:0":{"b": ["عبر كروسوس نهر هاليس واستولى على بتيريا؛ وانتهت معركة بتيريا مع كورش دون حسم", "eee7aef1"], "d": ["عبر كروسوس نهر هاليس معتمدًا على نبوءة دلفي، وحاصر بتيريا وطرد سوريي كبادوكيا. ولما بقيت الحرب الدامية مع كورش بلا نتيجة، عاد كروسوس إلى ساردس وجمع جيوش الحلفاء؛ فقام كورش بحملة خاطفة وهزمه في ثيمبرا وسقطت ساردس.", "419ac6ed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0551-01-01:0":{"b": ["استقر نبونيد في واحة تيماء (بلاد العرب) ولم يأت إلى بابل؛ وتعذر إقامة عيد أكيتو", "2ce93701"], "d": ["بينما أقام نبونيد في واحة تيماء، انتظر ولي العهد بيلشصر بجيشه في أكد؛ ولأن الملك لم يحضر في شهر أبريل لم يدخل مردوخ بابل وتعذر إقامة عيد رأس السنة (أكيتو). وكان هذا أحد أسباب دعم كهنة المعابد لكورش ضد نبونيد.", "d1e857db"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0555-01-01:0":{"b": ["اعتلى نبونيد عرش بابل بانقلاب", "b7ab73ce"], "d": ["بعد وفاة نبوخذنصر (562) جاء أمل-مردوخ ونرغل شر-أوصر (559-556) ولاباشي-مردوخ لفترة قصيرة؛ وقام نبونيد، وهو ليس من السلالة الملكية، بانقلاب سنة 556. وأغضب ولاؤه الخاص لإله القمر سين كهنة مردوخ.", "6b2f9204"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0559-01-01:0":{"b": ["اعتلى كروسوس عرش ليديا؛ وفرض الجزية على أفسس ومدن إيونيا الإغريقية", "5544cfa4"], "d": ["بعد وفاة أبيه أليات، جعل كروسوس أفسس ثم سائر مدن إيونيا وإيوليا وكاريا الإغريقية تابعة تدفع الجزية. وليديا وحدة سياسية واحدة من غرب الأناضول حتى هاليس؛ وصارت خزينة كروسوس وهداياه لدلفي أسطورة.", "88136bde"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0584-01-01:0":{"b": ["معركة هاليس (قزل إرماق): عقد أليات وكياخسارس الصلح إثر كسوف الشمس؛ وصار هاليس حدًّا بين ليديا وميديا", "9ababdd3"], "d": ["انتهت الحرب التي دامت خمس سنوات بين أليات وملك ميديا كياخسارس بالصلح إثر كسوف للشمس وقع نهارًا؛ وتوسط ملك كيليكيا سينيسيس وملك بابل «لابينيتوس». وصار نهر هاليس حدًّا بين المملكتين، وعُدّت ميديا ممتدة حتى داخل الأناضول.", "ddab1c12"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:0":{"b": ["بدأ نبوخذنصر حصار صور؛ واستمر الحصار ثلاث عشرة سنة", "5b753ca0"], "d": ["وفق يوسيفوس (ضد أبيون 1: 156) حاصر نبوخذنصر صور ثلاث عشرة سنة في عهد الملك إيثوبعل. وانتهى الأمر بترتيب صلح/تبعية؛ وبينما دخلت صور في نفوذ بابل ظلت المدينة في الجزيرة تدير نفسها باستقلال.", "0975583d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:1":{"b": ["دُمرت القدس وأُحرق هيكل سليمان؛ وانتهت مملكة يهوذا ونُفي الشعب إلى بابل", "c9f78b2a"], "d": ["حين ثار صدقيا على بابل، استولى نبوخذنصر على القدس للمرة الثانية وأحرقها؛ وهُدم الهيكل ونُفي معظم الشعب إلى بابل (السبي البابلي). وانتهى وجود يهوذا دولة مستقلة.", "f53414ac"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0596-03-16:0":{"b": ["استولى نبوخذنصر على القدس؛ وسيق الملك يهوياكين أسيرًا وخلفه صدقيا", "55b14c31"], "d": ["حاصر الجيش البابلي «مدينة يهوذا» واستولى عليها في 2 أدارو؛ وسيق الملك يهوياكين أسيرًا إلى بابل وأُقيم مكانه صدقيا (متنيا) الذي اختارته بابل. ودخلت المدينة لأول مرة تحت السيادة البابلية.", "12a9d088"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0599-01-01:0":{"b": ["هُدمت قلاع أورارتو وأُحرقت؛ وانهارت الدولة", "6be90688"], "d": ["تدل طبقة الحريق التي تُرى في قلاع مثل كرمير بلور على أن غارة السكيثيين/الكيميريين، أو الميديين، أو عدوًا آخر دمر أورارتو قبل 600 ق.م. ولانقطاع المصادر الآشورية يبقى تاريخ ما بعد الملك الأخير روسا الثالث غير مؤكد؛ وبعد حين صارت أورارتو ساتربية أخمينية (أرمينا).", "1e7ff200"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0603-12-01:0":{"b": ["استولى نبوخذنصر الثاني على عسقلان وأسر ملكها وحولها إلى خراب", "7429839d"], "d": ["في السنة الأولى من نبوخذنصر حمل إليه «جميع ملوك بلاد حاتي» الجزية؛ وقاومت عسقلان وحدها. واستُولي على المدينة في شهر كسليمو وأُسر الملك وحُولت المدينة إلى تل خراب.", "a455db32"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0604-09-07:0":{"b": ["توفي نبوبلاصر؛ واعتلى نبوخذنصر الثاني عرش بابل", "bce88c5a"], "d": ["توفي ملك بابل نبوبلاصر بعد حكم دام 21 سنة في 8 آبو (15 أغسطس 605)؛ وعاد نبوخذنصر الذي انتصر في قرقميش إلى البلاد وجلس على العرش في 1 أولولو (7 سبتمبر 605). وربطت حملات دامت أربع سنوات بلاد حاتي (سوريا-فلسطين) ببابل.", "b519ffaa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:0":{"b": ["سقطت حران؛ وانسحب آشور-أوبليط الثاني إلى مصر", "b2d122c2"], "d": ["كان آخر ملوك آشور آشور-أوبليط الثاني قد انسحب إلى حران بعد سقوط نينوى؛ وحين زحف الميديون والبابليون على حران، تركت القوات الآشورية والمصرية المدينة وانسحبت إلى ما وراء الفرات. واستولى نبوبلاصر على حران ونهبها.", "cb81464b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:1":{"b": ["اعتلى أليات عرش ليديا؛ وطرد الكيميريين من الأناضول ووسّع المملكة", "160e291d"], "d": ["طهّر أليات في عهده الطويل غرب الأناضول من الكيميريين وحارب ميليتوس؛ ونقل حدود المملكة إلى وسط الأناضول حتى التقى بميديا على حدود هاليس.", "54aee50b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0613-01-01:0":{"b": ["عقد كياخسارس ونبوبلاصر معاهدة تحالف أمام آشور", "650f0e5a"], "d": ["حين استولى الميديون على آشور، التقى ملك بابل نبوبلاصر الذي تأخر بملك ميديا قرب المدينة وأقام التحالف. ووفق بيروسوس توطد الرباط بزواج نبوخذنصر من أميتيس ابنة كياخسارس.", "450ae215"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0624-01-01:0":{"b": ["اعتلى كياخسارس (أوماكشتار) عرش ميديا", "67896ea0"], "d": ["وفق تقليد هيرودوت حكم كياخسارس أربعين سنة، ووحّد ميديا وخرج في حملة على آشور. والتحالف مع بابل (614) والاستيلاء على نينوى (612) في عهده؛ وبلغت ميديا في هذه السنوات أوسع حدودها.", "4094aac8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0630-01-01:0":{"b": ["توفي آشوربانيبال؛ وبدأ الصراع على العرش في آشور وتمرد بابل", "dbe19d8c"], "d": ["ترك موت آشوربانيبال آشور منقسمة بين وليين للعهد. وثار حكام بابل على سين-شوم-ليشير وسين-شار-إشكون؛ وبدأ انهيار الإمبراطورية في غضون عشر سنوات.", "9537e9f3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0644-01-01:0":{"b": ["دمر آشوربانيبال سوسة؛ وانهارت مملكة عيلام الحديثة", "cb341293"], "d": ["عقابًا على تمرد عيلام على آشور مع بابل، استولى آشوربانيبال على سوسة ونهبها، وهدم المعابد، ونقل تماثيل الآلهة إلى نينوى. ودخلت عيلام في نفوذ فارس/أنشان في صورة إمارات شبه مستقلة.", "327f1322"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0647-01-01:0":{"b": ["خضعت بابل لآشوربانيبال بعد تمرد شمش-شوم-أوكين", "d6964932"], "d": ["ثار شمش-شوم-أوكين ملك بابل، أخو آشوربانيبال، على آشور سنة 652؛ ومنحه حلفاؤه العيلاميون والعرب دعمًا مؤقتًا. وانتهت الحرب التي دامت أربع سنوات بسقوط بابل، ومات شمش-شوم-أوكين.", "b038173f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0651-01-01:0":{"b": ["نهب الكيميريون ساردس؛ ومات غيغيس", "950e5f80"], "d": ["امتد الغزو الكيميري بعد غورديون (696/695) إلى ليديا أيضًا ونهب المدينة السفلى لساردس. وتفيد المصادر الآشورية أن ملك ليديا غوغو (غيغيس) طلب العون الآشوري ضد الكيميريين؛ ومات غيغيس أثناء هذه الحروب أو بعدها.", "93736177"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0652-01-01:0":{"b": ["معركة تيل-توبا/أولاي: هزم آشوربانيبال ملك عيلام تيومان وقتله", "177e87cf"], "d": ["هزم آشوربانيبال ملك عيلام تيومان على ضفة أولاي (كارون/كرخه) قرب سوسة وقتله؛ وحُمل رأسه إلى نينوى. وهيأت المعركة نهاية دور عيلام في الصراع الآشوري-البابلي.", "3aa28a86"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0663-01-01:0":{"b": ["نهب آشوربانيبال طيبة (ثيبس)", "179269c7"], "d": ["بعد وفاة آسرحدون، حين اشتعل التمرد الكوشي في مصر من جديد مع تانوتامون، دخل آشوربانيبال صعيد مصر ونهب طيبة. وجد آشور صعوبة في الإمساك بمصر فعليًا وانسحب بعد وقت قصير.", "c292bcf0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0676-01-01:0":{"b": ["دمر آسرحدون صيدا وأعاد بناءها باسم كار-آسرحدون", "bd713ae6"], "d": ["حين ثار ملك صيدا عبدي-ملكوتي على آشور، هدم آسرحدون المدينة، وقتل ملكها بقطع رأسه، وأقام مكان المدينة مركز ولاية آشورية باسم كار-آسرحدون («ميناء آسرحدون»).", "2a506319"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0684-01-01:0":{"b": ["أطاح غيغيس بكاندولس وأسس أسرة المرمناد", "37e46a38"], "d": ["وفق هيرودوت، أطاح غيغيس، وكان من حرس القصر، بالملك كاندولس واستولى على عرش ليديا وأسس أسرة المرمناد. وبعد انهيار فريجيا بغزو الكيميريين، بدأت ليديا تصير القوة الرئيسة في غرب الأناضول.", "e477b6b5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0688-01-01:0":{"b": ["دمر سنحاريب بابل ونهب المعابد وأرسل مياه الفرات إلى المدينة", "82265d98"], "d": ["لتمردات بابل المتكررة استولى سنحاريب على المدينة وهدمها، وأخذ تمثال مردوخ، وأرسل مياه القناة إلى المدينة. وبقيت بابل مهدمة نصف قرن حتى إصلاح آسرحدون؛ والتدمير أشد خطوات سياسة آشور تجاه بابل.", "e4312fee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:0":{"b": ["غزا سنحاريب يهوذا؛ واستولى على لاخيش وحاصر القدس", "dc11fa2d"], "d": ["أخمد سنحاريب تمرد حزقيا على آشور، فاستولى على ست وأربعين مدينة من يهوذا وفتح لاخيش وحاصر القدس. ودفع حزقيا جزية ثقيلة فأنقذ المدينة؛ وتبين نقوش لاخيش البارزة في نينوى هذه الحملة.", "ebc2ce02"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:1":{"b": ["استولى سنحاريب على صيدا؛ وفرّ الملك لولي إلى قبرص", "41bb1358"], "d": ["أخضع سنحاريب المدن الفينيقية في 701: فرّ ملك صيدا لولي (إلولايوس) إلى قبرص، وانتقلت المدن التابعة لصيدا وصور إلى آشور. وبهذه الفتوحات أُمّن الساحل الغربي قبل حملة يهوذا.", "3b2c6518"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0704-01-01:0":{"b": ["قُتل سرجون الثاني في معركة في تابال؛ واعتلى سنحاريب العرش", "2f6ae581"], "d": ["قُتل سرجون الثاني في حملة على ملك تابال غوردي في الأناضول ولم يمكن استرداد جثمانه. ونقل ابنه سنحاريب قصره إلى نينوى؛ وهُجرت مدينة دور-شروكين التي أقامها أبوه وثارت ولايات عديدة.", "21ee2771"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0711-01-01:0":{"b": ["استولى سرجون الثاني على ملطية (ميليد)؛ ونُفي غونزينانو", "3ef6a5c9"], "d": ["هُزم ملك ميليد (ملطية) غونزينانو على يد سرجون لتعاونه مع تابال وأورارتو، وصارت مملكته ولاية آشورية. وهكذا انتهت الهيمنة الحثية الحديثة في شرق الأناضول.", "281f75fd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0713-01-01:0":{"b": ["دخل سرجون الثاني أورارتو: هُزم روسا الأول ونُهبت موساصير وأُخذ تمثال خالدي", "38992d24"], "d": ["نهبت حملة سرجون الثامنة أورارتو من محيط بحيرة أرومية نزولًا؛ وسُلب معبد خالدي في موساصير. وانتحر الملك روسا الأول أمام الهزيمة الثقيلة (وفق التقليد). ولم تقم أورارتو بعد ذلك بمسعى كبير ضد آشور.", "7d05af4c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0716-01-01:0":{"b": ["استولى سرجون الثاني على قرقميش؛ وصارت مملكة بيسيريس ولاية آشورية", "cfcc3ee4"], "d": ["حاول ملك قرقميش بيسيريس إقامة حلف مع ميداس (ميتا) ضد آشور؛ فاستولى سرجون على المدينة وقام بعمليات نفي. وانتهى استقلال قرقميش الذي دام قرنًا ونصفًا وانتقلت حدود الفرات إلى آشور.", "87f1f2e6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0719-01-01:0":{"b": ["هزم سرجون الثاني حماة (حماث)؛ وقتل ياو-بيدي في قرقر وحوّل المملكة إلى ولاية", "aeca8edc"], "d": ["كان ملك حماة ياو-بيدي على رأس تحالف سوريا-فلسطين ضد سرجون؛ فهزمه سرجون في قرقر ودمر المدينة، وحُولت حماة إلى ولاية آشورية.", "70e2d509"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0732-01-01:0":{"b": ["انتزع تغلث فلاسر الثالث الجليل وجلعاد من إسرائيل وجعلهما ولايتين آشوريتين", "0b59ead2"], "d": ["حين تمردت إسرائيل فقح مع دمشق على آشور، حوّل تغلث فلاسر الثالث شمال إسرائيل (الجليل وجلعاد ومحيط مجدو) إلى ولايات آشورية ونفى أهلها؛ وخلف هوشع فقح. وانحصرت مملكة إسرائيل في السامرة والمنطقة الجبلية المحيطة بها.", "28d3a30e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0733-01-01:0":{"b": ["استولى تغلث فلاسر الثالث على غزة؛ وصار ساحل فلسطين تحت السيطرة الآشورية", "1c89131f"], "d": ["توجه تغلث فلاسر إلى الشريط الساحلي لفلسطين، وأجبر ملك غزة حانونو على الفرار إلى مصر، وضم المدينة إلى نفوذه. وصارت دول المدن الفلسطينية في السنوات التالية شريطًا تابعًا لآشور.", "ff623a4d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0742-01-01:0":{"b": ["هزم تغلث فلاسر الثالث ملك أورارتو سردوري الثاني قرب أرفاد", "7478a232"], "d": ["انتهت محاولة سردوري الثاني توجيه دول سوريا نحو الاستقلال بانتصار تغلث فلاسر الثالث. وفقدت أورارتو نفوذها في سوريا؛ ولم تترك آشور أي منافس لها في الأناضول وسوريا.", "b851f23b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0744-01-01:0":{"b": ["اعتلى تغلث فلاسر الثالث العرش؛ وأُقيم نظام الولايات الآشوري", "b5889059"], "d": ["أرسى تغلث فلاسر الثالث، الذي تولى العرش بتمرد في كالحو، نظام الولايات بإحلال الولاة الآشوريين محل الممالك التابعة؛ وربط بابل بالاتحاد الشخصي، وقاد حملات على دمشق وغزة وإسرائيل. ومنه جاء نظام الإدارة الذي استخدمته الإمبراطوريات اللاحقة (بابل وفارس والسلوقيون).", "7deb8187"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0795-01-01:0":{"b": ["هزم أداد-نيراري الثالث ملك دمشق ماري وأخذ منه جزية", "3e01dbfa"], "d": ["هزم أداد-نيراري الثالث ملك دمشق ماري (بر-هداد) وأخذ جزية كبيرة؛ وضعفت القوة الداخلية لآرام-دمشق وتنفست إسرائيل الصعداء حينًا.", "c5c0a66d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0809-01-01:0":{"b": ["وسّع مينوا أورارتو من بحيرة فان إلى وادي آراس وبحيرة أرومية", "d77231e4"], "d": ["في عهد مينوا وابنه أرغيشتي الأول تحولت أورارتو من مركز بحيرة فان إلى مملكة تشمل الأرض العليا كلها حتى محيط آراس وبحيرة أرومية. وتوسعت توشبا (فان) بالاستيطان الجديد وأعمال الري.", "289fc554"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0839-01-01:0":{"b": ["أعلن ميشع ملك موآب استقلاله عن إسرائيل (مسلة ميشع)", "e9c264b2"], "d": ["تروي مسلة ميشع خلاص ميشع ملك موآب من وصاية إسرائيل وانتصاراته على أسرة عمري. وتبين التوراة والمسلة معًا الفترة التي ضعفت فيها أسرة عمري.", "ffefe5fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0840-01-01:0":{"b": ["هزم شلمنصر الثالث حزائيل وحاصر دمشق؛ ودفع ملك إسرائيل ياهو جزية", "93aacc56"], "d": ["هزم شلمنصر الثالث ملك آرام-دمشق حزائيل في جبل شانير (حرمون) وحاصر دمشق؛ ويُصوَّر ملك إسرائيل ياهو في المسلة السوداء يقدم الجزية لآشور. وتفرق تحالف قرقر وصارت آشور القوة المهيمنة في الغرب.", "2992ec0c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0852-01-01:0":{"b": ["معركة قرقر: واجه شلمنصر الثالث تحالف دمشق وحماة وإسرائيل", "9a736e92"], "d": ["حارب شلمنصر الثالث في قرقر تحالف اثني عشر ملكًا بينهم ملك دمشق حدد-عزر (أدد-إدري) وملك حماة إرخوليني وملك إسرائيل أخآب. ومع أن الوثائق الآشورية تدعي النصر فقد اضطر إلى ترك تقدمه؛ وأوقف التحالف آشور سنوات.", "524874c7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0857-01-01:0":{"b": ["بدأ شلمنصر الثالث حملات على أورارتو (أرامي)؛ وظهرت أورارتو لأول مرة في المصادر الآشورية", "375ce993"], "d": ["زحف شلمنصر الثالث في السنوات الأولى من حكمه إلى أراضي الملك أرامي في أورارتو؛ وتذكر حوليات آشور أورارتو في هذه الحملات لأول مرة باسم «بلاد أورارتو». وهذا أول سجل مؤرخ للدولة التي ستكون المنافس الرئيس لآشور في هذه المنطقة في القرون التالية.", "759a75b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0876-01-01:0":{"b": ["عبر آشورناصربال الثاني الفرات وأخذ جزية من قرقميش ودول الحثيين الحديثين/الآراميين", "5e385948"], "d": ["عبر آشورناصربال الثاني الفرات في حملته الغربية وبلغ قرقميش وباتينا والساحل الفينيقي وجمع الجزية. وهذه الحملة بداية سيرورة ربط دول المدن الحثية الحديثة-الآرامية بآشور.", "8432c2ea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0878-01-01:0":{"b": ["جعل آشورناصربال الثاني كالحو (نمرود) عاصمة آشور الجديدة", "fbb17248"], "d": ["حوّل آشورناصربال الثاني كالحو، وهي بلدة صغيرة، إلى عاصمة كبيرة بـ47 ألف عامل؛ وبُني القصر الشمالي الغربي في مدينة اتسعت ستة أضعاف آشور. وظلت كالحو عاصمة آشور حتى 706.", "5a0f00b6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0879-01-01:0":{"b": ["جعل عمري السامرة عاصمة؛ وضم موآب", "e060c4b7"], "d": ["أسس عمري أول دولة حقيقية لإسرائيل: فتح شرق الأردن (بما فيه موآب)، وقوّى قلاع الحدود، وجعل السامرة العاصمة الجديدة. وربط ابنه أخآب إسرائيل بالتجارة الفينيقية بزواجه من إيزابل ابنة إثبعل ملك صيدا.", "14f7df9d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0910-01-01:0":{"b": ["اعتلى أداد-نيراري الثاني العرش؛ وبدأ نهوض آشور الحديثة", "e6887ba9"], "d": ["بعد تراجع دام نحو قرن ونصف، بدأ أداد-نيراري الثاني يجمع أراضي آشور من جديد؛ وقام بحملات على الآراميين وعلى حدود بابل. وفي عهد خلفائه آشورناصربال الثاني وشلمنصر الثالث وُلدت الإمبراطورية الآشورية الحديثة.", "beab377b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0929-01-01:0":{"b": ["انقسمت مملكة سليمان؛ وأسس يربعام الأول مملكة إسرائيل في الشمال", "cfbbc025"], "d": ["وفق التوراة، أدت زيادة رحبعام ابن سليمان الضرائب عند وفاة أبيه إلى انفصال القبائل العشر في الشمال؛ فاختير يربعام ملكًا وجعل ترصة عاصمة. واستمرت يهوذا في الجنوب مع أسرة داود. وبدأ التاريخ المنفصل للدولتين.", "7e2e066d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1099-01-01:0":{"b": ["زحف تغلث فلاسر الأول غربًا وأخذ جزية من المدن الفينيقية على ساحل المتوسط", "0b2822b7"], "d": ["بلغ تغلث فلاسر الأول غابات لبنان وموانئ أرواد وجبيل وصيدا وجمع الجزية، وأبحر في المتوسط بسفينة. ولأنه لم تكن بعد انهيار الحثيين قوة تستطيع إيقافه في الغرب، فإن هذه الحملات تبدأ توجه آشور نحو الغرب.", "60dc7824"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1109-01-01:0":{"b": ["زحف نبوخذنصر الأول (إيسين الثانية) على عيلام واسترد تمثال مردوخ", "3c551c03"], "d": ["زحف نبوخذنصر الأول من أسرة إيسين الثانية على عيلام وأعاد إلى بابل تمثال مردوخ الذي أخذه كوتير-ناحوني. ويُذكر النصر في تاريخ بابل باسم «عودة مردوخ» وجعل عبادة مردوخ مركزية.", "fdd1a6a4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1157-01-01:0":{"b": ["نهب شوتروك-ناحوني بلاد بابل؛ ونقل مسلتي حمورابي ونرام سين إلى سوسة", "3d499fcc"], "d": ["هاجم ملك عيلام الوسطى شوتروك-ناحوني بابل ونهب مدنًا مثل سيبار؛ ونُقلت إلى سوسة غنائم مثل مسلة شريعة حمورابي ومسلة نصر نرام سين. أما ابنه كوتير-ناحوني فأنهى الأسرة الكاسية سنة 1155 ق.م.", "2179c21e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1174-01-01:0":{"b": ["حافظ كوزي-تشوب في قرقميش بلقب «الملك العظيم» على الإرث الحثي", "0bda7a64"], "d": ["بعد سقوط حاتوشا ظلت مملكة قرقميش قائمة على يد فرع من الأسرة الحثية؛ وأعلن كوزي-تشوب نفسه «الملك العظيم». وكونت دول المدن اللوفية-الآرامية مثل قرقميش وملطية (ميليد) وحماة عالم «الحثيين الحديثين».", "214de0bd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1179-01-01:0":{"b": ["احترقت حاتوشا وهُجرت؛ وانهارت الإمبراطورية الحثية", "64d58b6b"], "d": ["أُحرقت مدينة حاتوشا وهُجرت في عهد آخر ملوك الحثيين شوبيلوليوما الثاني؛ وهي جزء من انهيار العصر البرونزي المتأخر الذي جرى في سياق المجاعة والصراع الداخلي وشعوب البحر. وترك الحثيون الدولة لدول المدن الحثية الحديثة مثل قرقميش وملطية.", "34ee5436"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1224-01-01:0":{"b": ["فتح تكولتي-نينورتا الأول ملك آشور بابل؛ وحمل تمثال مردوخ إلى آشور", "2cc39251"], "d": ["هزم تكولتي-نينورتا الأول (نحو 1243-1207) الملك الكاسي كاشتيلياش الرابع واستولى على بابل، وهدم أسوارها، ونقل تمثال مردوخ إلى آشور. وبقيت بابل نحو سبع سنوات تحت سيطرة آشور؛ وصارت آشور أقوى دولة في العصر الأوسط.", "8abcb249"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1259-01-01:0":{"b": ["أسس شلمنصر الأول مدينة كالحو (نمرود)", "e0bf279a"], "d": ["أسس شلمنصر الأول كالحو على ضفة دجلة؛ وستصير المدينة عاصمة آشور بإعادة تأسيسها على يد آشورناصربال الثاني في 883.", "8a213755"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1269-01-01:0":{"b": ["ضم شلمنصر الأول خانيغلبات؛ وزالت ميتاني", "88620feb"], "d": ["أخمد شلمنصر الأول تمرد ملك خانيغلبات شاتوارا الثاني وضم البلاد مباشرة إلى آشور ونفى أهلها. وأُزيلت دولة ميتاني من مسرح التاريخ بضربات الحثيين والآشوريين المتعاقبة.", "c6c8615e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1274-01-01:0":{"b": ["أسس أونتاش-نابيريشا مدينة دور-أونتاش (تشوغا زنبيل) وزقورتها", "117fbc13"], "d": ["أسس ملك عيلام الوسطى أونتاش-نابيريشا قرب سوسة مدينة عبادة ذات زقورة للإله إنشوشيناك؛ واستُخدمت المدينة أكثر من قرنين مع أنها بقيت غير مكتملة. وتشوغا زنبيل أفضل زقورة محفوظة في إيران.", "fe8afd09"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1294-01-01:0":{"b": ["هزم أداد-نيراري الأول خانيغلبات (بقية ميتاني) وجعلها تابعة", "1adb5969"], "d": ["هزم أداد-نيراري الأول، حفيد آشور-أوبليط الأول، مملكة خانيغلبات الباقية من ميتاني التي ضربها الحثيون وأدخلها في التبعية؛ وفي عهد الملك التالي شلمنصر الأول حُولت البلاد إلى ولاية آشورية. وامتدت آشور حتى الفرات.", "24941786"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1317-01-01:0":{"b": ["هزم مورسيلي الثاني أرزاوا (غرب الأناضول) وقسّمها", "4a204e42"], "d": ["هزم مورسيلي الثاني في بداية حكمه كونفدرالية أرزاوا القوية في غرب الأناضول وقسمها إلى ممالك دنيا وجعلها تابعة للحثيين. واقتربت حدود الحثيين في غرب الأناضول من ساحل إيجة.", "c2f9977c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1327-01-01:0":{"b": ["عيّن شوبيلوليوما أبناءه على مملكتي قرقميش وحلب", "1c5bc8b3"], "d": ["أدار شوبيلوليوما سوريا التي فتحها بـ«ملوك» من الأسرة الحثية: أُعطيت قرقميش وحلب لأبنائه. وستواصل نيابة الملك في قرقميش وجودها نحو 500 سنة حتى بعد الانهيار الحثي.", "40eeaf84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1344-01-01:0":{"b": ["هزم شوبيلوليوما الأول ميتاني (توشراتا) واستولى على حلب وقرقميش؛ وانتقلت شمال سوريا إلى الحثيين", "52f9627a"], "d": ["هزم شوبيلوليوما ملك ميتاني توشراتا واستولى على مدن سوريا بما فيها قرقميش وحلب؛ وضُم غرب أراضي ميتاني إلى الإمبراطورية الحثية. وسهّلت المشكلات الداخلية لمصر في عهد إخناتون هذا التوسع.", "c80de115"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:0":{"b": ["احتلت بابل الكاسية في دبلوماسية العمارنة مكان قوة كبرى مكافئة لمصر", "5e7b31a2"], "d": ["كان ملوك الكاسيين كاداشمان-إنليل الأول وبورنابورياش الثاني ضمن رابطة «الملوك العظام» التي مارست دبلوماسية المصاهرة والهدايا مع فراعنة مصر. وتعدّد رسائل العمارنة أعضاء هذه الرابطة بوصفهم مصر وبابل وميتاني وحاتي وآشور.", "8ecd665d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1354-01-01:0":{"b": ["اعتلى شوبيلوليوما الأول العرش الحثي؛ وبدأ عصر المملكة الحديثة", "58b301b7"], "d": ["شوبيلوليوما الأول مؤسس المملكة الحثية الحديثة ومبتكر جيش العربات الحربية المحترف. وحوّل حكمه الذي دام خمسًا وثلاثين سنة الحثيين إلى إمبراطورية ممتدة من الأناضول إلى سوريا.", "72c7f3af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1362-01-01:0":{"b": ["تحرر آشور-أوبليط الأول من وصاية ميتاني؛ وصارت آشور مستقلة و«ملكًا عظيمًا»", "5f280058"], "d": ["استفادت آشور، التابعة لميتاني، في عهد آشور-أوبليط الأول من الضربة التي وجهها الحثيون إلى ميتاني فنالت استقلالها. وكتب الملك إلى فرعون مصر بلقب «الملك العظيم»؛ وهذا يبدأ عصر آشور الوسيط.", "690fb956"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1399-01-01:0":{"b": ["التحالف الميتاني-المصري: صلح أرتاتاما الأول وتحتمس الرابع، وذهبت أميرة ميتانية عروسًا إلى مصر", "017f13d2"], "d": ["بعد العداء عقد ملك ميتاني أرتاتاما الأول صلحًا مع فرعون مصر وأرسل ابنته إلى مصر. وأقام التحالف توازنًا مصريًا-ميتانيًا في شمال سوريا ضد التهديد الحثي وهيأ دبلوماسية عصر العمارنة.", "72df719d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1499-01-01:0":{"b": ["تأسست مملكة ميتاني (خانيغلبات) في منطقة الخابور-الفرات", "04920d91"], "d": ["نهضت مملكة الحوريين-ميتاني في بلاد ما بين النهرين العليا في فراغ انهيار بابل القديمة وتراجع الحثيين. وكانت العاصمة واشوكاني؛ وجعلت المملكة آشور وشمال سوريا تابعتين في بضعة عقود.", "c6aa0237"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1524-01-01:0":{"b": ["اعتلى تليبينو العرش وأصدر مرسومًا؛ وحُددت العلاقات مع كيزواتنا بمعاهدة", "e1f0895b"], "d": ["أعاد تليبينو بناء القانون الحثي بمرسومه الذي نظّم الإرث؛ وعدّت المعاهدة الموقعة مع كيزواتنا البلاد شريكًا مستقلًا لا تابعًا. وبهذا المرسوم تنتهي المملكة الحثية القديمة.", "47b927f1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1569-01-01:0":{"b": ["أعادت الأسرة الكاسية في عهد أغوم-كاكريمي بناء بابل؛ وعاد تمثال مردوخ من الأسر الحثي", "0d525e02"], "d": ["بعد نهب الملك الحثي مورسيلي الأول بابل (1595 ق.م) سيطرت الأسرة الكاسية على المدينة. وتروي الرواية أن أغوم-كاكريمي استرد من الحثيين تمثال مردوخ؛ وتبنّى الكاسيون ثقافة بابل بسرعة وأسسوا أسرة ستدوم نحو أربعة قرون.", "d91fcc1e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1589-01-01:0":{"b": ["اغتيل مورسيلي الأول؛ وضعفت المملكة الحثية بالخلافات الداخلية", "fa5a6ea9"], "d": ["عند عودته من بابل قتل مورسيلي الأول صهره هانتيلي وزيدانتا. وتركت صراعات العرش والقوة الحورية/الميتانية الجديدة المملكة ضعيفة نصف قرن؛ ولم يتمكن تليبينو من إقامة النظام إلا نحو 1525 ق.م.", "90711b8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1599-01-01:0":{"b": ["استولى مورسيلي الأول على حلب (يمحاض) ودمرها", "78c81e82"], "d": ["استولى مورسيلي الأول، حفيد حاتوشيلي وخليفته، على مملكة حلب التي قاومت عشرات السنين ودمرها. وأتاح انتهاء يمحاض التفوق الحثي في شمال سوريا وفتح طريق حملة مورسيلي على بابل.", "327a9d55"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1629-01-01:0":{"b": ["عبر حاتوشيلي الأول طوروس وضم كيزواتنا (كيليكيا) إلى حدوده، وحارب مملكة حلب", "4c4b5e22"], "d": ["أوصلت حملات حاتوشيلي الأول المملكة الحثية إلى البحر؛ ودخلت كيزواتنا (سهل كيليكيا) في النفوذ الحثي، وبدأت حرب طويلة مع حلب (يمحاض). واستُولي على مدن مثل ألالاخ أو دُمرت.", "71f55427"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1749-01-01:0":{"b": ["جعل أنيتا ملك كوشارا نيشا (كانش) عاصمة ودمر حاتوشا", "1eea344b"], "d": ["وفق نص أنيتا، وحّد أنيتا ملك كوشارا عدة دول مدن في الأناضول، وجعل نيشا (كانش) عاصمة، ودمر حاتوشا وألقى عليها لعنة. ويُذكر بوصفه أول مسعى سياسي حثي للتوحيد.", "01d03ad4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1753-01-01:0":{"b": ["أُقيمت مسلة شريعة حمورابي", "b4c80ab9"], "d": ["كُتبت مدونة حمورابي القانونية ذات المواد البالغ عددها 282 على مسلة من البازلت وأُقيمت في المعابد. ونُقلت المسلة إلى سوسة على يد ملك عيلام شوتروك-ناحوني في القرن 12 ق.م، وعُثر عليها هناك سنة 1901؛ وهي اليوم في اللوفر.", "e37255ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1760-01-01:0":{"b": ["استولى حمورابي على ماري؛ وهدم أسوارها بعد سنتين", "4f4114b4"], "d": ["استولى حمورابي على ماري التي كان يحكمها حليفه السابق زمري-ليم، وهدم أسوار المدينة أيضًا. وتدمير ماري نهاية المملكة الأمورية في وادي الفرات؛ وصارت بابل القوة المهيمنة شمالًا حتى آشور وإشنونا.", "5bbc9e99"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1762-01-01:0":{"b": ["استولى حمورابي على لارسا وهزم ريم-سين الأول؛ وارتبطت جنوب بلاد الرافدين ببابل", "6f95399b"], "d": ["حارب حمورابي في السنة نفسها عيلام وإشنونا وتوجه إلى لارسا وهزم ريم-سين الأول. وانضمت جنوب بلاد الرافدين (سومر) إلى مملكة بابل؛ وتُسمى هذه المنطقة منذ ذلك اليوم «بلاد أكد» (بابليا).", "4be6f89b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1793-01-01:0":{"b": ["فتح ملك لارسا ريم-سين الأول إيسين؛ وانتهت أسرة إيسين", "88964ca6"], "d": ["فتح ملك لارسا ريم-سين الأول إيسين، منافسته منذ زمن طويل، واستولى عليها وجعل لارسا القوة الكبرى الوحيدة في جنوب بلاد الرافدين. وهكذا انتهت أسرة إيسين بعد حكم دام 223 سنة.", "f1928082"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1794-01-01:0":{"b": ["استولى شمشي-أداد على ماري وعيّن ابنه يسماخ-أداد ملكًا عليها", "a428b4eb"], "d": ["استولى شمشي-أداد ملك آشور وإيكالاتوم على مملكة ماري على الفرات، وأزال أسرة ياخدون-ليم، وعيّن ابنه الصغير يسماخ-أداد على ماري. وصارت «مملكة بلاد الرافدين العليا» بذلك إمبراطورية أمورية ممتدة من زاغروس إلى الفرات.", "8d0ec094"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1821-01-01:0":{"b": ["اعتلى ريم-سين الأول عرش لارسا", "a24e891e"], "d": ["ربط ريم-سين الأول (نحو 1822-1763)، في حكمه الذي دام 60 سنة، الوركاء وإيسين ونيبور بلارسا، وجعل أسرة من أصل عيلامي الحاكم الوحيد للجنوب. وانتهى عهده باستيلاء حمورابي على لارسا (1763 ق.م).", "dcc872e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1835-01-01:0":{"b": ["دُمرت الطبقة الثانية من كاروم كانش (كولتيبه)؛ ونهض أنيتا بين دول مدن الأناضول", "084f9472"], "d": ["تدمير الطبقة الثانية في كولتيبه نهاية العصر الكبير الأول لكاروم التجار الآشوريين. وبعد ذلك جعل أنيتا ملك كوشارا كانش عاصمة وفتح طريق التأسيس السياسي للحثيين.", "c3514f06"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1899-01-01:0":{"b": ["أسس التجار الآشوريون كاروم كانش (كولتيبه)؛ وامتدت شبكة التجارة الآشورية القديمة إلى الأناضول", "b81b0cb9"], "d": ["أسس تجار مدينة آشور في الأناضول كاروم (مستعمرات تجارية) مركزها كانش لتجارة النحاس والقصدير والأقمشة. والآلاف من الألواح المسمارية المكتشفة في كولتيبه هي بداية الكتابة والتاريخ المكتوب في الأناضول.", "2311e7a7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1924-01-01:0":{"b": ["انتزع غونغونوم ملك لارسا أور من إيسين", "6c857c01"], "d": ["جعل غونغونوم (نحو 1932-1906) لارسا قوة كبرى لأول مرة: يُعلن في أسماء سنواته الاستيلاء على أور والنجاح ضد عيلام. وبانتقال أور بدأ انحصار إيسين في الشمال.", "0108b079"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1960-01-01:0":{"b": ["أسس نبلانوم أسرة أمورية مستقلة في لارسا", "86a820f8"], "d": ["أعلن الزعيم الأموري نبلانوم سيادته في لارسا فأسس ثاني أكبر أسرة في الجنوب بعد أور الثالثة. وفي تنافس دام قرونًا مع إيسين ستربط لارسا بنفسها أور أولًا ثم الوركاء وإيسين.", "ab808712"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2001-01-01:0":{"b": ["أخرج إشبي-إرا الحامية العيلامية من أور؛ وأخضع إيسين وأور ونيبور", "a68018b2"], "d": ["بعد استيلاء عيلام على أور (نحو 2004) أخرج إشبي-إرا الحامية العيلامية من أور، وربط أور ونيبور بإيسين. وحملت إيسين، بوصفها الوريثة السياسية لأور، لقب ملك سومر وأكد قرونًا.", "77884c9c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2016-01-01:0":{"b": ["انفصل إشبي-إرا في إيسين عن أور الثالثة؛ وتأسست أسرة إيسين", "8d9e3116"], "d": ["أسس إشبي-إرا، قائد إيبي-سين، أسرة مستقلة في إيسين حين انهارت دولة أور الثالثة. وصارت إيسين، بوصفها الأسرة التي تواصل الإرث الثقافي لأور وتحمل لقب «ملك سومر وأكد»، إحدى القوى الرئيسة في جنوب بلاد الرافدين نحو 220 سنة.", "b28db4ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2025-01-01:0":{"b": ["اعتلى إيبي-سين العرش آخر ملوك أور الثالثة", "0afa3ef5"], "d": ["أدار إيبي-سين (نحو 2028-2004)، خليفة شو-سين، سيرورة تفكك الدولة: ضغط الأموريين، والمجاعة، وفقدان سوسة والولايات الشرقية، واستقلال إشبي-إرا في إيسين. وانتهى حكمه بنهب أور بهجوم عيلام/سيماشكي.", "19e45ed0"]}
});
